package movie.swp391.controller;

import jakarta.validation.Valid;
import lombok.RequiredArgsConstructor;
import movie.swp391.request.CinemaRequest;
import movie.swp391.response.CinemaAdminResponse;
import movie.swp391.response.CityOptionResponse;
import movie.swp391.response.common.BaseResponse;
import movie.swp391.service.CinemaAdminService;
import org.springframework.http.ResponseEntity;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.web.bind.annotation.*;

import java.util.List;

@RestController
@RequestMapping("/api/admin/cinemas")
@RequiredArgsConstructor
@PreAuthorize("hasAnyRole('ADMIN','EMPLOYEE')")
public class CinemaAdminController {

    private final CinemaAdminService cinemaAdminService;

    @GetMapping
    public ResponseEntity<BaseResponse<List<CinemaAdminResponse>>> getAllCinemas() {
        return ResponseEntity.ok(cinemaAdminService.getAllCinemas());
    }

    @PostMapping
    public ResponseEntity<BaseResponse<CinemaAdminResponse>> createCinema(@Valid @RequestBody CinemaRequest request) {
        return ResponseEntity.ok(cinemaAdminService.createCinema(request));
    }

    @PutMapping("/{cinemaId}")
    public ResponseEntity<BaseResponse<CinemaAdminResponse>> updateCinema(
            @PathVariable Integer cinemaId,
            @Valid @RequestBody CinemaRequest request) {
        return ResponseEntity.ok(cinemaAdminService.updateCinema(cinemaId, request));
    }

    @DeleteMapping("/{cinemaId}")
    public ResponseEntity<BaseResponse<String>> deleteCinema(@PathVariable Integer cinemaId) {
        return ResponseEntity.ok(cinemaAdminService.deleteCinema(cinemaId));
    }

    @GetMapping("/cities")
    public ResponseEntity<BaseResponse<List<CityOptionResponse>>> getAllCities() {
        return ResponseEntity.ok(cinemaAdminService.getAllCities());
    }
}

package movie.swp391.controller;

import jakarta.validation.Valid;
import lombok.AccessLevel;
import lombok.RequiredArgsConstructor;
import lombok.experimental.FieldDefaults;
import movie.swp391.entity.Coupon;
import movie.swp391.request.ApplyCouponRequest;
import movie.swp391.request.CreateCouponRequest;
import movie.swp391.response.ApiResponse;
import movie.swp391.response.ApplyCouponResponse;
import movie.swp391.service.CouponService;
import org.springframework.web.bind.annotation.*;
import org.springframework.security.access.prepost.PreAuthorize;

import java.util.List;

@RestController
@RequestMapping("/api/coupon")
@RequiredArgsConstructor
@FieldDefaults(level = AccessLevel.PRIVATE, makeFinal = true)
public class CouponController {

    CouponService couponService;


    @PostMapping("/create-coupon")
    public ApiResponse<Coupon> createCoupon(@RequestBody @Valid CreateCouponRequest request) {
        return ApiResponse.<Coupon>builder()
                .result(couponService.createCoupon(request))
                .message("Success")
                .status(200)
                .build();
    }

    @PostMapping("/apply")
    public ApiResponse<ApplyCouponResponse> applyCoupon(@RequestBody @Valid ApplyCouponRequest request) {
        return ApiResponse.<ApplyCouponResponse>builder()
                .result(couponService.applyCoupon(request))
                .message("Success")
                .status(200)
                .build();



    }
    @PutMapping("/on-off-coupon")
    public ApiResponse<String> onOffCoupon(@RequestBody List<Integer> couponIds) {
        couponService.turnOnOffCoupon(couponIds);
        return ApiResponse.<String>builder()
                .result("Cập nhật thành công")
                .message("Success")
                .build();
    }
    @GetMapping("/view-all")
    public ApiResponse<List<Coupon>> getAllCoupon() {
        return ApiResponse.<List<Coupon>>builder()
                .result(couponService.viewAllCoupons())
                .message("Success")
                .status(200)
                .build();


    }

    @PutMapping("/choose-coupon-game")
    public ApiResponse<String> chooseGameCoupon(@RequestBody Integer couponId) {
        couponService.turnIsGame(couponId);
        return ApiResponse.<String>builder()
                .result("Cập nhật thành công")
                .message("Success")
                .status(200)
                .build();


    }

    @GetMapping("/random-coupon-for-game/{customerId}")
    public ApiResponse<Coupon> randomGameCoupon(@PathVariable Integer customerId) {
        return ApiResponse.<Coupon>builder()
                .result(couponService.randomGameCoupon(customerId))
                .message("Success")
                .status(200)
                .build();


    }

    @DeleteMapping("/delete/{couponId}")
    public ApiResponse<String> deleteCoupon(@PathVariable Integer couponId) {
        couponService.deleteCoupon(couponId);
        return ApiResponse.<String>builder()
                .result("Xóa coupon thành công")
                .message("Success")
                .status(200)
                .build();
    }
}

package movie.swp391.controller;

import jakarta.validation.Valid;
import lombok.AccessLevel;
import lombok.RequiredArgsConstructor;
import lombok.experimental.FieldDefaults;
import movie.swp391.entity.Coupon;
import movie.swp391.request.ApplyCouponRequest;
import movie.swp391.request.CreateCouponRequest;
import movie.swp391.response.ApiResponse;
import movie.swp391.response.ApplyCouponResponse;
import movie.swp391.response.GameCouponResponse;
import movie.swp391.service.CouponService;
import org.springframework.web.bind.annotation.*;
import org.springframework.security.access.prepost.PreAuthorize;

import java.util.List;

@RestController
@RequestMapping("/api/coupon")
@RequiredArgsConstructor
@FieldDefaults(level = AccessLevel.PRIVATE, makeFinal = true)
public class CouponController {

    CouponService couponService;


    @PostMapping("/create-coupon")
    public ApiResponse<Coupon> createCoupon(@RequestBody @Valid CreateCouponRequest request) {
        return ApiResponse.<Coupon>builder()
                .result(couponService.createCoupon(request))
                .message("Success")
                .status(200)
                .build();
    }

    @PostMapping("/apply")
    public ApiResponse<ApplyCouponResponse> applyCoupon(@RequestBody @Valid ApplyCouponRequest request) {
        return ApiResponse.<ApplyCouponResponse>builder()
                .result(couponService.applyCoupon(request))
                .message("Success")
                .status(200)
                .build();



    }
    @PutMapping("/on-off-coupon")
    public ApiResponse<String> onOffCoupon(@RequestBody List<Integer> couponIds) {
        couponService.turnOnOffCoupon(couponIds);
        return ApiResponse.<String>builder()
                .result("Cập nhật thành công")
                .message("Success")
                .build();
    }
    @GetMapping("/view-all")
    public ApiResponse<List<Coupon>> getAllCoupon() {
        return ApiResponse.<List<Coupon>>builder()
                .result(couponService.viewAllCoupons())
                .message("Success")
                .status(200)
                .build();


    }

    @PutMapping("/choose-coupon-game")
    public ApiResponse<String> chooseGameCoupon(@RequestBody Integer couponId) {
        couponService.turnIsGame(couponId);
        return ApiResponse.<String>builder()
                .result("Cập nhật thành công")
                .message("Success")
                .status(200)
                .build();


    }

    @GetMapping("/random-coupon-for-game/{customerId}")
    public ApiResponse<Coupon> randomGameCoupon(@PathVariable Integer customerId) {
        return ApiResponse.<Coupon>builder()
                .result(couponService.randomGameCoupon(customerId))
                .message("Success")
                .status(200)
                .build();


    }

    @GetMapping("/my-game-coupons/{customerId}")
    public ApiResponse<List<GameCouponResponse>> getMyGameCoupons(@PathVariable Integer customerId) {
        return ApiResponse.<List<GameCouponResponse>>builder()
                .result(couponService.getMyGameCoupons(customerId))
                .message("Success")
                .status(200)
                .build();
    }

    @DeleteMapping("/delete/{couponId}")
    public ApiResponse<String> deleteCoupon(@PathVariable Integer couponId) {
        couponService.deleteCoupon(couponId);
        return ApiResponse.<String>builder()
                .result("Xóa coupon thành công")
                .message("Success")
                .status(200)
                .build();
    }
}

package movie.swp391.controller;

import io.swagger.v3.oas.annotations.Operation;
import jakarta.validation.Valid;
import lombok.AccessLevel;
import lombok.RequiredArgsConstructor;
import lombok.experimental.FieldDefaults;
import movie.swp391.request.member.UpdateProfileRequest;
import movie.swp391.response.*;
import movie.swp391.response.ApiResponse;
import movie.swp391.response.CalculateScoreAndRankResponse;
import movie.swp391.response.CustomerResponse;
import movie.swp391.response.ViewScoreHistoryResponse;
import movie.swp391.response.common.BaseResponse;
import movie.swp391.service.MemberService;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.client.RestClient;

import java.security.Principal;
import java.util.List;
import org.springframework.security.access.prepost.PreAuthorize;

@RestController
@RequestMapping("/api/member")
@RequiredArgsConstructor
@FieldDefaults(level = AccessLevel.PRIVATE, makeFinal = true)

public class MemberController {

    MemberService memberService;
    private final RestClient.Builder builder;

    @Operation(summary = "Edit member profile", description = "Update logged-in user's profile")
    @io.swagger.v3.oas.annotations.responses.ApiResponses({
            @io.swagger.v3.oas.annotations.responses.ApiResponse(responseCode = "200", description = "Update success"),
            @io.swagger.v3.oas.annotations.responses.ApiResponse(responseCode = "400", description = "Invalid input"),
            @io.swagger.v3.oas.annotations.responses.ApiResponse(responseCode = "500", description = "Server error")
    })
    @PutMapping("/edit-profile-member")
    public ResponseEntity<BaseResponse<Void>> editProfile(
            @RequestBody @Valid UpdateProfileRequest request,
            Principal principal) {
        return memberService.editProfile(principal.getName(), request);
    }


    @GetMapping("/get-score-histories/{customerID}")
    public ApiResponse<List<ViewScoreHistoryResponse>> getListOfScoreHistories(@PathVariable Integer customerID) {
        return ApiResponse.<List<ViewScoreHistoryResponse>>builder()
                .result(memberService.viewScoreHistory(customerID))
                .message("Success")
                .status(200)
                .build();
    }

    @GetMapping("/get-profile-member")
    public ApiResponse<CustomerResponse> getProfileMember(@RequestParam Integer customerID) {
        return ApiResponse.<CustomerResponse>builder()
                .result(memberService.viewCustomerProfile(customerID))
                .message("Success")
                .status(200)
                .build();
    }

    @PostMapping("/get-score-member")
    public ApiResponse<CalculateScoreAndRankResponse> getScoresMember(@RequestParam Integer customerID) {
        return ApiResponse.<CalculateScoreAndRankResponse>builder()
                .result(memberService.recalculateCustomerScores(customerID))
                .message("Success")
                .status(200)
                .build();
    }


}

package movie.swp391.controller;

import io.swagger.v3.oas.annotations.Operation;
import jakarta.validation.Valid;
import lombok.AccessLevel;
import lombok.RequiredArgsConstructor;
import lombok.experimental.FieldDefaults;
import movie.swp391.request.member.UpdateProfileRequest;
import movie.swp391.response.*;
import movie.swp391.response.ApiResponse;
import movie.swp391.response.CalculateScoreAndRankResponse;
import movie.swp391.response.CustomerResponse;
import movie.swp391.response.ViewScoreHistoryResponse;
import movie.swp391.response.common.BaseResponse;
import movie.swp391.service.MemberService;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.client.RestClient;

import java.security.Principal;
import java.util.List;
import org.springframework.security.access.prepost.PreAuthorize;

@RestController
@RequestMapping("/api/member")
@RequiredArgsConstructor
@FieldDefaults(level = AccessLevel.PRIVATE, makeFinal = true)

public class MemberController {

    MemberService memberService;
    private final RestClient.Builder builder;

    @Operation(summary = "Edit member profile", description = "Update logged-in user's profile")
    @io.swagger.v3.oas.annotations.responses.ApiResponses({
            @io.swagger.v3.oas.annotations.responses.ApiResponse(responseCode = "200", description = "Update success"),
            @io.swagger.v3.oas.annotations.responses.ApiResponse(responseCode = "400", description = "Invalid input"),
            @io.swagger.v3.oas.annotations.responses.ApiResponse(responseCode = "500", description = "Server error")
    })
    @PutMapping("/edit-profile-member")
    public ResponseEntity<BaseResponse<Void>> editProfile(
            @RequestBody @Valid UpdateProfileRequest request,
            Principal principal) {
        if (principal == null || principal.getName() == null || "anonymousUser".equalsIgnoreCase(principal.getName())) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED)
                    .body(new BaseResponse<>("Vui lòng đăng nhập lại", false, null));
        }
        return memberService.editProfile(principal.getName(), request);
    }


    @GetMapping("/get-score-histories/{customerID}")
    public ApiResponse<List<ViewScoreHistoryResponse>> getListOfScoreHistories(@PathVariable Integer customerID) {
        return ApiResponse.<List<ViewScoreHistoryResponse>>builder()
                .result(memberService.viewScoreHistory(customerID))
                .message("Success")
                .status(200)
                .build();
    }

    @GetMapping("/get-profile-member")
    public ApiResponse<CustomerResponse> getProfileMember(@RequestParam Integer customerID) {
        return ApiResponse.<CustomerResponse>builder()
                .result(memberService.viewCustomerProfile(customerID))
                .message("Success")
                .status(200)
                .build();
    }

    @PostMapping("/get-score-member")
    public ApiResponse<CalculateScoreAndRankResponse> getScoresMember(@RequestParam Integer customerID) {
        return ApiResponse.<CalculateScoreAndRankResponse>builder()
                .result(memberService.recalculateCustomerScores(customerID))
                .message("Success")
                .status(200)
                .build();
    }


}

package movie.swp391.controller;

import lombok.AccessLevel;
import lombok.RequiredArgsConstructor;
