package movie.swp391.serviceImp;

import lombok.AccessLevel;
import lombok.RequiredArgsConstructor;
import lombok.experimental.FieldDefaults;
import movie.swp391.entity.*;
import movie.swp391.entity.Movie;
import movie.swp391.entity.MovieStatusPeriod;
import movie.swp391.entity.Showtime;
import movie.swp391.exception.AppException;
import movie.swp391.exception.ErrorHandler;
import movie.swp391.mapper.*;
import movie.swp391.repository.*;
import movie.swp391.mapper.MovieMapper;
import movie.swp391.mapper.MovieStatusPeriodMapper;
import movie.swp391.repository.MovieRepository;
import movie.swp391.repository.MovieStatusPeriodRepository;
import movie.swp391.repository.ShowtimeRepository;
import movie.swp391.request.MovieAutoRequest;
import movie.swp391.request.MovieRequest;
import movie.swp391.request.MovieStatusPeriodRequest;
import movie.swp391.response.*;
import movie.swp391.response.MovieResponse;
import movie.swp391.response.MovieStatusPeriodResponse;
import movie.swp391.service.MovieService;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;


import java.time.LocalDateTime;
import java.util.List;
import java.util.stream.Collectors;

@Service
@RequiredArgsConstructor
@FieldDefaults(level = AccessLevel.PRIVATE, makeFinal = true)

public class MovieServiceImpl implements MovieService {

    MovieRepository movieRepository;
    MovieMapper movieMapper;
    MovieStatusPeriodRepository movieStatusPeriodRepository;
    MovieStatusPeriodMapper movieStatusPeriodMapper;
    ShowtimeRepository showtimeRepository;

    private static final Logger log = LoggerFactory.getLogger(MovieServiceImpl.class);

    @Override
    public List<MovieResponse> getAllMovies() {
        List<MovieResponse> movies = movieRepository.findAll().stream().map(movieMapper::toMovieResponse).toList();
        if (movies.isEmpty()) throw new AppException(ErrorHandler.LIST_EMPTY);
        return movies;
    }

    @Override
    public MovieResponse createMovie(MovieRequest request) {

        Movie movie = movieMapper.toMovie(request);
        if (movieRepository.existsMoviesByTitleAndPoster(request.getTitle(), request.getPoster()))
            throw new AppException(ErrorHandler.MOVIE_EXIST);
        else movieRepository.save(movie);
        return movieMapper.toMovieResponse(movie);

    }
    @Override
    public MovieResponse createAutoMovie(MovieAutoRequest request) {

        Movie movie = movieMapper.toMovieAuto(request);
        if (movieRepository.existsMoviesByTitleAndPoster(request.getTitle(), request.getPoster()))
            throw new AppException(ErrorHandler.MOVIE_EXIST);

        else movieRepository.save(movie);
        return movieMapper.toMovieResponse(movie);

    }

    @Override
    public MovieResponse updateMovie(Integer movieId, MovieRequest request) {

        Movie movie = movieRepository.findById(movieId).orElseThrow(() -> new AppException(ErrorHandler.MOVIE_NOT_EXISTED));
        if (movieRepository.existsMoviesByTitleAndPosterAndMovieIDNot(request.getTitle(), request.getVersion(), movieId))
            throw new AppException(ErrorHandler.MOVIE_EXIST);
        if (movie.getActive()) throw new AppException(ErrorHandler.MOVIE_IN_ACTIVE);
        movieMapper.updateMovie(movie, request);

        return movieMapper.toMovieResponse(movieRepository.save(movie));

    }

    @Override
    public void deleteMovie(Integer movieId) {

        Movie movie = movieRepository.findById(movieId).orElseThrow(() -> new AppException(ErrorHandler.MOVIE_NOT_EXISTED));
        List<Showtime> showtimes = showtimeRepository.findAllByMovie_MovieID(movieId);
        if (!showtimes.isEmpty()){
            throw new AppException(ErrorHandler.MOVIE_IN_SHOWTIME,"Phim này đang tồn tại trong 1 suất nào đó đảm bảo xóa suất đó trước");

        }
        if (movie.getActive()){
            throw new AppException(ErrorHandler.MOVIE_IN_ACTIVE);
        }
        if(movie.getMovieStatusPeriod() != null){
            movie.setMovieStatusPeriod(null);
            movieRepository.save(movie);
        }


        movieRepository.deleteById(movieId);
    }
    @Override
    public List<MovieStatusPeriodResponse> getALlDate(){
        List<MovieStatusPeriodResponse> date = movieStatusPeriodRepository.findAll().stream().map(movieStatusPeriodMapper::toMovieStatusPeriodResponse).toList();
        if (date.isEmpty()) throw new AppException(ErrorHandler.LIST_EMPTY);
        return date;
    }
    @Override
    public MovieStatusPeriodResponse createDate(MovieStatusPeriodRequest request){
        MovieStatusPeriod movieStatusPeriod = movieStatusPeriodMapper.toMovieStatusPeriod(request);
        if (movieStatusPeriodRepository.existsMovieStatusPeriodByFromDateAndToDate(request.getFromDate(),request.getToDate())) throw new AppException(ErrorHandler.DATE_EXIST);
        movieStatusPeriodRepository.save(movieStatusPeriod);
        return movieStatusPeriodMapper.toMovieStatusPeriodResponse(movieStatusPeriod);
    }
    @Override
    public MovieStatusPeriodResponse updateDate(Long id,MovieStatusPeriodRequest request){
        MovieStatusPeriod msp = movieStatusPeriodRepository.findById(id).orElseThrow(() -> new AppException(ErrorHandler.DATE_NOT_EXIST));
        if (movieStatusPeriodRepository.existsMovieStatusPeriodByFromDateAndToDate(request.getFromDate(),request.getToDate())) throw new AppException(ErrorHandler.DATE_EXIST);

        movieStatusPeriodMapper.updateMovieStatusPeriod(msp, request);

        return movieStatusPeriodMapper.toMovieStatusPeriodResponse(movieStatusPeriodRepository.save(msp));
    }

    @Override
    public void deleteDate(Long id) {
        List<Movie> movies = movieRepository.findByMovieStatusPeriod_Id((id));
        if (!movies.isEmpty()) {
            for (Movie movie : movies) {
                movie.setMovieStatusPeriod(null);
            }
            movieRepository.saveAll(movies);
        }
        movieStatusPeriodRepository.deleteById(id);
    }

    @Override
    public void turnOnOffMovie(List<Integer> movieId){
        List<Movie> movies = movieRepository.findAllById(movieId);

        for (Movie movie : movies) {
            if (movie.getActive()) {
                if (checkIfMovieInShowTimeAfterDay(movie.getMovieID())) {
                    String mess = "Phim " + movie.getTitle() + " đang tồn tại trong giờ chiếu ở tương lai, không thể tắt hoạt động.";
                    throw new AppException(ErrorHandler.MOVIE_IN_SHOWTIME, mess);
                }
            }
        }
        for (Movie movie : movies) {
            movie.setActive(!movie.getActive());
        }
        movieRepository.saveAll(movies);
    }

    public void setDateForMovie(List<Integer> movieId, Long id ){
        MovieStatusPeriod movieStatusPeriod = movieStatusPeriodRepository.findById(id).orElseThrow(() -> new AppException(ErrorHandler.MOVIE_STATUS_NOT_EXIST));
        List<Movie> movies = movieRepository.findAllById(movieId);
        List<Movie> moviesDate = movieRepository.findByMovieStatusPeriod_Id(id);

        // Set movieStatusPeriod cho những movie được chọn
        for (Movie movie : movies) {
            movie.setMovieStatusPeriod(movieStatusPeriod);
        }
        movieRepository.saveAll(movies);

        // Set movieStatusPeriod = null cho những movie khác trong cùng period
        List<Movie> moviesToSetNull = moviesDate.stream()
                .filter(movie -> !movieId.contains(movie.getMovieID()))
                .collect(Collectors.toList());

        for (Movie movie : moviesToSetNull) {
            movie.setMovieStatusPeriod(null);
        }
        movieRepository.saveAll(moviesToSetNull);
    }




    public boolean checkIfMovieInShowTimeAfterDay(Integer movieId) {
        Movie movie = movieRepository.findById(movieId)
                .orElseThrow(() -> new AppException(ErrorHandler.MOVIE_NOT_EXISTED));

        LocalDateTime now = LocalDateTime.now();

        return movie.getShowtimes().stream()
                .anyMatch(showtime -> {
                    LocalDateTime showtimeDateTime = LocalDateTime.of(showtime.getDate(), showtime.getTime());
                    return showtimeDateTime.isAfter(now.plusMinutes(movie.getRunningTime()));
                });

    }









}

package movie.swp391.serviceImp;

import lombok.AccessLevel;
import lombok.RequiredArgsConstructor;
import lombok.experimental.FieldDefaults;
import movie.swp391.entity.*;
import movie.swp391.entity.Movie;
import movie.swp391.entity.MovieStatusPeriod;
import movie.swp391.entity.Showtime;
import movie.swp391.exception.AppException;
import movie.swp391.exception.ErrorHandler;
import movie.swp391.mapper.*;
import movie.swp391.repository.*;
import movie.swp391.mapper.MovieMapper;
import movie.swp391.mapper.MovieStatusPeriodMapper;
import movie.swp391.repository.MovieRepository;
import movie.swp391.repository.MovieStatusPeriodRepository;
import movie.swp391.repository.ShowtimeRepository;
import movie.swp391.request.MovieAutoRequest;
import movie.swp391.request.MovieRequest;
import movie.swp391.request.MovieStatusPeriodRequest;
import movie.swp391.response.*;
import movie.swp391.response.MovieResponse;
import movie.swp391.response.MovieStatusPeriodResponse;
import movie.swp391.service.MovieService;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;


import java.time.LocalDate;
import java.time.LocalDateTime;
import java.util.List;
import java.util.Optional;
import java.util.stream.Collectors;

@Service
@RequiredArgsConstructor
@FieldDefaults(level = AccessLevel.PRIVATE, makeFinal = true)

public class MovieServiceImpl implements MovieService {

    MovieRepository movieRepository;
    MovieMapper movieMapper;
    MovieStatusPeriodRepository movieStatusPeriodRepository;
    MovieStatusPeriodMapper movieStatusPeriodMapper;
    ShowtimeRepository showtimeRepository;

    private static final Logger log = LoggerFactory.getLogger(MovieServiceImpl.class);

    @Override
    public List<MovieResponse> getAllMovies() {
        List<Movie> allMovies = movieRepository.findAll();
        for (Movie movie : allMovies) {
            syncMovieStatusPeriodByShowtimes(movie.getMovieID());
        }

        List<MovieResponse> movies = movieRepository.findAll().stream()
                .map(this::toDerivedMovieResponse)
                .toList();
        if (movies.isEmpty()) throw new AppException(ErrorHandler.LIST_EMPTY);
        return movies;
    }

    private MovieResponse toDerivedMovieResponse(Movie movie) {
        MovieResponse response = movieMapper.toMovieResponse(movie);
        List<Showtime> showtimes = movie.getShowtimes();

        if (showtimes == null || showtimes.isEmpty()) {
            response.setFromDate(null);
            response.setToDate(null);
            response.setStatus("No Schedule");
            return response;
        }

        LocalDateTime now = LocalDateTime.now();
        LocalDateTime comingSoonThreshold = now.plusDays(7);
        boolean hasPast = false;
        boolean hasFuture = false;
        LocalDateTime earliestFutureShowtime = null;

        LocalDate firstDate = null;
        LocalDate latestDate = null;

        for (Showtime showtime : showtimes) {
            LocalDate showDate = showtime.getDate();
            LocalDateTime showDateTime = LocalDateTime.of(showtime.getDate(), showtime.getTime());

            if (showDateTime.isBefore(now)) {
                hasPast = true;
            } else if (showDateTime.isAfter(now)) {
                hasFuture = true;
                if (earliestFutureShowtime == null || showDateTime.isBefore(earliestFutureShowtime)) {
                    earliestFutureShowtime = showDateTime;
                }
            }

            if (firstDate == null || showDate.isBefore(firstDate)) {
                firstDate = showDate;
            }
            if (latestDate == null || showDate.isAfter(latestDate)) {
                latestDate = showDate;
            }
        }

        response.setFromDate(firstDate);
        response.setToDate(latestDate);

        if (hasPast && !hasFuture) {
            response.setStatus("Ended");
        } else if (!hasPast && hasFuture
                && earliestFutureShowtime != null
                && (earliestFutureShowtime.isEqual(comingSoonThreshold) || earliestFutureShowtime.isAfter(comingSoonThreshold))) {
            response.setStatus("Coming Soon");
        } else {
            response.setStatus("Now Showing");
        }

        return response;
    }

    @Override
    public MovieResponse createMovie(MovieRequest request) {

        Movie movie = movieMapper.toMovie(request);
        if (movieRepository.existsMoviesByTitleAndPoster(request.getTitle(), request.getPoster()))
            throw new AppException(ErrorHandler.MOVIE_EXIST);
        else movieRepository.save(movie);
        return movieMapper.toMovieResponse(movie);

    }
    @Override
    public MovieResponse createAutoMovie(MovieAutoRequest request) {

        Movie movie = movieMapper.toMovieAuto(request);
        if (movieRepository.existsMoviesByTitleAndPoster(request.getTitle(), request.getPoster()))
            throw new AppException(ErrorHandler.MOVIE_EXIST);

        else movieRepository.save(movie);
        return movieMapper.toMovieResponse(movie);

    }

    @Override
    public MovieResponse updateMovie(Integer movieId, MovieRequest request) {

        Movie movie = movieRepository.findById(movieId).orElseThrow(() -> new AppException(ErrorHandler.MOVIE_NOT_EXISTED));
        if (movieRepository.existsMoviesByTitleAndPosterAndMovieIDNot(request.getTitle(), request.getVersion(), movieId))
            throw new AppException(ErrorHandler.MOVIE_EXIST);
        movieMapper.updateMovie(movie, request);

        return movieMapper.toMovieResponse(movieRepository.save(movie));

    }

    @Override
    public void deleteMovie(Integer movieId) {

        Movie movie = movieRepository.findById(movieId).orElseThrow(() -> new AppException(ErrorHandler.MOVIE_NOT_EXISTED));
        List<Showtime> showtimes = showtimeRepository.findAllByMovie_MovieID(movieId);
        if (!showtimes.isEmpty()){
            throw new AppException(ErrorHandler.MOVIE_IN_SHOWTIME,"Phim này đang tồn tại trong 1 suất nào đó đảm bảo xóa suất đó trước");

        }
        if (movie.getActive()){
            throw new AppException(ErrorHandler.MOVIE_IN_ACTIVE);
        }
        if(movie.getMovieStatusPeriod() != null){
            movie.setMovieStatusPeriod(null);
            movieRepository.save(movie);
        }


        movieRepository.deleteById(movieId);
    }
    @Override
    public List<MovieStatusPeriodResponse> getALlDate(){
        List<MovieStatusPeriodResponse> date = movieStatusPeriodRepository.findAll().stream().map(movieStatusPeriodMapper::toMovieStatusPeriodResponse).toList();
        if (date.isEmpty()) throw new AppException(ErrorHandler.LIST_EMPTY);
        return date;
    }
    @Override
    public MovieStatusPeriodResponse createDate(MovieStatusPeriodRequest request){
        MovieStatusPeriod movieStatusPeriod = movieStatusPeriodMapper.toMovieStatusPeriod(request);
        if (movieStatusPeriodRepository.existsMovieStatusPeriodByFromDateAndToDate(request.getFromDate(),request.getToDate())) throw new AppException(ErrorHandler.DATE_EXIST);
        movieStatusPeriodRepository.save(movieStatusPeriod);
        return movieStatusPeriodMapper.toMovieStatusPeriodResponse(movieStatusPeriod);
    }
    @Override
    public MovieStatusPeriodResponse updateDate(Long id,MovieStatusPeriodRequest request){
        MovieStatusPeriod msp = movieStatusPeriodRepository.findById(id).orElseThrow(() -> new AppException(ErrorHandler.DATE_NOT_EXIST));
        if (movieStatusPeriodRepository.existsMovieStatusPeriodByFromDateAndToDate(request.getFromDate(),request.getToDate())) throw new AppException(ErrorHandler.DATE_EXIST);

        movieStatusPeriodMapper.updateMovieStatusPeriod(msp, request);

        return movieStatusPeriodMapper.toMovieStatusPeriodResponse(movieStatusPeriodRepository.save(msp));
    }

    @Override
    public void deleteDate(Long id) {
        List<Movie> movies = movieRepository.findByMovieStatusPeriod_Id((id));
        if (!movies.isEmpty()) {
            for (Movie movie : movies) {
                movie.setMovieStatusPeriod(null);
            }
            movieRepository.saveAll(movies);
        }
        movieStatusPeriodRepository.deleteById(id);
    }

    @Override
    public void turnOnOffMovie(List<Integer> movieId){
        List<Movie> movies = movieRepository.findAllById(movieId);

        for (Movie movie : movies) {
            if (movie.getActive()) {
                if (checkIfMovieInShowTimeAfterDay(movie.getMovieID())) {
                    String mess = "Phim " + movie.getTitle() + " đang tồn tại trong giờ chiếu ở tương lai, không thể tắt hoạt động.";
                    throw new AppException(ErrorHandler.MOVIE_IN_SHOWTIME, mess);
                }
            }
        }
        for (Movie movie : movies) {
            movie.setActive(!movie.getActive());
        }
        movieRepository.saveAll(movies);
    }

    public void setDateForMovie(List<Integer> movieId, Long id ){
        MovieStatusPeriod movieStatusPeriod = movieStatusPeriodRepository.findById(id).orElseThrow(() -> new AppException(ErrorHandler.MOVIE_STATUS_NOT_EXIST));
        List<Movie> movies = movieRepository.findAllById(movieId);
        List<Movie> moviesDate = movieRepository.findByMovieStatusPeriod_Id(id);

        // Set movieStatusPeriod cho những movie được chọn
        for (Movie movie : movies) {
            movie.setMovieStatusPeriod(movieStatusPeriod);
        }
        movieRepository.saveAll(movies);

        // Set movieStatusPeriod = null cho những movie khác trong cùng period
        List<Movie> moviesToSetNull = moviesDate.stream()
                .filter(movie -> !movieId.contains(movie.getMovieID()))
                .collect(Collectors.toList());

        for (Movie movie : moviesToSetNull) {
            movie.setMovieStatusPeriod(null);
        }
        movieRepository.saveAll(moviesToSetNull);
    }




    public boolean checkIfMovieInShowTimeAfterDay(Integer movieId) {
        Movie movie = movieRepository.findById(movieId)
                .orElseThrow(() -> new AppException(ErrorHandler.MOVIE_NOT_EXISTED));

        LocalDateTime now = LocalDateTime.now();

        return movie.getShowtimes().stream()
                .anyMatch(showtime -> {
                    LocalDateTime showtimeDateTime = LocalDateTime.of(showtime.getDate(), showtime.getTime());
                    return showtimeDateTime.isAfter(now.plusMinutes(movie.getRunningTime()));
                });

    }

    @Override
    @Transactional
    public void syncMovieStatusPeriodByShowtimes(Integer movieId) {
        Movie movie = movieRepository.findById(movieId)
                .orElseThrow(() -> new AppException(ErrorHandler.MOVIE_NOT_EXISTED));

        Optional<Showtime> latestShowtimeOpt = showtimeRepository.findTopByMovie_MovieIDOrderByDateDescTimeDesc(movieId);
        if (latestShowtimeOpt.isEmpty()) {
            if (movie.getMovieStatusPeriod() != null) {
                movie.setMovieStatusPeriod(null);
                movieRepository.save(movie);
            }
            return;
        }

        LocalDate latestDate = latestShowtimeOpt.get().getDate();
        LocalDate firstDate = showtimeRepository.findTopByMovie_MovieIDOrderByDateAscTimeAsc(movieId)
                .map(Showtime::getDate)
                .orElse(latestDate);

        MovieStatusPeriod period = movie.getMovieStatusPeriod();
        boolean changed = false;

        if (period == null) {
            period = new MovieStatusPeriod();
            period.setFromDate(firstDate);
            period.setToDate(latestDate);
            movie.setMovieStatusPeriod(period);
            changed = true;
        } else {
            // A period can be shared by multiple movies; clone it so syncing one movie does not overwrite others.
            if (period.getMovies() != null && period.getMovies().stream().anyMatch(m -> !m.getMovieID().equals(movieId))) {
                MovieStatusPeriod cloned = new MovieStatusPeriod();
                cloned.setFromDate(period.getFromDate());
                cloned.setToDate(period.getToDate());
                movie.setMovieStatusPeriod(cloned);
                period = cloned;
                changed = true;
            }

            if (period.getFromDate() == null || period.getFromDate().isAfter(firstDate)) {
                period.setFromDate(firstDate);
                changed = true;
            }

            if (period.getToDate() == null || !period.getToDate().equals(latestDate)) {
                period.setToDate(latestDate);
                changed = true;
            }
        }

        if (changed) {
            movieRepository.save(movie);
        }
    }

    @Scheduled(fixedRate = 300000)
    @Transactional
    public void syncAllMovieStatusPeriodsByShowtimes() {
        movieRepository.findAll().forEach(movie -> {
            try {
                syncMovieStatusPeriodByShowtimes(movie.getMovieID());
            } catch (Exception ex) {
                log.warn("Failed to sync movie status period for movieID={}: {}", movie.getMovieID(), ex.getMessage());
            }
        });
    }









}

package movie.swp391.serviceImp;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.transaction.Transactional;
import lombok.AccessLevel;
import lombok.RequiredArgsConstructor;
import lombok.experimental.FieldDefaults;
import movie.swp391.entity.*;
import movie.swp391.exception.AppException;
import movie.swp391.exception.ErrorHandler;
import movie.swp391.properties.PayOsProperties;
import movie.swp391.repository.*;
import movie.swp391.request.*;
import movie.swp391.service.*;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.stereotype.Service;
import vn.payos.PayOS;
import vn.payos.model.v2.paymentRequests.CreatePaymentLinkRequest;
import vn.payos.model.v2.paymentRequests.CreatePaymentLinkResponse;
import vn.payos.model.v2.paymentRequests.PaymentLinkItem;
import vn.payos.model.webhooks.WebhookData;

import java.io.UnsupportedEncodingException;
import java.time.LocalDate;
import java.time.LocalDateTime;
import java.util.*;

@Service
@RequiredArgsConstructor
@FieldDefaults(level = AccessLevel.PRIVATE, makeFinal = true)
public class PaymentServiceImpl implements PaymentService {

    VNpayService vnPayService;
    PaymentMethodRepository paymentMethodRepository;
    SeatRepository seatRepository;
    TicketBookingRepository ticketBookingRepository;
    TicketDetailRepository ticketDetailRepository;
    ScoreHistoryRepository scoreHistoryRepository;
    CouponRepository couponRepository;
    CouponUsageRepository couponUsageRepository;
    MovieRepository movieRepository;
    PromotionRepository promotionRepository;
    PromotionService promotionService;
    ExportService exportMovieDateService;
    CustomerRepository customerRepository;
    PayOsProperties payOsProperties;
    ObjectProvider<PayOS> payOSProvider;

    ObjectMapper objectMapper = new ObjectMapper();

    @Override
    @Transactional
    public String processPayment(PaymentRequest request) {
        String gateway = normalizeGateway(request.getPaymentGateway());
        PaymentMethod paymentMethod = resolvePaymentMethod(request.getPaymentId(), gateway);
        TicketBooking ticketBooking = ticketBookingRepository.findTicketBookingByBookingID(request.getBookingId())
                .orElseThrow(() -> new AppException(ErrorHandler.BOOKING_INVALID));

        if (paymentMethod == null && gateway.isBlank()) {
            throw new AppException(ErrorHandler.PAYMENT_NULL);
        }
        if (!request.isSuccess()) {
            throw new AppException(ErrorHandler.PAYMENT_OUT_TIME);
        }
        if ("Cancelled".equalsIgnoreCase(ticketBooking.getStatus())) {
            throw new AppException(ErrorHandler.PAYMENT_OUT_TIME);
        }

        if (paymentMethod != null) {
            ticketBooking.setPaymentMethod(paymentMethod);
            ticketBookingRepository.save(ticketBooking);
        }

        String paymentType = paymentMethod != null
                ? canonicalGateway(paymentMethod.getType())
                : canonicalGateway(gateway);

        if ("VNPAY".equals(paymentType)) {
            try {
                return vnPayService.createPaymentUrl(request.getBookingId(), request.getTotalMoney(), request.getIpAddress());
            } catch (UnsupportedEncodingException e) {
                throw new RuntimeException("Lỗi cổng phương thức", e);
            }
        }

        if ("PAYOS".equals(paymentType)) {
            return createPayOsPaymentLink(ticketBooking, request.getTotalMoney());
        }

        throw new RuntimeException("Phương thức thanh toán chưa hỗ trợ");
    }

    @Override
    @Transactional
    public String resultPayment(PaymentResultRequest request) {
        if (isPayOsResult(request)) {
            return handlePayOsResult(request);
        }

        TicketBooking ticketBooking = ticketBookingRepository.findById(request.getBookingId())
                .orElseThrow(() -> new AppException(ErrorHandler.BOOKING_INVALID));

        boolean isPaymentSuccessful = "00".equals(request.getVnp_ResponseCode())
                && "00".equals(request.getVnp_TransactionStatus());

        if (isPaymentSuccessful) {
            finalizeSuccessfulPayment(ticketBooking, request.getTotalMoney(), request.getCouponCode(), request.getSelectedPromotionIds());
            return "Thanh toán thành công";
        }

        markBookingFailed(ticketBooking);
        return "Thanh toán thất bại";
    }

    @Override
    @Transactional
    public Map<String, Object> handlePayOsWebhook(Map<String, Object> payload) {
        try {
            WebhookData verifiedData = verifyPayOsWebhook(payload);
            if (verifiedData == null) {
                return Map.of("code", "00", "message", "signature verification failed");
            }

            Map<String, Object> data = objectMapper.convertValue(verifiedData, Map.class);
            String orderCode = valueAsString(data.get("orderCode"));
            if (orderCode.isBlank()) {
                return Map.of("code", "00", "message", "orderCode missing");
            }

            TicketBooking booking = ticketBookingRepository.findByPayosOrderCode(orderCode)
                    .orElse(null);
            if (booking == null) {
                return Map.of("code", "00", "message", "booking not found");
            }

            String code = valueAsString(payload.get("code"));
            if (code.isBlank()) {
                code = valueAsString(data.get("code"));
            }
            String status = valueAsString(payload.get("status"));
            if (status.isBlank()) {
                status = valueAsString(data.get("status"));
            }

            boolean payOsSuccess = !isFailureStatus(status)
                    && ("00".equals(code) || isSuccessStatus(status));

            if (payOsSuccess) {
                finalizeSuccessfulPayment(booking, booking.getTotalPrice(), null, null);
                return Map.of("code", "00", "message", "success");
            }

            markBookingFailed(booking);
            return Map.of("code", "00", "message", "payment failed");
        } catch (Exception e) {
            return Map.of("code", "00", "message", "error");
        }
    }

    private String handlePayOsResult(PaymentResultRequest request) {
        TicketBooking ticketBooking = findBookingByPayOsRequest(request);

        boolean isPayOsSuccess = !isFailureStatus(request.getPayosStatus())
                && ("00".equals(request.getPayosCode())
                || isSuccessStatus(request.getPayosStatus()));

        if (isPayOsSuccess) {
            finalizeSuccessfulPayment(ticketBooking, request.getTotalMoney(), request.getCouponCode(), request.getSelectedPromotionIds());
            return "Thanh toán thành công";
        }

        markBookingFailed(ticketBooking);
        return "Thanh toán thất bại";
    }

    private TicketBooking findBookingByPayOsRequest(PaymentResultRequest request) {
        if (request.getPayosOrderCode() != null && !request.getPayosOrderCode().isBlank()) {
            TicketBooking byOrderCode = ticketBookingRepository.findByPayosOrderCode(request.getPayosOrderCode())
                    .orElse(null);
            if (byOrderCode != null) {
                return byOrderCode;
            }
        }

        if (request.getBookingId() != null) {
            return ticketBookingRepository.findById(request.getBookingId())
                    .orElseThrow(() -> new AppException(ErrorHandler.BOOKING_INVALID));
        }

        throw new AppException(ErrorHandler.BOOKING_INVALID);
    }

    private void finalizeSuccessfulPayment(
            TicketBooking ticketBooking,
            Double paidTotal,
            String couponCode,
            List<Integer> selectedPromotionIds
    ) {
        if ("Success".equalsIgnoreCase(ticketBooking.getStatus())) {
            return;
        }

        Customer customer = ticketBooking.getCustomer();
        if (couponCode != null && !couponCode.isBlank()) {
            Coupon coupon = (Coupon) couponRepository.findByCode(couponCode)
                    .orElseThrow(() -> new AppException(ErrorHandler.COUPON_NOT_FOUND, "Mã coupon không tồn tại."));

            coupon.setUsedCount(coupon.getUsedCount() + 1);
            if (coupon.getUsageLimit() <= 0) {
                coupon.setIsActive(false);
                throw new AppException(ErrorHandler.COUPON_LIMIT_REACHED, "Mã coupon đã đạt giới hạn sử dụng.");
            }
            coupon.setUsageLimit(coupon.getUsageLimit() - 1);

            CouponUsage couponUsage = new CouponUsage();
            couponUsage.setCustomer(customer);
            couponUsage.setCoupon(coupon);
            couponUsage.setUsedAt(LocalDateTime.now());
            couponUsageRepository.save(couponUsage);
            couponRepository.save(coupon);
        }

        if (selectedPromotionIds != null && !selectedPromotionIds.isEmpty()) {
            for (Integer promotionId : selectedPromotionIds) {
                Promotion promotion = promotionRepository.findById(promotionId)
                        .orElseThrow(() -> new AppException(ErrorHandler.PROMOTION_NOT_FOUND, "Khuyến mãi không tồn tại."));
                promotionService.applyPromotion(promotion, customer);
            }
        }

        Movie movie = movieRepository.findById(ticketBooking.getShowtime().getMovie().getMovieID())
                .orElseThrow(() -> new AppException(ErrorHandler.MOVIE_NOT_EXISTED));

        if (movie.getTotalMoney() == null || movie.getTotalMoneyWithoutFood() == null
                || movie.getTotalMoneyFood() == null || movie.getTotalMoneyDiscount() == null) {
            movie.setTotalMoney(0.0);
            movie.setTotalMoneyWithoutFood(0.0);
            movie.setTotalMoneyFood(0.0);
            movie.setTotalMoneyDiscount(0.0);
            movie.setBuyFromScores(0.0);
            movieRepository.save(movie);
        }

        // Loyalty rules removed — skip point awarding
        Integer seller = ticketBooking.getShowtime().getMovie().getSeller();
        Double totalMoney = ticketBooking.getTotalPrice();
        Double totalMoneyWithoutFoodAndDiscount = ticketBooking.getTicketDetails().stream()
                .filter(booking -> booking.getBooking().getBookingID().equals(ticketBooking.getBookingID()))
                .mapToDouble(TicketDetail::getUnitPrice)
                .sum();
        Double totalMoneyFood = ticketBooking.getBookingFoodAndDrinks() == null ? 0.0 : ticketBooking.getBookingFoodAndDrinks().stream()
                .filter(booking -> booking.getBooking() != null && booking.getBooking().getBookingID().equals(ticketBooking.getBookingID()))
                .mapToDouble(food -> food.getQuantity() * (food.getUnitPrice() != null ? food.getUnitPrice() : 0.0))
                .sum();
        Double totalMoneyDiscount = ticketBooking.getShowtime().getMovie().getTotalMoneyWithoutFood()
                + ticketBooking.getShowtime().getMovie().getTotalMoneyFood()
                - ticketBooking.getShowtime().getMovie().getTotalMoney();

        ticketBooking.setStatus("Success");
        if (paidTotal != null && paidTotal > 0) {
            ticketBooking.setTotalPrice(paidTotal);
        }
        ticketBooking.getShowtime().getMovie().setSeller(seller + 1);
        ticketBooking.getShowtime().getMovie().setTotalMoney(ticketBooking.getShowtime().getMovie().getTotalMoney() + totalMoney);
        ticketBooking.getShowtime().getMovie().setTotalMoneyWithoutFood(ticketBooking.getShowtime().getMovie().getTotalMoneyWithoutFood() + totalMoneyWithoutFoodAndDiscount);
        ticketBooking.getShowtime().getMovie().setTotalMoneyFood(ticketBooking.getShowtime().getMovie().getTotalMoneyFood() + totalMoneyFood);
        ticketBooking.getShowtime().getMovie().setTotalMoneyDiscount(ticketBooking.getShowtime().getMovie().getTotalMoneyDiscount() + totalMoneyDiscount);

        // Loyalty rules removed — no point awarding

        ticketBookingRepository.save(ticketBooking);

        exportMovieDateService.updateExportMovieDate(
                movie,
                LocalDate.now(),
                totalMoney,
                totalMoneyWithoutFoodAndDiscount,
                totalMoneyDiscount,
                totalMoneyFood,
                0
        );
    }

    private void markBookingFailed(TicketBooking ticketBooking) {
        if ("Success".equalsIgnoreCase(ticketBooking.getStatus())) {
            return;
        }
        if ("Cancelled".equalsIgnoreCase(ticketBooking.getStatus())) {
            return;
        }

        ticketBooking.setStatus("Cancelled");
        List<TicketDetail> ticketDetails = ticketBooking.getTicketDetails();
        for (TicketDetail ticketDetail : ticketDetails) {
            ticketDetail.setCheckSeat("Blank");
        }
        ticketDetailRepository.saveAll(ticketDetails);
        ticketBookingRepository.save(ticketBooking);
    }

    private PaymentMethod resolvePaymentMethod(Integer paymentId, String paymentGateway) {
        if (paymentId != null) {
            return paymentMethodRepository.findById(Long.valueOf(paymentId)).orElse(null);
        }
        if (paymentGateway == null || paymentGateway.isBlank()) {
            return null;
        }
        String canonical = canonicalGateway(paymentGateway);
        if (canonical.isBlank()) {
            return null;
        }

        String displayType = "PAYOS".equals(canonical) ? "PayOS" : "VNPay";
        return paymentMethodRepository.findByTypeIgnoreCase(displayType)
                .orElseGet(() -> paymentMethodRepository.save(new PaymentMethod(
                        null,
                        displayType,
                        ""
                )));
    }

    private String normalizeGateway(String paymentGateway) {
        if (paymentGateway == null) {
            return "";
        }
        return paymentGateway.trim().replace("_", "").replace("-", "").toUpperCase(Locale.ROOT);
    }

    private String canonicalGateway(String paymentGateway) {
        String normalized = normalizeGateway(paymentGateway);
        if ("PAYOS".equals(normalized)) {
            return "PAYOS";
        }
        if ("VNPAY".equals(normalized)) {
            return "VNPAY";
        }
        return "";
    }

    private String createPayOsPaymentLink(TicketBooking ticketBooking, Double totalMoney) {
        PayOS payOS = requirePayOsClient();
        long orderCode = generateUniqueOrderCode();
        long amount = Math.round(totalMoney == null ? ticketBooking.getTotalPrice() : totalMoney);

        try {
            PaymentLinkItem item = PaymentLinkItem.builder()
                    .name("Thanh toan ve xem phim")
                    .quantity(1)
                    .price(amount)
                    .build();

            String bookingIdStr = String.valueOf(ticketBooking.getBookingID());
            CreatePaymentLinkRequest paymentData = CreatePaymentLinkRequest.builder()
                    .orderCode(orderCode)
                    .amount(amount)
                    .description("Booking " + ticketBooking.getBookingID())
                    .item(item)
                    .returnUrl(buildPayOsReturnUrl(payOsProperties.getTicketReturnUrl(), orderCode, "success", bookingIdStr))
                    .cancelUrl(buildPayOsReturnUrl(payOsProperties.getTicketCancelUrl(), orderCode, "cancel", bookingIdStr))
                    .build();

            CreatePaymentLinkResponse response = payOS.paymentRequests().create(paymentData);
            if (response.getCheckoutUrl() == null || response.getCheckoutUrl().isBlank()) {
                throw new RuntimeException("PAYOS did not return checkoutUrl");
            }

            ticketBooking.setPayosOrderCode(String.valueOf(orderCode));
            ticketBooking.setPayosPaymentLinkId(response.getPaymentLinkId());
            ticketBookingRepository.save(ticketBooking);
            return response.getCheckoutUrl();
        } catch (Exception e) {
            throw new RuntimeException("Không thể tạo link thanh toán PAYOS", e);
        }
    }

    private long generateUniqueOrderCode() {
        long orderCode = System.currentTimeMillis() / 1000;
        int attempts = 0;
        while (ticketBookingRepository.findByPayosOrderCode(String.valueOf(orderCode)).isPresent()) {
            orderCode++;
            attempts++;
            if (attempts > 10_000) {
                throw new RuntimeException("Không thể sinh orderCode duy nhất cho PAYOS");
            }
        }
        return orderCode;
    }

    private PayOS requirePayOsClient() {
        if (payOsProperties.getClientId() == null || payOsProperties.getClientId().isBlank()
                || payOsProperties.getApiKey() == null || payOsProperties.getApiKey().isBlank()
                || payOsProperties.getChecksumKey() == null || payOsProperties.getChecksumKey().isBlank()) {
            throw new RuntimeException("PAYOS chưa được cấu hình đầy đủ");
        }

        PayOS payOS = payOSProvider.getIfAvailable();
        if (payOS == null) {
            throw new RuntimeException("Không khởi tạo được PAYOS client");
        }
        return payOS;
    }

    private WebhookData verifyPayOsWebhook(Map<String, Object> payload) {
        PayOS payOS = payOSProvider.getIfAvailable();
        if (payOS == null) {
            return null;
        }
        try {
            return payOS.webhooks().verify(payload);
        } catch (Exception e) {
            return null;
        }
    }

    private boolean isPayOsResult(PaymentResultRequest request) {
        return (request.getPaymentGateway() != null && request.getPaymentGateway().equalsIgnoreCase("payos"))
                || (request.getPayosOrderCode() != null && !request.getPayosOrderCode().isBlank());
    }

    private String valueAsString(Object value) {
        return value == null ? "" : String.valueOf(value);
    }

    private String buildPayOsReturnUrl(String baseUrl, long orderCode, String status, String id) {
        String query = "orderCode=" + orderCode + "&status=" + status + "&id=" + id + "&paymentGateway=payos";
        if (baseUrl == null || baseUrl.isBlank()) {
            return "http://localhost:5173/payment-success?" + query;
        }
        String normalized = baseUrl.trim();
        // If baseUrl already contains all required params, return it as is
        if (normalized.contains("orderCode=") && normalized.contains("status=") && normalized.contains("id=")) {
            return normalized;
        }
        // Otherwise, append missing query params
        return normalized + (normalized.contains("?") ? "&" : "?") + query;
    }

    private boolean isSuccessStatus(String status) {
        if (status == null) {
            return false;
        }
        String normalized = status.trim().toLowerCase();
        return "success".equals(normalized)
                || "succes".equals(normalized)
                || "paid".equals(normalized)
                || "succeeded".equals(normalized);
    }

    private boolean isFailureStatus(String status) {
        if (status == null) {
            return false;
        }
        String normalized = status.trim().toLowerCase();
        return "cancel".equals(normalized)
                || "cancelled".equals(normalized)
                || "canceled".equals(normalized)
                || "fail".equals(normalized)
                || "failed".equals(normalized)
                || "error".equals(normalized)
                || "expired".equals(normalized);
    }

    private String writeMetadata(Map<String, Object> payload) {
        try {
            return objectMapper.writeValueAsString(payload);
        } catch (JsonProcessingException e) {
            return null;
        }
    }

    @Override
    public List<PaymentMethod> getAllPayment() {
        return paymentMethodRepository.findAll();
    }

    // Pay-by-points and exchange-point methods removed as feature is deleted

}

package movie.swp391.serviceImp;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.transaction.Transactional;
import lombok.AccessLevel;
import lombok.RequiredArgsConstructor;
import lombok.experimental.FieldDefaults;
import movie.swp391.entity.*;
import movie.swp391.exception.AppException;
import movie.swp391.exception.ErrorHandler;
import movie.swp391.properties.PayOsProperties;
import movie.swp391.repository.*;
import movie.swp391.request.*;
import movie.swp391.service.*;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.stereotype.Service;
import vn.payos.PayOS;
import vn.payos.model.v2.paymentRequests.CreatePaymentLinkRequest;
import vn.payos.model.v2.paymentRequests.CreatePaymentLinkResponse;
import vn.payos.model.v2.paymentRequests.PaymentLinkItem;
import vn.payos.model.webhooks.WebhookData;

import java.io.UnsupportedEncodingException;
import java.time.LocalDate;
import java.time.LocalDateTime;
import java.util.*;

@Service
@RequiredArgsConstructor
@FieldDefaults(level = AccessLevel.PRIVATE, makeFinal = true)
public class PaymentServiceImpl implements PaymentService {

    VNpayService vnPayService;
    PaymentMethodRepository paymentMethodRepository;
    SeatRepository seatRepository;
    TicketBookingRepository ticketBookingRepository;
    TicketDetailRepository ticketDetailRepository;
    ScoreHistoryRepository scoreHistoryRepository;
    CouponRepository couponRepository;
    CouponUsageRepository couponUsageRepository;
    MovieRepository movieRepository;
    PromotionRepository promotionRepository;
    PromotionService promotionService;
    ExportService exportMovieDateService;
    CustomerRepository customerRepository;
    PayOsProperties payOsProperties;
    ObjectProvider<PayOS> payOSProvider;

    ObjectMapper objectMapper = new ObjectMapper();

    @Override
    @Transactional
    public String processPayment(PaymentRequest request) {
        String gateway = normalizeGateway(request.getPaymentGateway());
        PaymentMethod paymentMethod = resolvePaymentMethod(request.getPaymentId(), gateway);
        TicketBooking ticketBooking = ticketBookingRepository.findTicketBookingByBookingID(request.getBookingId())
                .orElseThrow(() -> new AppException(ErrorHandler.BOOKING_INVALID));

        if (paymentMethod == null && gateway.isBlank()) {
            throw new AppException(ErrorHandler.PAYMENT_NULL);
        }
        if (!request.isSuccess()) {
            throw new AppException(ErrorHandler.PAYMENT_OUT_TIME);
        }
        if ("Cancelled".equalsIgnoreCase(ticketBooking.getStatus())) {
            throw new AppException(ErrorHandler.PAYMENT_OUT_TIME);
        }

        if (paymentMethod != null) {
            ticketBooking.setPaymentMethod(paymentMethod);
            ticketBookingRepository.save(ticketBooking);
        }

        String paymentType = paymentMethod != null
                ? canonicalGateway(paymentMethod.getType())
                : canonicalGateway(gateway);

        if ("VNPAY".equals(paymentType)) {
            try {
                return vnPayService.createPaymentUrl(request.getBookingId(), request.getTotalMoney(), request.getIpAddress());
            } catch (UnsupportedEncodingException e) {
                throw new RuntimeException("Lỗi cổng phương thức", e);
            }
        }

        if ("PAYOS".equals(paymentType)) {
            return createPayOsPaymentLink(ticketBooking, request.getTotalMoney());
        }

        throw new RuntimeException("Phương thức thanh toán chưa hỗ trợ");
    }

    @Override
    @Transactional
    public String resultPayment(PaymentResultRequest request) {
        if (isPayOsResult(request)) {
            return handlePayOsResult(request);
        }

        TicketBooking ticketBooking = ticketBookingRepository.findById(request.getBookingId())
                .orElseThrow(() -> new AppException(ErrorHandler.BOOKING_INVALID));

        boolean isPaymentSuccessful = "00".equals(request.getVnp_ResponseCode())
                && "00".equals(request.getVnp_TransactionStatus());

        if (isPaymentSuccessful) {
            finalizeSuccessfulPayment(ticketBooking, request.getTotalMoney(), request.getCouponCode(), request.getSelectedPromotionIds());
            return "Thanh toán thành công";
        }

        markBookingFailed(ticketBooking);
        return "Thanh toán thất bại";
    }

    @Override
    @Transactional
    public String mockSuccessPayment(MockPaymentRequest request) {
        if (request == null || request.getBookingId() == null || request.getCustomerId() == null) {
            throw new AppException(ErrorHandler.INVALID_INPUT, "Thiếu bookingId hoặc customerId");
        }

        TicketBooking ticketBooking = ticketBookingRepository.findById(request.getBookingId())
                .orElseThrow(() -> new AppException(ErrorHandler.BOOKING_INVALID));

        if (ticketBooking.getCustomer() == null
                || !request.getCustomerId().equals(ticketBooking.getCustomer().getCustomerID())) {
            throw new AppException(ErrorHandler.UNAUTHORIZED, "Bạn không có quyền thanh toán đơn này");
        }

        if ("Success".equalsIgnoreCase(ticketBooking.getStatus())) {
            return "Đơn đã được thanh toán trước đó";
        }

        if (!"pending".equalsIgnoreCase(ticketBooking.getStatus())) {
            throw new AppException(ErrorHandler.PAYMENT_OUT_TIME, "Đơn không còn ở trạng thái chờ thanh toán");
        }

        finalizeSuccessfulPayment(ticketBooking, ticketBooking.getTotalPrice(), null, null);
        return "Mock thanh toán thành công";
    }

    @Override
    @Transactional
    public Map<String, Object> handlePayOsWebhook(Map<String, Object> payload) {
        try {
            WebhookData verifiedData = verifyPayOsWebhook(payload);
            if (verifiedData == null) {
                return Map.of("code", "00", "message", "signature verification failed");
            }

            Map<String, Object> data = objectMapper.convertValue(verifiedData, Map.class);
            String orderCode = valueAsString(data.get("orderCode"));
            if (orderCode.isBlank()) {
                return Map.of("code", "00", "message", "orderCode missing");
            }

            TicketBooking booking = ticketBookingRepository.findByPayosOrderCode(orderCode)
                    .orElse(null);
            if (booking == null) {
                return Map.of("code", "00", "message", "booking not found");
            }

            String code = valueAsString(payload.get("code"));
            if (code.isBlank()) {
                code = valueAsString(data.get("code"));
            }
            String status = valueAsString(payload.get("status"));
            if (status.isBlank()) {
                status = valueAsString(data.get("status"));
            }

            boolean payOsSuccess = !isFailureStatus(status)
                    && ("00".equals(code) || isSuccessStatus(status));

            if (payOsSuccess) {
                finalizeSuccessfulPayment(booking, booking.getTotalPrice(), null, null);
                return Map.of("code", "00", "message", "success");
            }

            markBookingFailed(booking);
            return Map.of("code", "00", "message", "payment failed");
        } catch (Exception e) {
            return Map.of("code", "00", "message", "error");
        }
    }

    private String handlePayOsResult(PaymentResultRequest request) {
        TicketBooking ticketBooking = findBookingByPayOsRequest(request);

        boolean isPayOsSuccess = !isFailureStatus(request.getPayosStatus())
                && ("00".equals(request.getPayosCode())
                || isSuccessStatus(request.getPayosStatus()));

        if (isPayOsSuccess) {
            finalizeSuccessfulPayment(ticketBooking, request.getTotalMoney(), request.getCouponCode(), request.getSelectedPromotionIds());
            return "Thanh toán thành công";
        }

        markBookingFailed(ticketBooking);
        return "Thanh toán thất bại";
    }

    private TicketBooking findBookingByPayOsRequest(PaymentResultRequest request) {
        if (request.getPayosOrderCode() != null && !request.getPayosOrderCode().isBlank()) {
            TicketBooking byOrderCode = ticketBookingRepository.findByPayosOrderCode(request.getPayosOrderCode())
                    .orElse(null);
            if (byOrderCode != null) {
                return byOrderCode;
            }
        }

        if (request.getBookingId() != null) {
            return ticketBookingRepository.findById(request.getBookingId())
                    .orElseThrow(() -> new AppException(ErrorHandler.BOOKING_INVALID));
        }

        throw new AppException(ErrorHandler.BOOKING_INVALID);
    }

    private void finalizeSuccessfulPayment(
            TicketBooking ticketBooking,
            Double paidTotal,
            String couponCode,
            List<Integer> selectedPromotionIds
    ) {
        if ("Success".equalsIgnoreCase(ticketBooking.getStatus())) {
            return;
        }

        Customer customer = ticketBooking.getCustomer();
        if (couponCode != null && !couponCode.isBlank()) {
            Coupon coupon = (Coupon) couponRepository.findByCode(couponCode)
                    .orElseThrow(() -> new AppException(ErrorHandler.COUPON_NOT_FOUND, "Mã coupon không tồn tại."));

            coupon.setUsedCount(coupon.getUsedCount() + 1);
            if (coupon.getUsageLimit() <= 0) {
                coupon.setIsActive(false);
                throw new AppException(ErrorHandler.COUPON_LIMIT_REACHED, "Mã coupon đã đạt giới hạn sử dụng.");
            }
            coupon.setUsageLimit(coupon.getUsageLimit() - 1);

            CouponUsage couponUsage = new CouponUsage();
            couponUsage.setCustomer(customer);
            couponUsage.setCoupon(coupon);
            couponUsage.setUsedAt(LocalDateTime.now());
            couponUsageRepository.save(couponUsage);
            couponRepository.save(coupon);
        }

        if (selectedPromotionIds != null && !selectedPromotionIds.isEmpty()) {
            for (Integer promotionId : selectedPromotionIds) {
                Promotion promotion = promotionRepository.findById(promotionId)
                        .orElseThrow(() -> new AppException(ErrorHandler.PROMOTION_NOT_FOUND, "Khuyến mãi không tồn tại."));
                promotionService.applyPromotion(promotion, customer);
            }
        }

        Movie movie = movieRepository.findById(ticketBooking.getShowtime().getMovie().getMovieID())
                .orElseThrow(() -> new AppException(ErrorHandler.MOVIE_NOT_EXISTED));

        if (movie.getTotalMoney() == null || movie.getTotalMoneyWithoutFood() == null
                || movie.getTotalMoneyFood() == null || movie.getTotalMoneyDiscount() == null) {
            movie.setTotalMoney(0.0);
            movie.setTotalMoneyWithoutFood(0.0);
            movie.setTotalMoneyFood(0.0);
            movie.setTotalMoneyDiscount(0.0);
            movie.setBuyFromScores(0.0);
            movieRepository.save(movie);
        }

        // Loyalty rules removed — skip point awarding
        Integer seller = ticketBooking.getShowtime().getMovie().getSeller();
        Double totalMoney = ticketBooking.getTotalPrice();
        Double totalMoneyWithoutFoodAndDiscount = ticketBooking.getTicketDetails().stream()
                .filter(booking -> booking.getBooking().getBookingID().equals(ticketBooking.getBookingID()))
                .mapToDouble(TicketDetail::getUnitPrice)
                .sum();
        Double totalMoneyFood = ticketBooking.getBookingFoodAndDrinks() == null ? 0.0 : ticketBooking.getBookingFoodAndDrinks().stream()
                .filter(booking -> booking.getBooking() != null && booking.getBooking().getBookingID().equals(ticketBooking.getBookingID()))
                .mapToDouble(food -> food.getQuantity() * (food.getUnitPrice() != null ? food.getUnitPrice() : 0.0))
                .sum();
        Double totalMoneyDiscount = ticketBooking.getShowtime().getMovie().getTotalMoneyWithoutFood()
                + ticketBooking.getShowtime().getMovie().getTotalMoneyFood()
                - ticketBooking.getShowtime().getMovie().getTotalMoney();

        ticketBooking.setStatus("Success");
        if (paidTotal != null && paidTotal > 0) {
            ticketBooking.setTotalPrice(paidTotal);
        }
        ticketBooking.getShowtime().getMovie().setSeller(seller + 1);
        ticketBooking.getShowtime().getMovie().setTotalMoney(ticketBooking.getShowtime().getMovie().getTotalMoney() + totalMoney);
        ticketBooking.getShowtime().getMovie().setTotalMoneyWithoutFood(ticketBooking.getShowtime().getMovie().getTotalMoneyWithoutFood() + totalMoneyWithoutFoodAndDiscount);
        ticketBooking.getShowtime().getMovie().setTotalMoneyFood(ticketBooking.getShowtime().getMovie().getTotalMoneyFood() + totalMoneyFood);
        ticketBooking.getShowtime().getMovie().setTotalMoneyDiscount(ticketBooking.getShowtime().getMovie().getTotalMoneyDiscount() + totalMoneyDiscount);

        // Loyalty rules removed — no point awarding

        ticketBookingRepository.save(ticketBooking);

        exportMovieDateService.updateExportMovieDate(
                movie,
                LocalDate.now(),
                totalMoney,
                totalMoneyWithoutFoodAndDiscount,
                totalMoneyDiscount,
                totalMoneyFood,
                0
        );
    }

    private void markBookingFailed(TicketBooking ticketBooking) {
        if ("Success".equalsIgnoreCase(ticketBooking.getStatus())) {
            return;
        }
        if ("Cancelled".equalsIgnoreCase(ticketBooking.getStatus())) {
            return;
        }

        ticketBooking.setStatus("Cancelled");
        List<TicketDetail> ticketDetails = ticketBooking.getTicketDetails();
        for (TicketDetail ticketDetail : ticketDetails) {
            ticketDetail.setCheckSeat("Blank");
        }
        ticketDetailRepository.saveAll(ticketDetails);
        ticketBookingRepository.save(ticketBooking);
    }

    private PaymentMethod resolvePaymentMethod(Integer paymentId, String paymentGateway) {
        if (paymentId != null) {
            return paymentMethodRepository.findById(Long.valueOf(paymentId)).orElse(null);
        }
        if (paymentGateway == null || paymentGateway.isBlank()) {
            return null;
        }
        String canonical = canonicalGateway(paymentGateway);
        if (canonical.isBlank()) {
            return null;
        }

        String displayType = "PAYOS".equals(canonical) ? "PayOS" : "VNPay";
        return paymentMethodRepository.findByTypeIgnoreCase(displayType)
                .orElseGet(() -> paymentMethodRepository.save(new PaymentMethod(
                        null,
                        displayType,
                        ""
                )));
    }

    private String normalizeGateway(String paymentGateway) {
        if (paymentGateway == null) {
            return "";
        }
        return paymentGateway.trim().replace("_", "").replace("-", "").toUpperCase(Locale.ROOT);
    }

    private String canonicalGateway(String paymentGateway) {
        String normalized = normalizeGateway(paymentGateway);
        if ("PAYOS".equals(normalized)) {
            return "PAYOS";
        }
        if ("VNPAY".equals(normalized)) {
            return "VNPAY";
        }
        return "";
    }

    private String createPayOsPaymentLink(TicketBooking ticketBooking, Double totalMoney) {
        PayOS payOS = requirePayOsClient();
        long orderCode = generateUniqueOrderCode();
        long amount = Math.round(totalMoney == null ? ticketBooking.getTotalPrice() : totalMoney);

        try {
            PaymentLinkItem item = PaymentLinkItem.builder()
                    .name("Thanh toan ve xem phim")
                    .quantity(1)
                    .price(amount)
                    .build();

            String bookingIdStr = String.valueOf(ticketBooking.getBookingID());
            CreatePaymentLinkRequest paymentData = CreatePaymentLinkRequest.builder()
                    .orderCode(orderCode)
                    .amount(amount)
                    .description("Booking " + ticketBooking.getBookingID())
                    .item(item)
                    .returnUrl(buildPayOsReturnUrl(payOsProperties.getTicketReturnUrl(), orderCode, "success", bookingIdStr))
                    .cancelUrl(buildPayOsReturnUrl(payOsProperties.getTicketCancelUrl(), orderCode, "cancel", bookingIdStr))
                    .build();

            CreatePaymentLinkResponse response = payOS.paymentRequests().create(paymentData);
            if (response.getCheckoutUrl() == null || response.getCheckoutUrl().isBlank()) {
                throw new RuntimeException("PAYOS did not return checkoutUrl");
            }

            ticketBooking.setPayosOrderCode(String.valueOf(orderCode));
            ticketBooking.setPayosPaymentLinkId(response.getPaymentLinkId());
            ticketBookingRepository.save(ticketBooking);
            return response.getCheckoutUrl();
        } catch (Exception e) {
            throw new RuntimeException("Không thể tạo link thanh toán PAYOS", e);
        }
    }

    private long generateUniqueOrderCode() {
        long orderCode = System.currentTimeMillis() / 1000;
        int attempts = 0;
        while (ticketBookingRepository.findByPayosOrderCode(String.valueOf(orderCode)).isPresent()) {
            orderCode++;
            attempts++;
            if (attempts > 10_000) {
                throw new RuntimeException("Không thể sinh orderCode duy nhất cho PAYOS");
            }
        }
        return orderCode;
    }

    private PayOS requirePayOsClient() {
        if (payOsProperties.getClientId() == null || payOsProperties.getClientId().isBlank()
                || payOsProperties.getApiKey() == null || payOsProperties.getApiKey().isBlank()
                || payOsProperties.getChecksumKey() == null || payOsProperties.getChecksumKey().isBlank()) {
            throw new RuntimeException("PAYOS chưa được cấu hình đầy đủ");
        }

        PayOS payOS = payOSProvider.getIfAvailable();
        if (payOS == null) {
            throw new RuntimeException("Không khởi tạo được PAYOS client");
        }
        return payOS;
    }

    private WebhookData verifyPayOsWebhook(Map<String, Object> payload) {
        PayOS payOS = payOSProvider.getIfAvailable();
        if (payOS == null) {
            return null;
        }
        try {
            return payOS.webhooks().verify(payload);
        } catch (Exception e) {
            return null;
        }
    }

    private boolean isPayOsResult(PaymentResultRequest request) {
        return (request.getPaymentGateway() != null && request.getPaymentGateway().equalsIgnoreCase("payos"))
                || (request.getPayosOrderCode() != null && !request.getPayosOrderCode().isBlank());
    }

    private String valueAsString(Object value) {
        return value == null ? "" : String.valueOf(value);
    }

    private String buildPayOsReturnUrl(String baseUrl, long orderCode, String status, String id) {
        String query = "orderCode=" + orderCode + "&status=" + status + "&id=" + id + "&paymentGateway=payos";
        if (baseUrl == null || baseUrl.isBlank()) {
            return "http://localhost:5173/payment-success?" + query;
        }
        String normalized = baseUrl.trim();
        // If baseUrl already contains all required params, return it as is
        if (normalized.contains("orderCode=") && normalized.contains("status=") && normalized.contains("id=")) {
            return normalized;
        }
        // Otherwise, append missing query params
        return normalized + (normalized.contains("?") ? "&" : "?") + query;
    }

    private boolean isSuccessStatus(String status) {
        if (status == null) {
            return false;
        }
        String normalized = status.trim().toLowerCase();
        return "success".equals(normalized)
                || "succes".equals(normalized)
                || "paid".equals(normalized)
                || "succeeded".equals(normalized);
    }

    private boolean isFailureStatus(String status) {
        if (status == null) {
            return false;
        }
        String normalized = status.trim().toLowerCase();
        return "cancel".equals(normalized)
                || "cancelled".equals(normalized)
                || "canceled".equals(normalized)
                || "fail".equals(normalized)
                || "failed".equals(normalized)
                || "error".equals(normalized)
                || "expired".equals(normalized);
    }

    private String writeMetadata(Map<String, Object> payload) {
        try {
            return objectMapper.writeValueAsString(payload);
        } catch (JsonProcessingException e) {
            return null;
        }
    }

    @Override
    public List<PaymentMethod> getAllPayment() {
        return paymentMethodRepository.findAll();
    }

    // Pay-by-points and exchange-point methods removed as feature is deleted

}

package movie.swp391.serviceImp;

import lombok.AccessLevel;
import lombok.RequiredArgsConstructor;
import lombok.experimental.FieldDefaults;
import movie.swp391.entity.*;
import movie.swp391.entity.*;
import movie.swp391.exception.AppException;
import movie.swp391.exception.ErrorHandler;
import movie.swp391.repository.*;
import movie.swp391.repository.*;
import movie.swp391.request.CreateSeatRequest;
import movie.swp391.request.UpdateSeatRequest;
import movie.swp391.response.SeatFromCityresponse;
import movie.swp391.service.SeatService;
import org.springframework.stereotype.Service;

import java.time.LocalDate;
import java.time.LocalTime;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

@Service
@RequiredArgsConstructor
@FieldDefaults(level = AccessLevel.PRIVATE, makeFinal = true)

public class SeatServiceImpl implements SeatService {

    CityRepository cityRepository;
    CinemaRoomRepository cinemaRoomRepository;
    SeatRepository seatRepository;
    SeatTypeRepository seatTypeRepository;
    TicketDetailRepository ticketDetailRepository;

@Override
    public List<SeatFromCityresponse> viewAllSeat() {
        List<City> cities = cityRepository.findAll();
        List<SeatFromCityresponse> response = new ArrayList<>();

        for (City city : cities) {
            List<SeatFromCityresponse.CinemaDTO> cinemaDTOs = new ArrayList<>();

            for (Cinema cinema : city.getCinemas()) {
                List<SeatFromCityresponse.CinemaRoomDTO> roomDTOs = new ArrayList<>();

                for (CinemaRoom room : cinema.getCinemaRooms()) {
                    List<SeatFromCityresponse.SeatDTO> seatDTOs = new ArrayList<>();

                    for (Seat seat : room.getSeats()) {
                        String seatTypeLabel = resolveSeatTypeLabel(seat);
                        SeatFromCityresponse.SeatDTO seatDTO = SeatFromCityresponse.SeatDTO.builder()
                                .seatID(seat.getSeatID())
                                .seatName(seat.getSeatName())
                                .seatType(seatTypeLabel)
                                .price(resolveSeatPrice(seat))
                                .isAvailable(seat.getIsAvailable())
                                .build();
                        seatDTOs.add(seatDTO);
                    }

                    SeatFromCityresponse.CinemaRoomDTO roomDTO = SeatFromCityresponse.CinemaRoomDTO.builder()
                            .cinemaRoomID(room.getCinemaRoomID())
                            .roomName(room.getRoomName())
                            .seatQuantity(room.getSeatQuantity())
                            .seats(seatDTOs)
                            .build();

                    roomDTOs.add(roomDTO);
                }

                SeatFromCityresponse.CinemaDTO cinemaDTO = SeatFromCityresponse.CinemaDTO.builder()
                        .cinemaID(cinema.getCinemaID())
                        .name(cinema.getName())

                        .cinemaRooms(roomDTOs)
                        .build();

                cinemaDTOs.add(cinemaDTO);
            }

            SeatFromCityresponse cityResponse = SeatFromCityresponse.builder()
                    .cityID(city.getCityID())
                    .name(city.getName())
                    .cinemas(cinemaDTOs)
                    .build();

            response.add(cityResponse);
        }
        return response;
    }


    public String createSeatsForRoom(CreateSeatRequest request) {
        CinemaRoom room = cinemaRoomRepository.findById(request.getCinemaRoomId())
                .orElseThrow(() -> new AppException(ErrorHandler.CINEMA_ROOM_NOT_FOUND));

        // 1. Kiểm tra trùng lặp trong request
        Set<String> seenSeatNames = new HashSet<>();
        for (CreateSeatRequest.SeatDTO dto : request.getSeats()) {
            if (!seenSeatNames.add(dto.getSeatName())) {
                throw new AppException(ErrorHandler.DUPLICATE_SEAT_IN_REQUEST,
                        "Ghế '" + dto.getSeatName() + "' bị trùng lặp trong danh sách yêu cầu.");
            }
        }

        // 2. Đếm số lượng ghế đã tồn tại trong phòng
        int existingSeatCount = seatRepository.countByCinemaRoom(room);
        int roomCapacity = room.getSeatQuantity(); // field quantity trong CinemaRoom

        List<Seat> createdSeats = new ArrayList<>();
        int processedCount = 0;

        for (CreateSeatRequest.SeatDTO dto : request.getSeats()) {
            if (existingSeatCount + processedCount >= roomCapacity) {
                // Vượt quá giới hạn => dừng lại và quăng lỗi
                throw new AppException(ErrorHandler.CINEMA_ROOM_FULL,
                        "Phòng chiếu đã đầy. Chỉ tạo được " + processedCount + " ghế trước khi vượt quá giới hạn " + roomCapacity + ".");
            }

            boolean exists = seatRepository.existsBySeatNameAndCinemaRoom(dto.getSeatName(), room);
            if (exists) {
                throw new AppException(ErrorHandler.SEAT_ALREADY_EXISTS,
                        "Ghế '" + dto.getSeatName() + "' đã tồn tại trong phòng chiếu này.");
            }

            SeatType resolvedType = resolveSeatType(dto.getSeatTypeId(), dto.getSeatType());

            Seat seat = Seat.builder()
                    .seatName(dto.getSeatName())
                    .seatType(resolveSeatTypeLabel(resolvedType, dto.getSeatType()))
                    .seatTypeRef(resolvedType)
                    .price(resolveSeatPrice(dto.getPrice(), resolvedType))
                    .cinemaRoom(room)
                    .build();

            createdSeats.add(seat);
            processedCount++;
        }

        seatRepository.saveAll(createdSeats);
        return "Đã tạo thành công " + processedCount + " ghế.";
    }

    public String updateSeat(UpdateSeatRequest request) {
        CinemaRoom room = cinemaRoomRepository.findById(request.getCinemaRoomId())
                .orElseThrow(() -> new AppException(ErrorHandler.CINEMA_ROOM_NOT_FOUND));

        Seat seat = seatRepository.findById(request.getSeatId())
                .orElseThrow(() -> new AppException(ErrorHandler.SEAT_NOT_FOUND));

        if (!seat.getCinemaRoom().getCinemaRoomID().equals(room.getCinemaRoomID())) {
            throw new AppException(ErrorHandler.SEAT_NOT_BELONG);
        }

        SeatType resolvedType = resolveSeatType(request.getSeatTypeId(), request.getSeatType());

        seat.setSeatName(request.getSeatName());
        if (resolvedType != null || request.getSeatType() != null) {
            seat.setSeatType(resolveSeatTypeLabel(resolvedType, request.getSeatType()));
            seat.setSeatTypeRef(resolvedType);
        }
        if (request.getPrice() != null) {
            seat.setPrice(request.getPrice());
        } else if (resolvedType != null) {
            seat.setPrice(resolvedType.getBasePrice());
        }
        seatRepository.save(seat);

        return "Đã cập nhật thành công";
    }

    @Override
    public void turnOnOffSeat(List<Integer> seatId){
        List<Seat> seats = seatRepository.findAllById(seatId);

        for (Seat seat : seats) {
            if (seat.getIsAvailable()) {
                if (checkIfSeatActive(seat.getSeatID())) {
                    String mess = "Chỗ ngồi " + seat.getSeatName() + " đã có người đặt có suất chiếu ở tương lai";
                    throw new AppException(ErrorHandler.SEAT_IN_ACTIVE, mess);
                }
            }
        }
        for (Seat seat : seats) {
            seat.setIsAvailable(!seat.getIsAvailable());
        }
        seatRepository.saveAll(seats);
    }

    public boolean checkIfSeatActive(Integer seatId) {
        List<TicketDetail> details = ticketDetailRepository.findBySeat_SeatIDAndCheckSeat(seatId, "Occupied");

        LocalDate nowDate = LocalDate.now();
        LocalTime nowTime = LocalTime.now();

        for (TicketDetail td : details) {
            LocalDate showDate = td.getBooking().getShowtime().getDate();
            LocalTime showTime = td.getBooking().getShowtime().getTime();

            if (showDate.isAfter(nowDate) || (showDate.isEqual(nowDate) && showTime.isAfter(nowTime))) {
                return true;
            }
        }

        return false;
    }

    private SeatType resolveSeatType(Integer seatTypeId, String seatTypeLabel) {
        if (seatTypeId != null) {
            return seatTypeRepository.findById(seatTypeId)
                    .orElseThrow(() -> new AppException(ErrorHandler.SEAT_TYPE_NOT_FOUND));
        }
        if (seatTypeLabel == null || seatTypeLabel.isBlank()) {
            return null;
        }
        return seatTypeRepository.findByCodeIgnoreCase(seatTypeLabel.trim())
                .or(() -> seatTypeRepository.findByNameIgnoreCase(seatTypeLabel.trim()))
                .orElse(null);
    }

    private String resolveSeatTypeLabel(SeatType seatType) {
        if (seatType != null && seatType.getName() != null && !seatType.getName().isBlank()) {
            return seatType.getName();
        }
        return null;
    }

    private String resolveSeatTypeLabel(Seat seat) {
        if (seat == null) {
            return null;
        }
        if (seat.getSeatTypeRef() != null && seat.getSeatTypeRef().getName() != null && !seat.getSeatTypeRef().getName().isBlank()) {
            return seat.getSeatTypeRef().getName();
        }
        return seat.getSeatType();
    }

    private String resolveSeatTypeLabel(SeatType seatType, String fallback) {
        String label = resolveSeatTypeLabel(seatType);
        return label != null ? label : fallback;
    }

    private Double resolveSeatPrice(Double requestedPrice, SeatType seatType) {
        if (requestedPrice != null) {
            return requestedPrice;
        }
        if (seatType != null && seatType.getBasePrice() != null) {
            return seatType.getBasePrice();
        }
        return 0.0;
    }

    private Double resolveSeatPrice(Seat seat) {
        if (seat == null) {
            return 0.0;
        }
        if (seat.getPrice() != null) {
            return seat.getPrice();
        }
        if (seat.getSeatTypeRef() != null && seat.getSeatTypeRef().getBasePrice() != null) {
            return seat.getSeatTypeRef().getBasePrice();
        }
        return 0.0;
    }

}

package movie.swp391.serviceImp;

import lombok.AccessLevel;
import lombok.RequiredArgsConstructor;
import lombok.experimental.FieldDefaults;
