                    initial={{ scale: 0.5, opacity: 0 }}
                    animate={{ scale: 1, opacity: 1 }}
                    exit={{ scale: 0.5, opacity: 0 }}
                    transition={{ duration: 0.25 }}
                    className="absolute -right-2 -bottom-1 text-[#ff7120] font-extrabold"
                    style={{ fontWeight: 900, fontSize: '2rem' }}
                  >
                    ⌟
                  </motion.span>
