              ) : (
                <span className="text-xs">Khuyến Mãi</span>
              )}
            </button>
            <button type="button" onClick={() => handleMenuClick('about-us')} className="px-2 py-2 text-xs font-semibold rounded hover:bg-[#ff7120]/10 transition-colors duration-150 bg-transparent border-0 focus:outline-none">
              {activeSection === 'about-us' && location.pathname === '/' ? (
                <span className="relative">
                  <motion.span
                    initial={{ scale: 0.5, opacity: 0 }}
                    animate={{ scale: 1, opacity: 1 }}
                    exit={{ scale: 0.5, opacity: 0 }}
                    transition={{ duration: 0.25 }}
                    className="absolute -left-2 -top-1 text-[#ff7120] font-extrabold"
                    style={{ fontWeight: 900, fontSize: '2rem' }}
                  >
                    ⌜
                  </motion.span>
                  <span className="relative z-10 inline-block text-xs">
                    <ScrambleText text="Về Chúng Tôi" triggerKey={activeSection} className="inline-block" />
                  </span>
                  <motion.span
                    initial={{ scale: 0.5, opacity: 0 }}
                    animate={{ scale: 1, opacity: 1 }}
                    exit={{ scale: 0.5, opacity: 0 }}
                    transition={{ duration: 0.25 }}
                    className="absolute -right-2 -bottom-1 text-[#ff7120] font-extrabold"
                    style={{ fontWeight: 900, fontSize: '2rem' }}
                  >
                    ⌟
                  </motion.span>
                </span>
              ) : (
                <span className="text-xs">Về Chúng Tôi</span>
              )}
            </button>
          </nav>
          {/* Nhóm icon phải */}
          <div className="flex items-center gap-1 md:gap-2 ml-1 md:ml-2 flex-wrap">
            {/* Search icon */}
            <div className="relative group flex items-center" ref={searchRef}>
              {showSearch && (
                <input
                  type="text"
                  className="w-36 md:w-52 text-sm md:text-base border border-[#ff7120] rounded-xl px-2 md:px-4 py-2 focus:ring-2 focus:ring-[#ff7120] outline-none bg-white text-black placeholder:text-gray-500 transition-all duration-200 absolute right-10 md:right-12 top-1/2 -translate-y-1/2 shadow-lg z-[9999]"
                  placeholder="Tìm tên phim..."
                  value={searchValue}
                  onChange={(e) => setSearchValue(e.target.value)}
                  onKeyDown={handleInputKeyDown}
                  autoFocus
                />
              )}
              <button
                className="h-9 w-9 md:h-12 md:w-12 flex items-center justify-center rounded-full hover:bg-[#ff7120]/20 transition-colors"
                onClick={e => { e.stopPropagation(); setShowSearch(prev => !prev); }}
                style={{ zIndex: 52 }}
              >
                <FiSearch size={20} className="md:text-[24px] text-[#00c9a7]" />
              </button>
              {/* Kết quả search */}
              {showSearch && searchResults && searchResults.length > 0 && (
                <>
                  {/* Mobile: full width, top header, responsive */}
                  <div className="fixed left-0 right-0 mx-auto w-[95vw] max-w-xs top-[60px] md:hidden bg-white border-2 border-[#ff7120] rounded-xl shadow-lg z-[9999] p-2">
                    <div className="w-full max-h-80 overflow-y-auto">
                      {searchResults.map((movie) => (
                        <Link
                          key={movie.movieID}
                          to={`/movies/${normalize(movie.title)}`}
                          className="flex items-center gap-3 px-4 py-3 hover:bg-gradient-to-r hover:bg-orange-100 transition rounded-lg"
                          onClick={() => {
                            setShowSearch(false);
                            setSearchValue("");
                            setSearchResults([]);
                          }}
                        >
                          <img src={movie.poster} alt={movie.title} className="w-10 h-14 object-cover rounded shadow border border-orange-200" />
                          <span className="font-semibold text-gray-800 group-hover:text-orange-700 text-base">{movie.title}</span>
                        </Link>
                      ))}
                    </div>
                  </div>
                  {/* Desktop/tablet: giữ nguyên vị trí cũ */}
                  <div className="fixed hidden md:block" style={{top: 65, left: 646, width: 320, background: 'white', border: '2px solid #ff7120', borderRadius: 12, boxShadow: '0 8px 32px rgba(0,0,0,0.18)', zIndex: 9999, padding: 8}}>
                    <div className="w-full max-h-80 overflow-y-auto">
                      {searchResults.map((movie) => (
                        <Link
                          key={movie.movieID}
                          to={`/movies/${normalize(movie.title)}`}
                          className="flex items-center gap-3 px-4 py-3 hover:bg-gradient-to-r hover:bg-orange-100 transition rounded-lg"
                          onClick={() => {
                            setShowSearch(false);
                            setSearchValue("");
                            setSearchResults([]);
                          }}
                        >
                          <img src={movie.poster} alt={movie.title} className="w-10 h-14 object-cover rounded shadow border border-orange-200" />
                          <span className="font-semibold text-gray-800 group-hover:text-orange-700 text-base">{movie.title}</span>
                        </Link>
                      ))}
                    </div>
                  </div>
                </>
              )}
            </div>
            {/* Profile/Login */}
            <div className="relative group" ref={menuRef}>
              {isLoggedIn ? (
                <div className="relative flex items-center">
                  <button
                    className="h-9 w-9 md:h-12 md:w-12 flex items-center justify-center rounded-full hover:bg-[#ff7120]/20 transition-colors"
                    onClick={() => setShowUserMenu(!showUserMenu)}
                  >
                    <FiUser size={20} className="md:text-[24px] text-[#ff7120]" />
                  </button>
                  {showUserMenu && (
                    <div className="absolute right-0 top-16 w-48 bg-black/90 rounded-lg shadow-lg py-2 z-[9999]">
                      <Link
                        to="/profile"
                        className="block px-4 py-2 text-sm text-white hover:bg-orange-600 hover:text-white"
                        onClick={handleProfileClick}
                      >
                        Thông tin cá nhân
                      </Link>
                      <button
                        onClick={handleLogout}
                        className="block w-full hover:bg-orange-600 text-left px-4 py-2 text-sm text-white hover:text-white"
                      >
                        Đăng xuất
                      </button>
                    </div>
                  )}
                </div>
              ) : (
                <button
                  onClick={() => setShowLoginModal(true)}
                  className="ml-1 md:ml-2 px-3 md:px-6 py-2 bg-[#ff7120] hover:bg-orange-600 text-white font-bold rounded-lg shadow transition-all duration-200 uppercase tracking-wide text-sm md:text-base border-2 border-[#ff7120]"
                  style={{ minWidth: 80 }}
                >
                  Đăng nhập
                </button>
              )}
            </div>
          </div>
        </div>
      </header>
      {/* Login Modal */}
      <LoginModal
        isOpen={showLoginModal}
        onClose={() => setShowLoginModal(false)}
        onLoginSuccess={(username) => {
          // setUser(username); // This line is removed as per the new_code
          setShowLoginModal(false);
          // LoginVersionContext đã được trigger trong LoginModal rồi
        }}
      />
    </>
  );
};

export default Header;

import React, { useEffect, useState } from "react";
import { Form, Input, Select } from "antd";
import { HomeOutlined, EnvironmentOutlined } from "@ant-design/icons";
import { createCinema, getAllCities } from "../../../service/cinema";
import { showErrorToast, showSuccessToast } from "../../../utils/toast";

const AddCinema = ({ onSuccess, onClose }) => {
  const [form] = Form.useForm();
  const [cities, setCities] = useState([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    getAllCities().then((response) => {
      if (response.success && Array.isArray(response.data)) {
        setCities(response.data);
      }
    });
  }, []);

  const handleSubmit = async () => {
    try {
      const values = await form.validateFields();
      setLoading(true);

      const response = await createCinema({
        name: values.name?.trim(),
        address: values.address?.trim(),
        cityId: Number(values.cityId),
      });

      if (response.success) {
        showSuccessToast(response.message || "Them rap phim thanh cong");
        form.resetFields();
        onSuccess && onSuccess();
      } else {
        showErrorToast(response.message || "Them rap phim that bai");
      }
    } catch (error) {
      showErrorToast(error?.response?.data?.message || error?.message || "Them rap phim that bai");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="mt-4">
      <Form form={form} layout="vertical" className="space-y-4">
        <div className="p-4 bg-gradient-to-br from-blue-50 to-indigo-50 rounded-xl border border-blue-200">
          <div className="flex items-center gap-2 mb-3">
            <div className="w-6 h-6 bg-gradient-to-br from-blue-500 to-indigo-600 rounded-lg flex items-center justify-center">
              <HomeOutlined className="text-white text-sm" />
            </div>
            <h3 className="text-lg font-semibold text-gray-900">Thong tin rap phim</h3>
          </div>

          <Form.Item
            label="Ten rap"
            name="name"
            rules={[{ required: true, message: "Vui long nhap ten rap" }]}
            className="mb-2"
          >
            <Input placeholder="Nhap ten rap phim" className="rounded-lg" maxLength={100} />
          </Form.Item>

          <Form.Item
            label="Dia chi"
            name="address"
            rules={[{ required: true, message: "Vui long nhap dia chi" }]}
            className="mb-2"
          >
            <Input.TextArea placeholder="Nhap dia chi" rows={3} className="rounded-lg" maxLength={255} />
          </Form.Item>
        </div>

        <div className="p-4 bg-gradient-to-br from-green-50 to-emerald-50 rounded-xl border border-green-200">
          <div className="flex items-center gap-2 mb-3">
            <div className="w-6 h-6 bg-gradient-to-br from-green-500 to-emerald-600 rounded-lg flex items-center justify-center">
              <EnvironmentOutlined className="text-white text-sm" />
            </div>
            <h3 className="text-lg font-semibold text-gray-900">Thanh pho</h3>
          </div>

          <Form.Item
            label="Chon thanh pho"
            name="cityId"
            rules={[{ required: true, message: "Vui long chon thanh pho" }]}
            className="mb-2"
          >
            <Select
              placeholder="Chon thanh pho"
              options={cities.map((city) => ({ label: city.name, value: city.cityId }))}
            />
          </Form.Item>
        </div>

        <div className="flex gap-3 mt-6">
          <button
            type="button"
            onClick={onClose}
            className="flex-1 border border-gray-300 text-gray-700 py-2 px-4 rounded-lg hover:bg-gray-50 transition-all duration-200 font-medium"
          >
            Huy
          </button>
          <button
            type="button"
            onClick={handleSubmit}
            disabled={loading}
            className="flex-1 bg-gradient-to-r from-blue-600 to-indigo-600 text-white py-2 px-4 rounded-lg hover:from-blue-700 hover:to-indigo-700 transition-all duration-200 font-medium disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {loading ? "Dang them..." : "Them rap phim"}
          </button>
        </div>
      </Form>
    </div>
  );
};

export default AddCinema;

import React, { useEffect, useMemo, useState } from "react";
import { Button, Modal, Tooltip } from "antd";
import {
  DeleteOutlined,
  EditOutlined,
  HomeOutlined,
  InboxOutlined,
  SearchOutlined,
} from "@ant-design/icons";
import { deleteCinema, getAllCinemas } from "../../../service/cinema";
import { showErrorToast, showSuccessToast } from "../../../utils/toast";
import AddCinema from "./AddCinema";
import EditCinema from "./EditCinema";

const CinemaManagement = ({ addModalVisible, setAddModalVisible }) => {
  const [loading, setLoading] = useState(false);
  const [cinemas, setCinemas] = useState([]);
  const [searchText, setSearchText] = useState("");
  const [pagination, setPagination] = useState({ current: 1, pageSize: 8 });

  const [showAdd, setShowAdd] = useState(false);
  const modalVisible = addModalVisible !== undefined ? addModalVisible : showAdd;
  const setModalVisible = setAddModalVisible !== undefined ? setAddModalVisible : setShowAdd;

  const [editModalVisible, setEditModalVisible] = useState(false);
  const [deleteModalVisible, setDeleteModalVisible] = useState(false);
  const [selectedCinema, setSelectedCinema] = useState(null);

  const fetchCinemas = async () => {
    setLoading(true);
    try {
      const response = await getAllCinemas();
      if (response.success) {
        setCinemas(Array.isArray(response.data) ? response.data : []);
      } else {
        showErrorToast(response.message || "Khong lay duoc danh sach rap phim");
      }
    } catch (error) {
      showErrorToast("Mat ket noi server");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchCinemas();
  }, []);

  const filteredCinemas = useMemo(() => {
    if (!searchText) return cinemas;
    const keyword = searchText.toLowerCase();

    return cinemas.filter(
      (cinema) =>
        cinema.name?.toLowerCase().includes(keyword) ||
        cinema.address?.toLowerCase().includes(keyword) ||
        cinema.city?.toLowerCase().includes(keyword)
    );
  }, [cinemas, searchText]);

  const totalPages = Math.max(1, Math.ceil(filteredCinemas.length / pagination.pageSize));
  const currentPage = Math.min(pagination.current, totalPages);
  const startIdx = (currentPage - 1) * pagination.pageSize;
  const pageData = filteredCinemas.slice(startIdx, startIdx + pagination.pageSize);

  const handleDeleteConfirm = async () => {
    if (!selectedCinema) return;

    const response = await deleteCinema(selectedCinema.cinemaId);
    if (response.success) {
      showSuccessToast(response.message || "Xoa rap phim thanh cong");
      fetchCinemas();
    } else {
      showErrorToast(response.message || "Xoa rap phim that bai");
    }

    setDeleteModalVisible(false);
    setSelectedCinema(null);
  };

  return (
    <>
      <div className="flex items-center justify-between gap-4 mb-4 p-4 bg-gradient-to-r from-gray-50 to-slate-50 rounded-lg border border-gray-200">
        <div className="text-sm text-gray-600">Tong rap phim: {filteredCinemas.length}</div>
        <div className="relative">
          <SearchOutlined className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 z-10" />
          <input
            placeholder="Tim kiem rap phim..."
            value={searchText}
            onChange={(e) => {
              setSearchText(e.target.value);
              setPagination((prev) => ({ ...prev, current: 1 }));
            }}
            className="pl-10 w-72 h-8 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-400 focus:border-blue-400 focus:outline-none text-sm shadow-sm"
            style={{ color: "black", backgroundColor: "white" }}
          />
        </div>
      </div>

      {pageData.length === 0 ? (
        <div className="bg-gradient-to-br from-gray-50 to-slate-50 rounded-xl p-12 text-center border border-gray-200">
          <InboxOutlined className="text-6xl text-gray-300 mb-4" />
          <h3 className="text-lg font-medium text-gray-900 mb-2">Khong tim thay rap phim nao</h3>
          <p className="text-gray-500">Thu thay doi bo loc hoac them rap phim moi</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
          {pageData.map((cinema) => (
            <div
              key={cinema.cinemaId}
              className="bg-gradient-to-br from-white via-blue-50 to-indigo-100 rounded-xl border-2 transition-all duration-300 hover:shadow-lg hover:scale-[1.02] relative overflow-hidden border-gray-200 hover:border-blue-300"
            >
              <div className="p-3 border-b border-gray-200 flex items-center justify-between bg-gradient-to-r from-blue-100 to-indigo-100">
                <div className="flex items-center gap-2">
                  <HomeOutlined className="text-blue-600" />
                  <span className="font-bold text-blue-700">{cinema.name}</span>
                </div>
              </div>

              <div className="p-3 bg-gradient-to-br from-white to-blue-50">
                <div className="space-y-2 mb-3">
                  <div className="flex justify-between text-xs gap-2">
                    <span className="text-gray-500">Thanh pho:</span>
                    <span className="text-gray-700 text-right">{cinema.city || "-"}</span>
                  </div>
                  <div className="flex justify-between text-xs gap-2">
                    <span className="text-gray-500">Dia chi:</span>
                    <span className="text-gray-700 text-right">{cinema.address}</span>
                  </div>
                  <div className="flex justify-between text-xs gap-2">
                    <span className="text-gray-500">So phong:</span>
                    <span className="text-green-700 font-bold">{cinema.totalRooms || 0}</span>
                  </div>
                </div>

                <div className="flex gap-1">
                  <Tooltip title="Chinh sua">
                    <Button
                      size="small"
                      icon={<EditOutlined className="text-blue-600" />}
                      onClick={() => {
                        setSelectedCinema(cinema);
                        setEditModalVisible(true);
                      }}
                      className="flex-1 border-blue-300 text-blue-700 hover:border-blue-400 hover:text-blue-800 shadow-sm bg-gradient-to-r from-blue-100 to-indigo-100"
                    />
                  </Tooltip>
                  <Tooltip title="Xoa">
                    <Button
                      size="small"
                      icon={<DeleteOutlined className="text-red-600" />}
                      onClick={() => {
                        setSelectedCinema(cinema);
                        setDeleteModalVisible(true);
                      }}
                      className="flex-1 border-red-300 text-red-700 hover:border-red-400 hover:text-red-800 shadow-sm bg-gradient-to-r from-red-100 to-rose-100"
                    />
                  </Tooltip>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      <div className="flex flex-wrap justify-end items-center gap-2 mt-4">
        <button
          className={`w-9 h-9 rounded-xl font-bold shadow transition flex items-center justify-center ${
            currentPage === 1 ? "bg-gray-200 text-gray-400 cursor-not-allowed" : "bg-white text-blue-700 hover:bg-blue-100"
          }`}
          disabled={currentPage === 1}
          onClick={() => setPagination((prev) => ({ ...prev, current: prev.current - 1 }))}
        >
          &lt;
        </button>

        {Array.from({ length: totalPages }, (_, i) => i + 1).map((page) => (
          <button
            key={page}
            className={`w-9 h-9 rounded-xl font-bold shadow transition flex items-center justify-center ${
              currentPage === page
                ? "bg-gradient-to-br from-blue-500 to-indigo-700 text-white scale-105"
                : "bg-white text-blue-700 hover:bg-blue-100"
            }`}
            onClick={() => setPagination((prev) => ({ ...prev, current: page }))}
          >
            {page}
          </button>
        ))}

        <button
          className={`w-9 h-9 rounded-xl font-bold shadow transition flex items-center justify-center ${
            currentPage === totalPages || filteredCinemas.length === 0
              ? "bg-gray-200 text-gray-400 cursor-not-allowed"
              : "bg-white text-blue-700 hover:bg-blue-100"
          }`}
          disabled={currentPage === totalPages || filteredCinemas.length === 0}
          onClick={() => setPagination((prev) => ({ ...prev, current: prev.current + 1 }))}
        >
          &gt;
        </button>

        <select
          className="ml-4 rounded-lg border px-2 py-1 focus:outline-none focus:ring-2 focus:ring-blue-400 focus:border-blue-400 transition bg-white text-blue-700 border-blue-200"
          value={pagination.pageSize}
          onChange={(e) => setPagination({ current: 1, pageSize: Number(e.target.value) })}
        >
          {[8, 16, 32].map((size) => (
            <option key={size} value={size}>
              {size} / page
            </option>
          ))}
        </select>
      </div>

      <Modal
        title="Them rap phim moi"
        open={modalVisible}
        onCancel={() => setModalVisible(false)}
        footer={null}
        width={560}
        className="!rounded-xl"
      >
        <AddCinema
          onSuccess={() => {
            setModalVisible(false);
            fetchCinemas();
          }}
          onClose={() => setModalVisible(false)}
        />
      </Modal>

      <Modal
        title="Chinh sua rap phim"
        open={editModalVisible}
        onCancel={() => {
          setEditModalVisible(false);
          setSelectedCinema(null);
        }}
        footer={null}
        width={560}
        className="!rounded-xl"
      >
        <EditCinema
          cinema={selectedCinema}
          onSuccess={() => {
            setEditModalVisible(false);
            setSelectedCinema(null);
            fetchCinemas();
          }}
          onClose={() => {
            setEditModalVisible(false);
            setSelectedCinema(null);
          }}
        />
      </Modal>

      <Modal
        title="Xac nhan xoa"
        open={deleteModalVisible}
        onOk={handleDeleteConfirm}
        onCancel={() => {
          setDeleteModalVisible(false);
          setSelectedCinema(null);
        }}
        okText="Xoa"
        cancelText="Huy"
        okButtonProps={{ danger: true, loading }}
        className="!rounded-xl"
      >
        <p>Ban co chac chan muon xoa rap phim "{selectedCinema?.name}"?</p>
        <p className="text-red-500 font-medium">Hanh dong nay khong the hoan tac.</p>
      </Modal>
    </>
  );
};

export default CinemaManagement;

import React, { useEffect, useState } from "react";
import { Form, Input, Select } from "antd";
import { EnvironmentOutlined, HomeOutlined } from "@ant-design/icons";
import { getAllCities, updateCinema } from "../../../service/cinema";
import { showErrorToast, showSuccessToast } from "../../../utils/toast";

const EditCinema = ({ cinema, onSuccess, onClose }) => {
  const [form] = Form.useForm();
  const [cities, setCities] = useState([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    getAllCities().then((response) => {
      if (response.success && Array.isArray(response.data)) {
        setCities(response.data);
      }
    });
  }, []);

  useEffect(() => {
    form.setFieldsValue({
      name: cinema?.name || "",
      address: cinema?.address || "",
      cityId: cinema?.cityId,
    });
  }, [cinema, form]);

  const handleSubmit = async () => {
    try {
      const values = await form.validateFields();
      if (!cinema?.cinemaId) return;

      setLoading(true);
      const response = await updateCinema(cinema.cinemaId, {
        name: values.name?.trim(),
        address: values.address?.trim(),
        cityId: Number(values.cityId),
      });

      if (response.success) {
        showSuccessToast(response.message || "Cap nhat rap phim thanh cong");
        onSuccess && onSuccess();
      } else {
        showErrorToast(response.message || "Cap nhat rap phim that bai");
      }
    } catch (error) {
      showErrorToast(error?.response?.data?.message || error?.message || "Cap nhat rap phim that bai");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="mt-4">
      <Form form={form} layout="vertical" className="space-y-4">
        <div className="p-4 bg-gradient-to-br from-blue-50 to-indigo-50 rounded-xl border border-blue-200">
          <div className="flex items-center gap-2 mb-3">
            <div className="w-6 h-6 bg-gradient-to-br from-blue-500 to-indigo-600 rounded-lg flex items-center justify-center">
              <HomeOutlined className="text-white text-sm" />
            </div>
            <h3 className="text-lg font-semibold text-gray-900">Thong tin rap phim</h3>
          </div>

          <Form.Item
            label="Ten rap"
            name="name"
            rules={[{ required: true, message: "Vui long nhap ten rap" }]}
            className="mb-2"
          >
            <Input placeholder="Nhap ten rap phim" className="rounded-lg" maxLength={100} />
          </Form.Item>

          <Form.Item
            label="Dia chi"
            name="address"
            rules={[{ required: true, message: "Vui long nhap dia chi" }]}
            className="mb-2"
          >
            <Input.TextArea placeholder="Nhap dia chi" rows={3} className="rounded-lg" maxLength={255} />
          </Form.Item>
        </div>

        <div className="p-4 bg-gradient-to-br from-green-50 to-emerald-50 rounded-xl border border-green-200">
          <div className="flex items-center gap-2 mb-3">
            <div className="w-6 h-6 bg-gradient-to-br from-green-500 to-emerald-600 rounded-lg flex items-center justify-center">
              <EnvironmentOutlined className="text-white text-sm" />
            </div>
            <h3 className="text-lg font-semibold text-gray-900">Thanh pho</h3>
          </div>

          <Form.Item
            label="Chon thanh pho"
            name="cityId"
            rules={[{ required: true, message: "Vui long chon thanh pho" }]}
            className="mb-2"
          >
            <Select
              placeholder="Chon thanh pho"
              options={cities.map((city) => ({ label: city.name, value: city.cityId }))}
            />
          </Form.Item>
        </div>

        <div className="flex gap-3 mt-6">
          <button
            type="button"
            onClick={onClose}
            className="flex-1 border border-gray-300 text-gray-700 py-2 px-4 rounded-lg hover:bg-gray-50 transition-all duration-200 font-medium"
          >
            Huy
          </button>
          <button
            type="button"
            onClick={handleSubmit}
            disabled={loading}
            className="flex-1 bg-gradient-to-r from-blue-600 to-indigo-600 text-white py-2 px-4 rounded-lg hover:from-blue-700 hover:to-indigo-700 transition-all duration-200 font-medium disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {loading ? "Dang luu..." : "Luu thay doi"}
          </button>
        </div>
      </Form>
    </div>
  );
};

export default EditCinema;

import React, { useState, useEffect } from "react";
import { Form, Input, InputNumber, Select } from "antd";
import { createCinemaRoom, getAllCinemaRooms } from "../../../service/cinemaroom";
import { showSuccessToast, showErrorToast } from "../../../utils/toast";
import { VideoCameraOutlined, HomeOutlined, TeamOutlined } from "@ant-design/icons";

const AddCinemaRoom = ({ onSuccess, onClose }) => {
  const [form] = Form.useForm();
  const [cinemas, setCinemas] = useState([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    // Lấy danh sách phòng chiếu, lọc ra các rạp duy nhất
    getAllCinemaRooms().then(res => {
      if (res.success && Array.isArray(res.data)) {
        const uniqueCinemas = [];
        const cinemaMap = {};
        res.data.forEach(room => {
          if (room.cinemaId && room.name && !cinemaMap[room.cinemaId]) {
            cinemaMap[room.cinemaId] = true;
            uniqueCinemas.push({ id: room.cinemaId, name: room.name });
          }
        });
        setCinemas(uniqueCinemas);
      }
    });
  }, []);

  const handleSubmit = async () => {
    try {
      const values = await form.validateFields();
      setLoading(true);

      const payload = {
        roomName: [values.roomName],
        seatQuantity: Number(values.seatQuantity),
        cinemaId: Number(values.cinemaId),
      };

      const res = await createCinemaRoom(payload);

      if (res?.success) {
        showSuccessToast(res.message || "Tạo phòng chiếu thành công!");
        form.resetFields();
        onSuccess && onSuccess();
      } else {
        showErrorToast(res.message || "Tạo phòng chiếu thất bại!");
      }
    } catch (err) {
