const EditMovie = ({ visible, onCancel, onSuccess, movieID }) => {
  const [form] = Form.useForm();
  const [loading, setLoading] = useState(false);
  const [fetching, setFetching] = useState(true);
  const [posterPreview, setPosterPreview] = useState(null);
  const [trailerUrl, setTrailerUrl] = useState("");
  const [originPosterUrl, setOriginPosterUrl] = useState("");
  const [showtimesLoading, setShowtimesLoading] = useState(false);
  const [movieShowtimes, setMovieShowtimes] = useState([]);
  const [deletingShowtimeId, setDeletingShowtimeId] = useState(null);

  const flattenMovieShowtimes = (data, targetMovieId) => {
    const normalizedMovieId = Number(targetMovieId);
    const result = [];

    data.forEach((city) => {
      city.cinemas?.forEach((cinema) => {
        cinema.cinemaRooms?.forEach((room) => {
          room.showtimes?.forEach((show) => {
            show.times?.forEach((time) => {
              if (Number(time.movieId) !== normalizedMovieId) return;

              result.push({
                id: time.showtimeID,
                showtimeId: time.showtimeID,
                movieId: Number(time.movieId),
                movieTitle: time.movieTitle,
                version: time.version,
                active: Boolean(time.active),
                cityName: city.cityName,
                cinemaID: cinema.cinemaID,
                cinemaName: cinema.name,
                cinemaRoomId: room.cinemaRoomID,
                cinemaRoom: room.roomName,
                date: show.date,
                time: time.time,
                toTime: time.toTime,
              });
            });
          });
        });
      });
    });

    return result.sort((a, b) => {
      const left = dayjs(`${a.date} ${String(a.time).slice(0, 5)}`);
      const right = dayjs(`${b.date} ${String(b.time).slice(0, 5)}`);
      return right.valueOf() - left.valueOf();
    });
  };

  const loadMovieShowtimes = async (targetMovieId = movieID) => {
    if (!targetMovieId) return;

    setShowtimesLoading(true);
    try {
      const response = await getShowtimes();
      if (!response.error) {
        setMovieShowtimes(flattenMovieShowtimes(response.result || [], targetMovieId));
      } else {
        toast.error(response.message || "Không thể lấy danh sách suất chiếu của phim");
      }
    } catch (error) {
      toast.error("Không thể lấy danh sách suất chiếu của phim");
    } finally {
      setShowtimesLoading(false);
    }
  };

  useEffect(() => {
    if (visible && movieID) {
      setFetching(true);
      loadMovieShowtimes(movieID);
      getMovieById(movieID).then((res) => {
        if (!res.error) {
          const movie = res.result;
          setOriginPosterUrl(movie.poster);
          setPosterPreview(movie.poster);
          setTrailerUrl(movie.trailer || "");
          form.setFieldsValue({
            ...movie,
            releaseDate: movie.releaseDate ? dayjs(movie.releaseDate) : null,
            // Đảm bảo poster là mảng file object cho Upload
            poster: movie.poster
              ? [
                  {
                    uid: "-1",
                    name: "poster.jpg",
                    status: "done",
                    url: movie.poster,
                  },
                ]
              : [],
          });
        }
        setFetching(false);
      });
    }
  }, [visible, movieID, form]);

  useEffect(() => {
    if (!visible) {
      setMovieShowtimes([]);
      setDeletingShowtimeId(null);
    }
  }, [visible]);

  const normFile = (e) => {
    if (Array.isArray(e)) return e;
    return e?.fileList;
  };

  const onPosterChange = (info) => {
    const file = info.file?.originFileObj;
    if (file) {
      const reader = new FileReader();
      reader.onload = (e) => setPosterPreview(e.target.result);
      reader.readAsDataURL(file);
    } else if (info.file?.url) {
      setPosterPreview(info.file.url);
    } else {
      setPosterPreview(originPosterUrl);
    }
  };

  const getYoutubeEmbedUrl = (url) => {
    if (!url) return "";
    const match = url.match(
      /(?:https?:\/\/)?(?:www\.)?(?:youtube\.com\/watch\?v=|youtu\.be\/)([\w-]{11})/
    );
    return match ? `https://www.youtube.com/embed/${match[1]}` : "";
  };

  const uploadToCloudinary = async (file) => {
    const CLOUDINARY_UPLOAD_PRESET = "phuocnt-cloudinary";
    const CLOUDINARY_CLOUD_NAME = "dl5dphe0f";
    const formData = new FormData();
    formData.append("file", file);
    formData.append("upload_preset", CLOUDINARY_UPLOAD_PRESET);

    const response = await fetch(
      `https://api.cloudinary.com/v1_1/${CLOUDINARY_CLOUD_NAME}/image/upload`,
      {
        method: "POST",
        body: formData,
      }
    );
    const data = await response.json();
    return data.secure_url;
  };

  const onFinish = async (values) => {
    try {
      setLoading(true);
      let newPosterUrl = originPosterUrl;
      const file = values.poster?.[0]?.originFileObj;
      if (file) {
        newPosterUrl = await uploadToCloudinary(file);
      } else if (values.posterUrl) {
        newPosterUrl = values.posterUrl;
      }

      const releaseDate = values.releaseDate
        ? dayjs(values.releaseDate).format("YYYY-MM-DD")
        : "";

      const movieData = {
        title: values.title,
        actors: values.actors,
        director: values.director,
        productionCompany: values.productionCompany,
        runningTime: values.runningTime,
        version: values.version,
        trailer: values.trailer,
        content: values.content,
        genre: Array.isArray(values.genre) ? values.genre.join(",") : values.genre,
        language: Array.isArray(values.language) ? values.language.join(",") : values.language,
        ageRating: values.ageRating,
        releaseDate,
        poster: newPosterUrl,
      };

      const response = await updateMovie(movieID, movieData);
      if (!response.error) {
        toast.success(response.message || "Cập nhật phim thành công!");
        onSuccess && onSuccess();
        onCancel && onCancel();
      } else {
        toast.error(response.message || "Cập nhật phim thất bại");
      }
    } catch (error) {
      toast.error("Cập nhật phim thất bại");
    } finally {
      setLoading(false);
    }
  };

  const handleDeleteShowtime = async (showtimeId) => {
    try {
      setDeletingShowtimeId(showtimeId);
      const response = await deleteShowtime(showtimeId);

      if (!response.error && (response.status === 200 || response.status === 204)) {
        if (response.result?.failures?.length) {
          response.result.failures.forEach((failure) => toast.error(failure));
        } else {
          toast.success("Xóa suất chiếu thành công!");
          await loadMovieShowtimes(movieID);
        }
        return;
      }

      toast.error(response.message || "Xóa suất chiếu thất bại");
    } catch (error) {
      toast.error("Xóa suất chiếu thất bại");
    } finally {
      setDeletingShowtimeId(null);
    }
  };

  const showtimeColumns = [
    {
      title: "Ngày chiếu",
      dataIndex: "date",
      key: "date",
      width: 130,
      render: (value) => (
        <Space size={6}>
          <CalendarOutlined className="text-blue-600" />
          <span>{value ? dayjs(value).format("DD/MM/YYYY") : "-"}</span>
        </Space>
      ),
    },
    {
      title: "Giờ chiếu",
      key: "timeRange",
      width: 150,
      render: (_, record) => (
        <Space size={6}>
          <ClockCircleOutlined className="text-indigo-600" />
          <span>
            {record.time?.slice(0, 5)} - {record.toTime?.slice(0, 5)}
          </span>
        </Space>
      ),
    },
    {
      title: "Rạp / Phòng",
      key: "cinemaRoom",
      render: (_, record) => (
        <div>
          <div className="font-medium text-gray-900">{record.cinemaName}</div>
          <div className="text-xs text-gray-500">{record.cityName} • {record.cinemaRoom}</div>
        </div>
      ),
    },
    {
      title: "Phiên bản",
      dataIndex: "version",
      key: "version",
      width: 110,
      render: (value) => <Tag color="blue">{value || "-"}</Tag>,
    },
    {
      title: "Trạng thái",
      dataIndex: "active",
      key: "active",
      width: 110,
      render: (active) => (
        <Tag color={active ? "green" : "default"}>{active ? "Đang bật" : "Đã tắt"}</Tag>
      ),
    },
    {
      title: "Thao tác",
      key: "actions",
      width: 170,
      render: (_, record) => (
        <Space wrap>
          <EditShowTime
            showtime={record}
            onSuccess={() => loadMovieShowtimes(movieID)}
            buttonProps={{
              children: "Sửa",
            }}
          />
          <Popconfirm
            title="Xóa suất chiếu"
            description="Bạn có chắc muốn xóa suất chiếu này?"
            okText="Xóa"
            cancelText="Hủy"
            okButtonProps={{ danger: true, loading: deletingShowtimeId === record.showtimeId }}
            onConfirm={() => handleDeleteShowtime(record.showtimeId)}
          >
            <Button
              danger
              size="small"
              icon={<DeleteOutlined />}
              loading={deletingShowtimeId === record.showtimeId}
            >
              Xóa
            </Button>
          </Popconfirm>
        </Space>
      ),
    },
  ];

  return (
    <Modal
      open={visible}
      onCancel={onCancel}
      footer={null}
      width={1100}
      title={
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 bg-gradient-to-br from-blue-500 to-indigo-600 rounded-lg flex items-center justify-center shadow-lg">
            <VideoCameraOutlined className="text-white" />
          </div>
          <span className="text-xl font-bold text-gray-900">Cập nhật phim</span>
        </div>
      }
      destroyOnHidden
      style={{ top: 30 }}
      className="!rounded-xl"
    >
      {fetching ? (
        <div style={{ textAlign: "center", padding: 40 }}>
          <Spin size="large" />
        </div>
      ) : (
        <Form
          form={form}
          layout="vertical"
          onFinish={onFinish}
          autoComplete="off"
          className="mt-2"
        >
          <Row gutter={32}>
            {/* Bên trái: Poster & Trailer */}
            <Col xs={24} md={10}>
              <div className="bg-gradient-to-br from-blue-900 to-indigo-700 rounded-xl p-6 shadow-lg flex flex-col items-center min-h-[480px] border border-blue-200">
                <div className="w-full flex flex-col items-center mb-6">
                  <Form.Item
                    name="poster"
                    label={<span className="text-white font-semibold text-lg"> Poster phim (tải từ máy)</span>}
                    valuePropName="fileList"
                    getValueFromEvent={normFile}
                    style={{ marginBottom: 0, width: "100%" }}
                  >
                    <Upload
                      beforeUpload={() => false}
                      maxCount={1}
                      accept="image/*"
                      listType="picture"
                      onChange={onPosterChange}
                      defaultFileList={
                        originPosterUrl
                          ? [
                              {
                                uid: "-1",
                                name: "poster.jpg",
                                status: "done",
                                url: originPosterUrl,
                              },
                            ]
                          : []
                      }
                    >
                      <Button 
                        icon={<UploadOutlined />}
                        className="bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-700 hover:to-indigo-700 text-white border-0 shadow-lg hover:shadow-xl transition-all duration-300"
                      >
                         Chọn ảnh
                      </Button>
                    </Upload>
                  </Form.Item>
                  <Form.Item
                    name="posterUrl"
                    label={<span className="text-white font-semibold text-lg"> Hoặc nhập URL poster</span>}
                    style={{ width: "100%", marginTop: 8 }}
                  >
                    <Input
                      prefix={<PictureOutlined className="text-blue-400" />}
                      placeholder="Dán URL poster tại đây nếu không tải ảnh"
                      onChange={e => setPosterPreview(e.target.value || null)}
                      onBlur={e => setPosterPreview(e.target.value || null)}
                      className="rounded-lg border-gray-300 focus:border-blue-500 focus:ring-2 focus:ring-blue-500"
                    />
                  </Form.Item>
                  {posterPreview && (
                    <div className="w-full flex justify-center mt-2">
                      <img
                        src={posterPreview}
                        alt="Poster Preview"
                        style={{
                          maxWidth: 220,
                          maxHeight: 320,
                          borderRadius: 12,
                          boxShadow: "0 4px 20px rgba(0,0,0,0.3)",
                          background: "#fff",
                          objectFit: "cover",
                          border: "3px solid white"
                        }}
                        onError={e => (e.target.style.display = "none")}
                      />
                    </div>
                  )}
                </div>
                <Divider className="bg-blue-300" />
                <div className="w-full">
                  <Form.Item
                    name="trailer"
                    label={<span className="text-white font-semibold text-lg"> Trailer (URL)</span>}
                    rules={[{ required: true, message: "Vui lòng nhập link trailer" }]}
                    style={{ marginBottom: 8 }}
                  >
                    <Input
                      prefix={<VideoCameraOutlined className="text-blue-400" />}
                      placeholder="Nhập link trailer"
                      value={trailerUrl}
                      onChange={e => setTrailerUrl(e.target.value)}
                      className="rounded-lg border-gray-300 focus:border-blue-500 focus:ring-2 focus:ring-blue-500"
                    />
                  </Form.Item>
                  <div className="w-full h-72 bg-gradient-to-br from-gray-900 to-black rounded-xl flex items-center justify-center mt-2 border border-blue-300 shadow-lg">
                    {getYoutubeEmbedUrl(trailerUrl) ? (
                      <iframe
                        width="100%"
                        height="100%"
                        src={getYoutubeEmbedUrl(trailerUrl)}
                        title="YouTube trailer"
                        allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                        allowFullScreen
                        style={{ border: 0, borderRadius: 8, width: "100%", height: "100%" }}
                      />
                    ) : (
                      <div className="text-center">
                        <VideoCameraOutlined className="text-4xl text-blue-400 mb-2" />
                        <span className="text-white text-sm opacity-80"> Xem trước trailer</span>
                      </div>
                    )}
                  </div>
                </div>
              </div>
            </Col>
            {/* Bên phải: Thông tin phim */}
            <Col xs={24} md={14}>
              <div className="bg-gradient-to-br from-blue-50 to-indigo-50 rounded-xl shadow-lg p-6 border border-blue-200">
                <Form.Item
                  name="title"
                  label={<span className="font-semibold text-gray-900 text-lg"> Tên phim</span>}
                  rules={[{ required: true, message: "Vui lòng nhập tên phim" }]}
                >
                  <Input 
                    placeholder="Nhập tên phim" 
                    className="rounded-lg border-gray-300 focus:border-blue-500 focus:ring-2 focus:ring-blue-500"
                  />
                </Form.Item>
                <Form.Item
                  name="content"
                  label={<span className="font-semibold text-gray-900 text-lg"> Nội dung</span>}
                  rules={[{ required: true, message: "Vui lòng nhập nội dung phim" }]}
                >
                  <TextArea 
                    rows={3} 
                    placeholder="Nhập nội dung phim" 
                    className="rounded-lg border-gray-300 focus:border-blue-500 focus:ring-2 focus:ring-blue-500"
                  />
                </Form.Item>
                <Row gutter={8}>
                  <Col span={12}>
                    <Form.Item
                      name="productionCompany"
                      label={<span className="font-semibold text-gray-900"> Hãng sản xuất</span>}
                      rules={[{ required: true, message: "Vui lòng nhập hãng sản xuất" }]}
                    >
                      <Input 
                        placeholder="Nhập hãng sản xuất" 
                        className="rounded-lg border-gray-300 focus:border-blue-500 focus:ring-2 focus:ring-blue-500"
                      />
                    </Form.Item>
                  </Col>
                  <Col span={12}>
                    <Form.Item
                      name="director"
                      label={<span className="font-semibold text-gray-900"> Đạo diễn</span>}
                      rules={[{ required: true, message: "Vui lòng nhập đạo diễn" }]}
                    >
                      <Input 
                        placeholder="Nhập tên đạo diễn" 
                        className="rounded-lg border-gray-300 focus:border-blue-500 focus:ring-2 focus:ring-blue-500"
                      />
                    </Form.Item>
                  </Col>
                </Row>
                <Form.Item
                  name="actors"
                  label={<span className="font-semibold text-gray-900"> Diễn viên</span>}
                  rules={[{ required: true, message: "Vui lòng nhập diễn viên" }]}
                >
                  <Input 
                    placeholder="Nhập tên diễn viên, cách nhau bởi dấu phẩy" 
                    className="rounded-lg border-gray-300 focus:border-blue-500 focus:ring-2 focus:ring-blue-500"
                  />
                </Form.Item>
                <Row gutter={8}>
                  <Col span={12}>
                    <Form.Item
                      name="genre"
                      label={<span className="font-semibold text-gray-900"> Thể loại</span>}
                      rules={[{ required: true, message: "Vui lòng chọn thể loại" }]}
                    >
                      <Select
                        mode="multiple"
                        placeholder="Chọn thể loại"
                        options={genreOptions}
                        allowClear
                        className="rounded-lg"
                      />
                    </Form.Item>
                  </Col>
                  <Col span={12}>
                    <Form.Item
                      name="language"
                      label={<span className="font-semibold text-gray-900"> Ngôn ngữ</span>}
                      rules={[{ required: true, message: "Vui lòng chọn ngôn ngữ" }]}
                    >
                      <Select
                        mode="multiple"
                        placeholder="Chọn ngôn ngữ"
                        options={languageOptions}
                        allowClear
                        className="rounded-lg"
                      />
                    </Form.Item>
                  </Col>
                </Row>
                <Row gutter={8}>
                  <Col span={12}>
                    <Form.Item
                      name="version"
                      label={<span className="font-semibold text-gray-900"> Phiên bản</span>}
                      rules={[{ required: true, message: "Vui lòng chọn phiên bản" }]}
                    >
                      <Select
                        placeholder="Chọn phiên bản"
                        options={versionOptions}
                        allowClear
                        className="rounded-lg"
                      />
                    </Form.Item>
                  </Col>
                  <Col span={12}>
                    <Form.Item
                      name="ageRating"
                      label={<span className="font-semibold text-gray-900"> Giới hạn tuổi</span>}
                      rules={[{ required: true, message: "Vui lòng chọn giới hạn tuổi" }]}
                    >
                      <Select
                        placeholder="Chọn giới hạn tuổi"
                        options={ageRatingOptions}
                        allowClear
                        className="rounded-lg"
                      />
                    </Form.Item>
                  </Col>
                </Row>
                <Row gutter={8}>
                  <Col span={12}>
                    <Form.Item
                      name="runningTime"
                      label={<span className="font-semibold text-gray-900">⏰ Thời lượng phim</span>}
                      rules={[{ required: true, message: "Vui lòng nhập thời lượng" }]}
                    >
                      <Input
                        type="number"
                        min={1}
                        placeholder="VD: 120 phút"
                        className="rounded-lg border-gray-300 focus:border-blue-500 focus:ring-2 focus:ring-blue-500"
                      />
                    </Form.Item>
                  </Col>
                  <Col span={12}>
                    <Form.Item
                      name="releaseDate"
                      label={<span className="font-semibold text-gray-900"> Ngày ra mắt</span>}
                      rules={[{ required: true, message: "Vui lòng chọn ngày ra mắt" }]}
                    >
                      <DatePicker 
                        className="w-full rounded-lg border-gray-300 focus:border-blue-500 focus:ring-2 focus:ring-blue-500" 
                        format="YYYY-MM-DD" 
                      />
                    </Form.Item>
                  </Col>
                </Row>
              </div>
            </Col>
          </Row>
          <Divider orientation="left" className="!mt-8">
            Suất chiếu hiện có của phim
          </Divider>
          <div className="bg-gradient-to-br from-slate-50 to-blue-50 rounded-xl border border-blue-100 p-4 shadow-sm">
            <div className="flex flex-col gap-1 mb-4">
              <Text strong className="text-base text-gray-900">
                Quản lý suất chiếu trong mục chỉnh sửa phim
              </Text>
              <Text type="secondary">
                Danh sách được sắp xếp từ suất chiếu mới nhất đến cũ nhất.
              </Text>
            </div>

            <Table
              rowKey="showtimeId"
              loading={showtimesLoading}
              columns={showtimeColumns}
              dataSource={movieShowtimes}
              pagination={{ pageSize: 5, hideOnSinglePage: true }}
              locale={{
                emptyText: (
                  <Empty
                    description="Phim này chưa có suất chiếu nào"
                    image={Empty.PRESENTED_IMAGE_SIMPLE}
                  />
                ),
              }}
              scroll={{ x: 900 }}
              size="middle"
            />
          </div>
          <Divider className="my-4" />
          <div className="flex gap-3 justify-end">
            <Button 
              onClick={onCancel} 
              disabled={loading} 
              className="border-gray-300 text-gray-700 hover:border-gray-400 hover:text-gray-800"
            >
              Hủy
            </Button>
            <Button 
              type="primary" 
              htmlType="submit" 
              loading={loading}
              className="bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-700 hover:to-indigo-700 border-0 shadow-lg"
            >
              Cập nhật phim
            </Button>
          </div>
        </Form>
      )}
    </Modal>
  );
};

export default EditMovie;

import React, { useEffect, useState } from "react";
import { Modal, Tooltip, Button, Select } from "antd";
import { getAllSeats, toggleSeatAvailability } from "../../../service/seat";
import AddSeat from "./AddSeat";
import EditSeat from "./EditSeat";
import { HomeOutlined, InboxOutlined, SearchOutlined, CheckCircleOutlined, CloseCircleOutlined, PlusOutlined } from "@ant-design/icons";
import { showSuccessToast, showErrorToast } from "../../../utils/toast";

const normalizeSeatType = (seatType) => String(seatType || "").toLowerCase();
const isVipSeat = (seatType) => normalizeSeatType(seatType).includes("vip");
const isDoubleSeat = (seatType) => normalizeSeatType(seatType).includes("double") || normalizeSeatType(seatType).includes("doi");
const getSeatFillClass = (seatType) => {
  if (isVipSeat(seatType)) return "bg-yellow-200 text-yellow-900 shadow-[0_0_8px_2px_rgba(255,193,7,0.3)]";
  if (isDoubleSeat(seatType)) return "bg-purple-200 text-purple-900 shadow-[0_0_8px_2px_rgba(168,85,247,0.25)]";
  return "bg-gray-200 text-gray-700";
};
const getSeatTypeLabel = (seatType) => {
  if (isVipSeat(seatType)) return "VIP";
  if (isDoubleSeat(seatType)) return "Ghế đôi";
  return seatType || "Thường";
};

const SeatManagement = ({ addModalVisible, setAddModalVisible }) => {
  const [seatData, setSeatData] = useState([]);
  const [flatSeats, setFlatSeats] = useState([]);
  const [cityFilter, setCityFilter] = useState("");
  const [cinemaFilter, setCinemaFilter] = useState("");
  const [roomFilter, setRoomFilter] = useState("");
  const [searchText, setSearchText] = useState("");
  const [pagination, setPagination] = useState({
    current: 1,
    pageSize: 6,
    total: 0,
  });
  const [showAdd, setShowAdd] = useState(false);
  // Use props if provided, otherwise use local state
  const modalVisible = addModalVisible !== undefined ? addModalVisible : showAdd;
  const setModalVisible = setAddModalVisible !== undefined ? setAddModalVisible : setShowAdd;
  const [showEdit, setShowEdit] = useState(false);
  const [selectedSeat, setSelectedSeat] = useState(null);
  const [selectedRoomForAdd, setSelectedRoomForAdd] = useState(null);
  const [allRooms, setAllRooms] = useState([]);

  // Lấy dữ liệu ghế và flatten để dễ render
  const fetchSeats = async ({ page = 1, pageSize = 6, search = searchText, city = cityFilter, cinema = cinemaFilter, room = roomFilter } = {}) => {
    try {
      const res = await getAllSeats();
      if (res.success) {
        setSeatData(res.data);

        // Flatten dữ liệu để dễ filter và render
        const seats = [];
        const rooms = [];
        res.data.forEach(city => {
          city.cinemas.forEach(cinema => {
            cinema.cinemaRooms.forEach(room => {
              rooms.push({
                ...room,
                cityName: city.name,
                cinemaName: cinema.name,
              });
              room.seats.forEach(seat => {
                seats.push({
                  cityID: city.cityID,
                  cityName: city.name,
                  cinemaID: cinema.cinemaID,
                  cinemaName: cinema.name,
                  cinemaRoomID: room.cinemaRoomID,
                  roomName: room.roomName,
                  seatID: seat.seatID,
                  seatName: seat.seatName,
                  seatType: seat.seatType,
                  isAvailable: seat.isAvailable,
                  price: seat.price,
                });
              });
            });
          });
        });
        setFlatSeats(seats);
        setAllRooms(rooms);

        // Filter rooms based on search and filters
        let filteredRooms = rooms;

        if (search) {
          filteredRooms = filteredRooms.filter(room => 
            room.roomName?.toLowerCase().includes(search.toLowerCase()) ||
            room.cityName?.toLowerCase().includes(search.toLowerCase()) ||
            room.cinemaName?.toLowerCase().includes(search.toLowerCase())
          );
        }

        if (city && city !== "") {
          // Filter theo cityName vì cityID trong rooms là undefined
          const selectedCity = seatData.find(c => c.cityID === Number(city));
          if (selectedCity) {
            filteredRooms = filteredRooms.filter(room => room.cityName === selectedCity.name);
          }
        }

        if (cinema && cinema !== "") {
          const selectedCinema = seatData
            .find(city => city.cityID === Number(cityFilter))
            ?.cinemas.find(c => c.cinemaID === Number(cinema));
          if (selectedCinema) {
            filteredRooms = filteredRooms.filter(room => room.cinemaName === selectedCinema.name);
          }
        }

        if (room && room !== "") {
          const selectedRoom = seatData
            .find(city => city.cityID === Number(cityFilter))
            ?.cinemas.find(cinema => cinema.cinemaID === Number(cinemaFilter))
            ?.cinemaRooms.find(r => r.cinemaRoomID === Number(room));
          if (selectedRoom) {
            filteredRooms = filteredRooms.filter(room => room.roomName === selectedRoom.roomName);
          }
        }




        setPagination({
          current: page,
          pageSize: pageSize,
          total: filteredRooms.length,
        });

        const startIdx = (page - 1) * pageSize;
        const endIdx = startIdx + pageSize;
        setFilteredRooms(filteredRooms.slice(startIdx, endIdx));
      } else {
        showErrorToast(res.message || "Không thể lấy danh sách ghế");
        setFlatSeats([]);
        setAllRooms([]);
        setPagination(prev => ({ ...prev, total: 0 }));
      }
    } catch (err) {
      showErrorToast("Mất kết nối server");
      setFlatSeats([]);
      setAllRooms([]);
      setPagination(prev => ({ ...prev, total: 0 }));
    }
  };

  useEffect(() => {
    fetchSeats();
  }, []);

  useEffect(() => {
    fetchSeats({ page: 1, pageSize: pagination.pageSize, search: searchText, city: cityFilter, cinema: cinemaFilter, room: roomFilter });
  }, [searchText, cityFilter, cinemaFilter, roomFilter]);

  // Reset selectedRoomForAdd when modal is closed
  useEffect(() => {
    if (!modalVisible) {
      setSelectedRoomForAdd(null);
    }
  }, [modalVisible]);

  const [filteredRooms, setFilteredRooms] = useState([]);

  // Statistics
  const totalSeats = flatSeats.length;
  const availableSeats = flatSeats.filter(seat => seat.isAvailable).length;
  const unavailableSeats = flatSeats.filter(seat => !seat.isAvailable).length;
  const totalRooms = allRooms.length;

  // Lấy options cho filter
  const cityOptions = seatData.map(city => ({
    value: city.cityID,
    label: city.name,
  }));

  // Alternative: Tạo cityOptions từ allRooms nếu seatData trống
  const cityOptionsFromRooms = allRooms.length > 0 ? 
    [...new Set(allRooms.map(room => ({ value: room.cityID, label: room.cityName })))] : [];

  const finalCityOptions = cityOptions.length > 0 ? cityOptions : cityOptionsFromRooms;



  const cinemaOptions = cityFilter
    ? seatData
        .find(city => city.cityID === Number(cityFilter))
        ?.cinemas.map(cinema => ({
          value: cinema.cinemaID,
          label: cinema.name,
        })) || []
    : [];

  const roomOptions = cinemaFilter
    ? seatData
        .find(city => city.cityID === Number(cityFilter))
        ?.cinemas.find(cinema => cinema.cinemaID === Number(cinemaFilter))
        ?.cinemaRooms.map(room => ({
          value: room.cinemaRoomID,
          label: room.roomName,
        })) || []
    : [];



  // Handle seat toggle
  const handleSeatToggle = async (seat) => {
    try {
      const res = await toggleSeatAvailability([seat.seatID]);
      if (res.success) {
        showSuccessToast(res.message || "Cập nhật trạng thái ghế thành công!");
        fetchSeats({ page: pagination.current, pageSize: pagination.pageSize });
      } else {
        showErrorToast(res.message || "Cập nhật trạng thái ghế thất bại!");
      }
    } catch (err) {
      showErrorToast("Mất kết nối server");
    }
  };

  return (
    <>
      {/* Statistics Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-3 mb-6">
        <div className="bg-gradient-to-br from-blue-50 to-indigo-50 rounded-lg p-3 border-2 border-gray-200 hover:border-blue-300 transition-all duration-300 cursor-pointer hover:shadow-lg hover:scale-[1.02]">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-xs font-medium text-gray-600">Tổng ghế</p>
              <p className="text-lg font-bold text-blue-900">{totalSeats}</p>
            </div>
            <div className="w-8 h-8 bg-gradient-to-br from-blue-500 to-indigo-600 rounded-lg flex items-center justify-center shadow-md">
              <HomeOutlined className="text-white text-sm" />
            </div>
          </div>
        </div>
        <div className="bg-gradient-to-br from-green-50 to-emerald-50 rounded-lg p-3 border-2 border-gray-200 hover:border-green-300 transition-all duration-300 cursor-pointer hover:shadow-lg hover:scale-[1.02]">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-xs font-medium text-gray-600">Đang hoạt động</p>
              <p className="text-lg font-bold text-green-700">{availableSeats}</p>
            </div>
            <div className="w-8 h-8 bg-gradient-to-br from-green-500 to-emerald-600 rounded-lg flex items-center justify-center shadow-md">
              <CheckCircleOutlined className="text-white text-sm" />
            </div>
          </div>
        </div>
        <div className="bg-gradient-to-br from-red-50 to-rose-50 rounded-lg p-3 border-2 border-gray-200 hover:border-red-300 transition-all duration-300 cursor-pointer hover:shadow-lg hover:scale-[1.02]">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-xs font-medium text-gray-600">Đã khóa</p>
              <p className="text-lg font-bold text-red-700">{unavailableSeats}</p>
            </div>
            <div className="w-8 h-8 bg-gradient-to-br from-red-500 to-rose-600 rounded-lg flex items-center justify-center shadow-md">
              <CloseCircleOutlined className="text-white text-sm" />
            </div>
          </div>
        </div>
        <div className="bg-gradient-to-br from-purple-50 to-violet-50 rounded-lg p-3 border-2 border-gray-200 hover:border-purple-300 transition-all duration-300 cursor-pointer hover:shadow-lg hover:scale-[1.02]">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-xs font-medium text-gray-600">Tổng phòng</p>
              <p className="text-lg font-bold text-purple-700">{totalRooms}</p>
            </div>
            <div className="w-8 h-8 bg-gradient-to-br from-purple-500 to-violet-600 rounded-lg flex items-center justify-center shadow-md">
              <HomeOutlined className="text-white text-sm" />
            </div>
          </div>
        </div>
      </div>

      {/* Search and Filter Section */}
      <div className="flex items-center justify-between gap-4 mb-4 p-4 bg-gradient-to-r from-gray-50 to-slate-50 rounded-lg border border-gray-200">
        <div className="flex items-center gap-4">
          <Select
            placeholder="Tất cả thành phố"
            style={{ width: 180 }}
            value={cityFilter || undefined}
            onChange={v => {
              setCityFilter(v);
              setCinemaFilter("");
              setRoomFilter("");
            }}
            options={[
              { value: "", label: "Tất cả thành phố" },
              ...finalCityOptions,
            ]}
            showSearch
            filterOption={(input, option) =>
              (option?.label ?? '').toLowerCase().includes(input.toLowerCase())
            }
            allowClear={false}
          />
          <Select
            placeholder="Tất cả rạp"
            style={{ width: 180 }}
            value={cinemaFilter}
            onChange={v => {
              setCinemaFilter(v);
              setRoomFilter("");
            }}
            options={[
              { value: "", label: "Tất cả rạp" },
              ...cinemaOptions,
            ]}
            allowClear={false}
            disabled={!cityFilter && cinemaOptions.length === 0}
          />
          <Select
            placeholder="Tất cả phòng chiếu"
            style={{ width: 180 }}
            value={roomFilter}
            onChange={setRoomFilter}
            options={[
              { value: "", label: "Tất cả phòng chiếu" },
              ...roomOptions,
            ]}
            allowClear={false}
            disabled={!cinemaFilter && roomOptions.length === 0}
          />
        </div>

        <div className="relative">
          <SearchOutlined className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 z-10" />
          <input
            placeholder="Tìm kiếm ghế..."
            value={searchText}
            onChange={e => setSearchText(e.target.value)}
            className="pl-10 w-64 h-8 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-400 focus:border-blue-400 focus:outline-none text-sm shadow-sm"
            style={{ color: 'black', backgroundColor: 'white' }}
          />
        </div>
      </div>
      {/* Room Cards */}
      {filteredRooms.length === 0 ? (
        <div className="bg-gradient-to-br from-gray-50 to-slate-50 rounded-xl p-12 text-center border border-gray-200">
          <InboxOutlined className="text-6xl text-gray-300 mb-4" />
          <h3 className="text-lg font-medium text-gray-900 mb-2">Không tìm thấy phòng chiếu nào</h3>
          <p className="text-gray-500">Thử thay đổi bộ lọc hoặc thêm ghế mới</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-2 xl:grid-cols-3 gap-6">
          {filteredRooms.map((room) => (
            <div key={room.cinemaRoomID} className="bg-gradient-to-br from-white via-blue-50 to-indigo-100 rounded-xl border-2 transition-all duration-300 hover:shadow-lg hover:scale-[1.02] relative overflow-hidden border-gray-200 hover:border-blue-300">
              {/* Header */}
              <div className="p-4 border-b border-gray-200 flex items-center justify-between bg-gradient-to-r from-blue-100 to-indigo-100">
                <div className="flex items-center gap-2">
                  <HomeOutlined className="text-blue-600" />
                  <span className="font-bold text-blue-700">{room.roomName}</span>
                </div>
                <div className="flex items-center gap-2">
                  <div className="text-xs text-blue-600 font-medium">
                    {room.seats.length} ghế
                  </div>
                  <Tooltip title="Thêm ghế cho phòng này">
                    <Button
                      size="small"
                      type="primary"
                      icon={<PlusOutlined />}
                      onClick={() => {
                        setSelectedRoomForAdd(room);
                        setModalVisible(true);
                      }}
                      className="bg-gradient-to-r from-green-600 to-emerald-600 hover:from-green-700 hover:to-emerald-700 border-0"
                    />
                  </Tooltip>
                </div>
              </div>

              {/* Content */}
              <div className="p-4 bg-gradient-to-br from-white to-blue-50">
                {/* Room Info */}
                <div className="space-y-2 mb-4">
                  <div className="flex justify-between text-xs">
                    <span className="text-gray-500">Rạp:</span>
                    <span className="text-blue-700 font-bold">{room.cinemaName}</span>
                  </div>
                  <div className="flex justify-between text-xs">
                    <span className="text-gray-500">Thành phố:</span>
                    <span className="text-gray-700">{room.cityName}</span>
                  </div>
                </div>

                {/* Seat Legend */}
                <div className="flex gap-3 mb-4 justify-center">
                  <div className="flex items-center gap-1">
                    <div className="w-4 h-4 rounded bg-gray-200 border border-green-400" />
                    <span className="text-xs text-gray-600">Thường</span>
                  </div>
                  <div className="flex items-center gap-1">
                    <div className="w-4 h-4 rounded bg-yellow-200 border border-yellow-500 shadow-[0_0_8px_2px_rgba(255,193,7,0.3)]" />
                    <span className="text-xs text-gray-600">VIP</span>
                  </div>
                  <div className="flex items-center gap-1">
                    <div className="w-4 h-4 rounded bg-purple-200 border border-purple-500 shadow-[0_0_8px_2px_rgba(168,85,247,0.25)]" />
                    <span className="text-xs text-gray-600">Ghế đôi</span>
                  </div>
                  <div className="flex items-center gap-1">
                    <div className="w-4 h-4 rounded bg-gray-200 border border-red-400 opacity-50" />
                    <span className="text-xs text-gray-600">Khóa</span>
                  </div>
                </div>

                {/* Seat Layout */}
                {room.seats.length === 0 ? (
                  <div className="flex flex-col items-center justify-center py-8 text-gray-400">
                    <InboxOutlined className="text-3xl mb-2" />
                    <div className="text-sm font-medium">Không có ghế nào</div>
                  </div>
                ) : (
                  <div className="w-full">
                    {(() => {
                      const rows = Array.from(new Set(room.seats.map(seat => seat.seatName[0]))).sort();
                      const cols = Array.from(new Set(room.seats.map(seat => Number(seat.seatName.slice(1))))).sort((a,b) => a-b);
                      return (
                        <div className="flex flex-col items-center w-full">
                          {/* Screen */}
                          <div className="text-center text-blue-500 font-bold text-sm mb-2">Màn hình</div>
                          <div className="w-full h-1 rounded-full bg-gradient-to-r from-blue-200 to-blue-400 mb-3" />

                          {/* Seats */}
                          <div className="rounded-lg p-3 shadow border border-blue-100 w-full">
                            {rows.map(row => (
                              <div key={row} className="flex gap-1 mb-1 items-center">
                                <span className="w-3 text-gray-400 text-xs">{row}</span>
                                {cols.map(col => {
                                  const seat = room.seats.find(s => s.seatName === `${row}${col}`);
                                  return seat ? (
                                    <div
                                      key={seat.seatID}
                                      className={`w-8 h-8 flex items-center justify-center rounded font-bold border text-xs cursor-pointer transition-all duration-200
                                        ${getSeatFillClass(seat.seatType)}
                                        ${seat.isAvailable ? 'border-green-400 hover:scale-110 hover:shadow-lg hover:border-blue-400' : 'border-red-400 opacity-50'}
                                      `}
                                      title={`${seat.seatName} - ${getSeatTypeLabel(seat.seatType)} - ${seat.price?.toLocaleString()} đ`}
                                      onClick={() => handleSeatToggle(seat)}
                                    >
                                      {seat.seatName}
                                    </div>
                                  ) : (
                                    <div key={col} className="w-8 h-8" />
                                  );
                                })}
                                <span className="w-3 text-gray-400 text-xs">{row}</span>
                              </div>
                            ))}
                            {/* Column numbers */}
                            <div className="flex gap-1 mt-1 ml-4">
                              {cols.map(col => (
                                <span key={col} className="w-8 text-center text-gray-400 text-xs">{col}</span>
                              ))}
                            </div>
                          </div>
                        </div>
                      );
                    })()}
                  </div>
                )}
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Custom Pagination */}
      <div className="flex flex-wrap justify-end items-center gap-2 mt-6">
        <button
          className={`w-9 h-9 rounded-xl font-bold shadow transition flex items-center justify-center
            ${pagination.current === 1
              ? 'bg-gray-200 text-gray-400 cursor-not-allowed'
              : 'bg-white text-blue-700 hover:bg-blue-100'}
          `}
          disabled={pagination.current === 1}
          onClick={() => {
            if (pagination.current > 1) {
              const newPage = pagination.current - 1;
              setPagination(prev => ({ ...prev, current: newPage }));
              fetchSeats({ page: newPage, pageSize: pagination.pageSize });
            }
          }}
        >
          &lt;
        </button>
        {Array.from({ length: Math.ceil(allRooms.length / pagination.pageSize) }, (_, i) => i + 1).map(page => (
          <button
            key={page}
            className={`w-9 h-9 rounded-xl font-bold shadow transition flex items-center justify-center
              ${pagination.current === page
                ? 'bg-gradient-to-br from-blue-500 to-indigo-700 text-white scale-105'
                : 'bg-white text-blue-700 hover:bg-blue-100'}
            `}
            onClick={() => {
              setPagination(prev => ({ ...prev, current: page }));
              fetchSeats({ page: page, pageSize: pagination.pageSize });
            }}
          >
            {page}
          </button>
        ))}
        <button
          className={`w-9 h-9 rounded-xl font-bold shadow transition flex items-center justify-center
            ${pagination.current === Math.ceil(allRooms.length / pagination.pageSize) || allRooms.length === 0
              ? 'bg-gray-200 text-gray-400 cursor-not-allowed'
              : 'bg-white text-blue-700 hover:bg-blue-100'}
          `}
          disabled={pagination.current === Math.ceil(allRooms.length / pagination.pageSize) || allRooms.length === 0}
          onClick={() => {
            if (pagination.current < Math.ceil(allRooms.length / pagination.pageSize)) {
              const newPage = pagination.current + 1;
              setPagination(prev => ({ ...prev, current: newPage }));
              fetchSeats({ page: newPage, pageSize: pagination.pageSize });
            }
          }}
        >
          &gt;
        </button>
        <select
          className="ml-4 rounded-lg border px-2 py-1 focus:outline-none focus:ring-2 focus:ring-blue-400 focus:border-blue-400 transition bg-white text-blue-700 border-blue-200"
          value={pagination.pageSize}
          onChange={e => {
            const newSize = Number(e.target.value);
            setPagination(prev => ({ ...prev, pageSize: newSize, current: 1 }));
            fetchSeats({ page: 1, pageSize: newSize });
          }}
        >
          {[6, 12, 24].map(size => (
            <option key={size} value={size}>{size} / page</option>
          ))}
        </select>
      </div>
      {/* Modals */}
      <Modal
        title="Thêm ghế mới"
        open={modalVisible}
        key={`add-seat-modal-${selectedRoomForAdd?.cinemaRoomID || 'no-room'}`}
        onCancel={() => {
          setModalVisible(false);
          setSelectedRoomForAdd(null); // Reset on cancel
        }}
        onOk={() => {
          // This will never be called since footer={null}, but just in case
          setSelectedRoomForAdd(null);
        }}
        afterClose={() => {
          // Reset when modal is completely closed
          setSelectedRoomForAdd(null);
        }}
        footer={null}
        width={800}
        className="!rounded-xl"
      >
        <AddSeat
          selectedRoom={selectedRoomForAdd}
          onSuccess={() => {
            setModalVisible(false);
            setSelectedRoomForAdd(null); // Reset on success
            fetchSeats({ page: pagination.current, pageSize: pagination.pageSize });
          }}
          onClose={() => {
            setModalVisible(false);
            setSelectedRoomForAdd(null); // Reset on close
          }}
        />
      </Modal>

      <Modal
        title="Chỉnh sửa ghế"
        open={showEdit}
        onCancel={() => {
          setShowEdit(false);
          setSelectedSeat(null);
        }}
        footer={null}
        width={500}
        className="!rounded-xl"
      >
        <EditSeat
          seat={selectedSeat}
          onSuccess={() => {
            setShowEdit(false);
            setSelectedSeat(null);
            fetchSeats({ page: pagination.current, pageSize: pagination.pageSize });
          }}
          onClose={() => {
            setShowEdit(false);
            setSelectedSeat(null);
          }}
        />
      </Modal>
    </>
  );
};

export default SeatManagement;

import React, { useEffect, useState } from "react";
import { Modal, Tooltip, Button, Select } from "antd";
import { getAllSeats, toggleSeatAvailability, getAllSeatTypes, updateSeatTypeBatch } from "../../../service/seat";
import AddSeat from "./AddSeat";
import EditSeat from "./EditSeat";
import { HomeOutlined, InboxOutlined, SearchOutlined, CheckCircleOutlined, CloseCircleOutlined, PlusOutlined } from "@ant-design/icons";
import { showSuccessToast, showErrorToast } from "../../../utils/toast";

const normalizeSeatType = (seatType) =>
  String(seatType || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .trim();
const isVipSeat = (seatType) => normalizeSeatType(seatType).includes("vip");
const isDoubleSeat = (seatType) => {
  const normalized = normalizeSeatType(seatType);
  return normalized.includes("double") || normalized.includes("doi");
};
const getSeatFillClass = (seatType) => {
  if (isVipSeat(seatType)) return "bg-yellow-200 text-yellow-900 shadow-[0_0_8px_2px_rgba(255,193,7,0.3)]";
  if (isDoubleSeat(seatType)) return "bg-purple-200 text-purple-900 shadow-[0_0_8px_2px_rgba(168,85,247,0.25)]";
  return "bg-gray-200 text-gray-700";
};
const getSeatTypeLabel = (seatType) => {
  if (isVipSeat(seatType)) return "VIP";
  if (isDoubleSeat(seatType)) return "Ghế đôi";
  return seatType || "Thường";
};

const SeatManagement = ({ addModalVisible, setAddModalVisible }) => {
  const [seatData, setSeatData] = useState([]);
  const [flatSeats, setFlatSeats] = useState([]);
  const [cityFilter, setCityFilter] = useState("");
  const [cinemaFilter, setCinemaFilter] = useState("");
  const [roomFilter, setRoomFilter] = useState("");
  const [searchText, setSearchText] = useState("");
  const [pagination, setPagination] = useState({
    current: 1,
    pageSize: 6,
    total: 0,
  });
  const [showAdd, setShowAdd] = useState(false);
  // Use props if provided, otherwise use local state
  const modalVisible = addModalVisible !== undefined ? addModalVisible : showAdd;
  const setModalVisible = setAddModalVisible !== undefined ? setAddModalVisible : setShowAdd;
  const [showEdit, setShowEdit] = useState(false);
  const [selectedSeat, setSelectedSeat] = useState(null);
  const [selectedRoomForAdd, setSelectedRoomForAdd] = useState(null);
  const [allRooms, setAllRooms] = useState([]);
  const [seatTypes, setSeatTypes] = useState([]);
  const [showSeatActionModal, setShowSeatActionModal] = useState(false);
  const [selectedSeatsByRoom, setSelectedSeatsByRoom] = useState({});
  const [selectedActionRoom, setSelectedActionRoom] = useState(null);
  const [selectedSeatsForAction, setSelectedSeatsForAction] = useState([]);
  const [selectedSeatTypeId, setSelectedSeatTypeId] = useState("");
  const [selectedSeatPrice, setSelectedSeatPrice] = useState(0);
  const [actionLoading, setActionLoading] = useState(false);

  // Lấy dữ liệu ghế và flatten để dễ render
  const fetchSeats = async ({ page = 1, pageSize = 6, search = searchText, city = cityFilter, cinema = cinemaFilter, room = roomFilter } = {}) => {
    try {
      const res = await getAllSeats();
      if (res.success) {
        setSeatData(res.data);

        // Flatten dữ liệu để dễ filter và render
        const seats = [];
        const rooms = [];
        res.data.forEach(city => {
          city.cinemas.forEach(cinema => {
            cinema.cinemaRooms.forEach(room => {
              rooms.push({
                ...room,
                cityName: city.name,
                cinemaName: cinema.name,
              });
              room.seats.forEach(seat => {
                seats.push({
                  cityID: city.cityID,
                  cityName: city.name,
                  cinemaID: cinema.cinemaID,
                  cinemaName: cinema.name,
                  cinemaRoomID: room.cinemaRoomID,
                  roomName: room.roomName,
                  seatID: seat.seatID,
                  seatName: seat.seatName,
                  seatType: seat.seatType,
                  isAvailable: seat.isAvailable,
                  price: seat.price,
                });
              });
            });
          });
        });
        setFlatSeats(seats);
        setAllRooms(rooms);

        // Filter rooms based on search and filters
        let filteredRooms = rooms;

        if (search) {
          filteredRooms = filteredRooms.filter(room => 
            room.roomName?.toLowerCase().includes(search.toLowerCase()) ||
            room.cityName?.toLowerCase().includes(search.toLowerCase()) ||
            room.cinemaName?.toLowerCase().includes(search.toLowerCase())
          );
        }

        if (city && city !== "") {
          // Filter theo cityName vì cityID trong rooms là undefined
          const selectedCity = seatData.find(c => c.cityID === Number(city));
          if (selectedCity) {
            filteredRooms = filteredRooms.filter(room => room.cityName === selectedCity.name);
          }
        }

        if (cinema && cinema !== "") {
          const selectedCinema = seatData
            .find(city => city.cityID === Number(cityFilter))
            ?.cinemas.find(c => c.cinemaID === Number(cinema));
          if (selectedCinema) {
            filteredRooms = filteredRooms.filter(room => room.cinemaName === selectedCinema.name);
          }
        }

        if (room && room !== "") {
          const selectedRoom = seatData
            .find(city => city.cityID === Number(cityFilter))
            ?.cinemas.find(cinema => cinema.cinemaID === Number(cinemaFilter))
            ?.cinemaRooms.find(r => r.cinemaRoomID === Number(room));
          if (selectedRoom) {
            filteredRooms = filteredRooms.filter(room => room.roomName === selectedRoom.roomName);
          }
        }




        setPagination({
          current: page,
          pageSize: pageSize,
          total: filteredRooms.length,
        });

        const startIdx = (page - 1) * pageSize;
        const endIdx = startIdx + pageSize;
        setFilteredRooms(filteredRooms.slice(startIdx, endIdx));
      } else {
        showErrorToast(res.message || "Không thể lấy danh sách ghế");
        setFlatSeats([]);
        setAllRooms([]);
        setPagination(prev => ({ ...prev, total: 0 }));
      }
    } catch (err) {
      showErrorToast("Mất kết nối server");
      setFlatSeats([]);
      setAllRooms([]);
      setPagination(prev => ({ ...prev, total: 0 }));
    }
  };

  useEffect(() => {
    fetchSeats();
  }, []);

  useEffect(() => {
    const fetchSeatTypes = async () => {
      const res = await getAllSeatTypes();
      if (res.success) {
        setSeatTypes(Array.isArray(res.data) ? res.data : []);
      }
    };
    fetchSeatTypes();
  }, []);

  useEffect(() => {
    fetchSeats({ page: 1, pageSize: pagination.pageSize, search: searchText, city: cityFilter, cinema: cinemaFilter, room: roomFilter });
  }, [searchText, cityFilter, cinemaFilter, roomFilter]);

  // Reset selectedRoomForAdd when modal is closed
  useEffect(() => {
    if (!modalVisible) {
      setSelectedRoomForAdd(null);
    }
  }, [modalVisible]);

  const [filteredRooms, setFilteredRooms] = useState([]);

  // Statistics
  const totalSeats = flatSeats.length;
  const availableSeats = flatSeats.filter(seat => seat.isAvailable).length;
  const unavailableSeats = flatSeats.filter(seat => !seat.isAvailable).length;
  const totalRooms = allRooms.length;

  // Lấy options cho filter
  const cityOptions = seatData.map(city => ({
    value: city.cityID,
    label: city.name,
  }));

  // Alternative: Tạo cityOptions từ allRooms nếu seatData trống
  const cityOptionsFromRooms = allRooms.length > 0 ? 
    [...new Set(allRooms.map(room => ({ value: room.cityID, label: room.cityName })))] : [];

  const finalCityOptions = cityOptions.length > 0 ? cityOptions : cityOptionsFromRooms;



  const cinemaOptions = cityFilter
    ? seatData
        .find(city => city.cityID === Number(cityFilter))
        ?.cinemas.map(cinema => ({
          value: cinema.cinemaID,
          label: cinema.name,
        })) || []
    : [];

  const roomOptions = cinemaFilter
    ? seatData
        .find(city => city.cityID === Number(cityFilter))
        ?.cinemas.find(cinema => cinema.cinemaID === Number(cinemaFilter))
        ?.cinemaRooms.map(room => ({
          value: room.cinemaRoomID,
          label: room.roomName,
        })) || []
    : [];



  // Handle seat toggle
  const handleSeatToggle = async (seat) => {
    try {
      const res = await toggleSeatAvailability([seat.seatID]);
      if (res.success) {
        showSuccessToast(res.message || "Cập nhật trạng thái ghế thành công!");
        fetchSeats({ page: pagination.current, pageSize: pagination.pageSize });
      } else {
        showErrorToast(res.message || "Cập nhật trạng thái ghế thất bại!");
      }
    } catch (err) {
      showErrorToast("Mất kết nối server");
    }
  };

  const resolveSeatTypeId = (seatTypeLabel) => {
    if (!seatTypeLabel) return "";
    const found = seatTypes.find(
      (type) =>
        type.code?.toLowerCase() === String(seatTypeLabel).toLowerCase() ||
        type.name?.toLowerCase() === String(seatTypeLabel).toLowerCase()
    );
    return found?.seatTypeID || "";
  };

  const getRoomSelection = (roomId) => selectedSeatsByRoom[String(roomId)] || [];

  const extractSeatPosition = (seatName) => {
    const match = String(seatName || "").trim().match(/^([A-Za-z]+)(\d+)$/);
    if (!match) return null;
    return { row: match[1].toUpperCase(), col: Number(match[2]) };
  };

  const isDoubleTargetType = (seatTypeId) => {
    const chosen = seatTypes.find((type) => type.seatTypeID === Number(seatTypeId));
    if (!chosen) return false;
    return isDoubleSeat(chosen.code) || isDoubleSeat(chosen.name);
  };

  const validateHorizontalAdjacentIgnoringGap = (selectedSeats) => {
    if (selectedSeats.length !== 2) return false;

    const first = extractSeatPosition(selectedSeats[0].seatName);
    const second = extractSeatPosition(selectedSeats[1].seatName);
    return !!first && !!second && first.row === second.row && Math.abs(first.col - second.col) === 1;
  };

  const toggleSeatSelection = (seat, room) => {
    const roomKey = String(room.cinemaRoomID);
    setSelectedSeatsByRoom((prev) => {
      const current = prev[roomKey] || [];
      const exists = current.some((item) => item.seatID === seat.seatID);
      const next = exists
        ? current.filter((item) => item.seatID !== seat.seatID)
        : [
            ...current,
            {
              ...seat,
              roomName: room.roomName,
              cinemaRoomID: room.cinemaRoomID,
            },
          ];
      return { ...prev, [roomKey]: next };
    });
  };

  const openSeatAction = (room) => {
    const selectedSeats = getRoomSelection(room.cinemaRoomID);
    if (selectedSeats.length === 0) {
      showErrorToast("Vui lòng chọn ít nhất 1 ghế để chỉnh sửa");
      return;
    }

    const firstSeat = selectedSeats[0];
    setSelectedActionRoom(room);
    setSelectedSeatsForAction(selectedSeats);
    setSelectedSeatTypeId(resolveSeatTypeId(firstSeat.seatType));
    setSelectedSeatPrice(firstSeat.price || 0);
    setShowSeatActionModal(true);
  };

  const handleSaveSeatType = async () => {
    if (!selectedActionRoom || selectedSeatsForAction.length === 0) return;
    if (!selectedSeatTypeId) {
      showErrorToast("Vui lòng chọn loại ghế");
      return;
    }
    if (Number(selectedSeatPrice) < 0) {
      showErrorToast("Giá ghế không hợp lệ");
      return;
    }

    setActionLoading(true);
    try {
      const chosenType = seatTypes.find((t) => t.seatTypeID === Number(selectedSeatTypeId));

      if (isDoubleTargetType(selectedSeatTypeId)) {
        if (selectedSeatsForAction.length !== 2) {
          showErrorToast("Khi đổi sang ghế đôi, bạn phải chọn đúng 2 ghế");
          return;
        }
        if (!validateHorizontalAdjacentIgnoringGap(selectedSeatsForAction)) {
          showErrorToast("2 ghế đôi phải cùng hàng và có số ghế liền kề (ví dụ C1 + C2)");
          return;
        }
      }

      const res = await updateSeatTypeBatch({
        cinemaRoomId: Number(selectedActionRoom.cinemaRoomID),
        seatIds: selectedSeatsForAction.map((seat) => seat.seatID),
        seatTypeId: Number(selectedSeatTypeId),
        seatType: chosenType?.code || chosenType?.name,
        price: Number(selectedSeatPrice),
      });

      if (!res.success) {
        showErrorToast(res.message || "Cập nhật loại ghế thất bại");
        return;
      }

      showSuccessToast(`Đã cập nhật loại ghế thành công cho ${selectedSeatsForAction.length} ghế`);
      setShowSeatActionModal(false);
      setSelectedSeatsByRoom((prev) => ({
        ...prev,
        [String(selectedActionRoom.cinemaRoomID)]: [],
      }));
      setSelectedSeatsForAction([]);
      setSelectedActionRoom(null);
      fetchSeats({ page: pagination.current, pageSize: pagination.pageSize });
    } finally {
      setActionLoading(false);
    }
  };

  return (
    <>
      {/* Statistics Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-3 mb-6">
        <div className="bg-gradient-to-br from-blue-50 to-indigo-50 rounded-lg p-3 border-2 border-gray-200 hover:border-blue-300 transition-all duration-300 cursor-pointer hover:shadow-lg hover:scale-[1.02]">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-xs font-medium text-gray-600">Tổng ghế</p>
              <p className="text-lg font-bold text-blue-900">{totalSeats}</p>
            </div>
            <div className="w-8 h-8 bg-gradient-to-br from-blue-500 to-indigo-600 rounded-lg flex items-center justify-center shadow-md">
              <HomeOutlined className="text-white text-sm" />
            </div>
          </div>
        </div>
        <div className="bg-gradient-to-br from-green-50 to-emerald-50 rounded-lg p-3 border-2 border-gray-200 hover:border-green-300 transition-all duration-300 cursor-pointer hover:shadow-lg hover:scale-[1.02]">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-xs font-medium text-gray-600">Đang hoạt động</p>
              <p className="text-lg font-bold text-green-700">{availableSeats}</p>
            </div>
            <div className="w-8 h-8 bg-gradient-to-br from-green-500 to-emerald-600 rounded-lg flex items-center justify-center shadow-md">
              <CheckCircleOutlined className="text-white text-sm" />
            </div>
          </div>
        </div>
        <div className="bg-gradient-to-br from-red-50 to-rose-50 rounded-lg p-3 border-2 border-gray-200 hover:border-red-300 transition-all duration-300 cursor-pointer hover:shadow-lg hover:scale-[1.02]">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-xs font-medium text-gray-600">Đã khóa</p>
              <p className="text-lg font-bold text-red-700">{unavailableSeats}</p>
            </div>
            <div className="w-8 h-8 bg-gradient-to-br from-red-500 to-rose-600 rounded-lg flex items-center justify-center shadow-md">
              <CloseCircleOutlined className="text-white text-sm" />
            </div>
          </div>
        </div>
        <div className="bg-gradient-to-br from-purple-50 to-violet-50 rounded-lg p-3 border-2 border-gray-200 hover:border-purple-300 transition-all duration-300 cursor-pointer hover:shadow-lg hover:scale-[1.02]">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-xs font-medium text-gray-600">Tổng phòng</p>
              <p className="text-lg font-bold text-purple-700">{totalRooms}</p>
            </div>
            <div className="w-8 h-8 bg-gradient-to-br from-purple-500 to-violet-600 rounded-lg flex items-center justify-center shadow-md">
              <HomeOutlined className="text-white text-sm" />
            </div>
          </div>
        </div>
      </div>

      {/* Search and Filter Section */}
      <div className="flex items-center justify-between gap-4 mb-4 p-4 bg-gradient-to-r from-gray-50 to-slate-50 rounded-lg border border-gray-200">
        <div className="flex items-center gap-4">
          <Select
            placeholder="Tất cả thành phố"
            style={{ width: 180 }}
            value={cityFilter || undefined}
            onChange={v => {
              setCityFilter(v);
              setCinemaFilter("");
              setRoomFilter("");
            }}
            options={[
              { value: "", label: "Tất cả thành phố" },
              ...finalCityOptions,
            ]}
            showSearch
            filterOption={(input, option) =>
              (option?.label ?? '').toLowerCase().includes(input.toLowerCase())
            }
            allowClear={false}
          />
          <Select
            placeholder="Tất cả rạp"
            style={{ width: 180 }}
            value={cinemaFilter}
            onChange={v => {
              setCinemaFilter(v);
              setRoomFilter("");
            }}
            options={[
              { value: "", label: "Tất cả rạp" },
              ...cinemaOptions,
            ]}
            allowClear={false}
            disabled={!cityFilter && cinemaOptions.length === 0}
          />
          <Select
            placeholder="Tất cả phòng chiếu"
            style={{ width: 180 }}
            value={roomFilter}
            onChange={setRoomFilter}
            options={[
              { value: "", label: "Tất cả phòng chiếu" },
              ...roomOptions,
            ]}
            allowClear={false}
            disabled={!cinemaFilter && roomOptions.length === 0}
          />
        </div>

        <div className="relative">
          <SearchOutlined className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 z-10" />
          <input
            placeholder="Tìm kiếm ghế..."
            value={searchText}
            onChange={e => setSearchText(e.target.value)}
            className="pl-10 w-64 h-8 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-400 focus:border-blue-400 focus:outline-none text-sm shadow-sm"
            style={{ color: 'black', backgroundColor: 'white' }}
          />
        </div>
      </div>
      {/* Room Cards */}
      {filteredRooms.length === 0 ? (
        <div className="bg-gradient-to-br from-gray-50 to-slate-50 rounded-xl p-12 text-center border border-gray-200">
          <InboxOutlined className="text-6xl text-gray-300 mb-4" />
          <h3 className="text-lg font-medium text-gray-900 mb-2">Không tìm thấy phòng chiếu nào</h3>
          <p className="text-gray-500">Thử thay đổi bộ lọc hoặc thêm ghế mới</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-2 xl:grid-cols-3 gap-6">
          {filteredRooms.map((room) => (
            <div key={room.cinemaRoomID} className="bg-gradient-to-br from-white via-blue-50 to-indigo-100 rounded-xl border-2 transition-all duration-300 hover:shadow-lg hover:scale-[1.02] relative overflow-hidden border-gray-200 hover:border-blue-300">
              {/* Header */}
              <div className="p-4 border-b border-gray-200 flex items-center justify-between bg-gradient-to-r from-blue-100 to-indigo-100">
                <div className="flex items-center gap-2">
                  <HomeOutlined className="text-blue-600" />
                  <span className="font-bold text-blue-700">{room.roomName}</span>
                </div>
                <div className="flex items-center gap-2">
                  <div className="text-xs text-blue-600 font-medium">
                    {room.seats.length} ghế
                  </div>
                  <Tooltip title="Cập nhật ghế đã chọn">
                    <Button
                      size="small"
                      onClick={() => openSeatAction(room)}
                      disabled={getRoomSelection(room.cinemaRoomID).length === 0}
                    >
                      Sửa ({getRoomSelection(room.cinemaRoomID).length})
                    </Button>
                  </Tooltip>
                  <Tooltip title="Thêm ghế cho phòng này">
                    <Button
                      size="small"
                      type="primary"
                      icon={<PlusOutlined />}
                      onClick={() => {
                        setSelectedRoomForAdd(room);
                        setModalVisible(true);
                      }}
                      className="bg-gradient-to-r from-green-600 to-emerald-600 hover:from-green-700 hover:to-emerald-700 border-0"
                    />
                  </Tooltip>
                </div>
              </div>

              {/* Content */}
              <div className="p-4 bg-gradient-to-br from-white to-blue-50">
                {/* Room Info */}
                <div className="space-y-2 mb-4">
                  <div className="flex justify-between text-xs">
                    <span className="text-gray-500">Rạp:</span>
                    <span className="text-blue-700 font-bold">{room.cinemaName}</span>
                  </div>
                  <div className="flex justify-between text-xs">
                    <span className="text-gray-500">Thành phố:</span>
                    <span className="text-gray-700">{room.cityName}</span>
                  </div>
                </div>

                {/* Seat Legend */}
                <div className="flex gap-3 mb-4 justify-center">
                  <div className="flex items-center gap-1">
                    <div className="w-4 h-4 rounded bg-gray-200 border border-green-400" />
                    <span className="text-xs text-gray-600">Thường</span>
                  </div>
                  <div className="flex items-center gap-1">
                    <div className="w-4 h-4 rounded bg-yellow-200 border border-yellow-500 shadow-[0_0_8px_2px_rgba(255,193,7,0.3)]" />
                    <span className="text-xs text-gray-600">VIP</span>
                  </div>
                  <div className="flex items-center gap-1">
                    <div className="w-4 h-4 rounded bg-purple-200 border border-purple-500 shadow-[0_0_8px_2px_rgba(168,85,247,0.25)]" />
                    <span className="text-xs text-gray-600">Ghế đôi</span>
                  </div>
                  <div className="flex items-center gap-1">
                    <div className="w-4 h-4 rounded bg-gray-200 border border-red-400 opacity-50" />
                    <span className="text-xs text-gray-600">Khóa</span>
                  </div>
                </div>

                {/* Seat Layout */}
                {room.seats.length === 0 ? (
                  <div className="flex flex-col items-center justify-center py-8 text-gray-400">
                    <InboxOutlined className="text-3xl mb-2" />
                    <div className="text-sm font-medium">Không có ghế nào</div>
                  </div>
                ) : (
                  <div className="w-full">
                    {(() => {
                      const rows = Array.from(new Set(room.seats.map(seat => seat.seatName[0]))).sort();
                      const cols = Array.from(new Set(room.seats.map(seat => Number(seat.seatName.slice(1))))).sort((a,b) => a-b);
                      return (
                        <div className="flex flex-col items-center w-full">
                          {/* Screen */}
                          <div className="text-center text-blue-500 font-bold text-sm mb-2">Màn hình</div>
                          <div className="w-full h-1 rounded-full bg-gradient-to-r from-blue-200 to-blue-400 mb-3" />

                          {/* Seats */}
                          <div className="rounded-lg p-3 shadow border border-blue-100 w-full">
                            {rows.map(row => (
                              <div key={row} className="flex gap-1 mb-1 items-center">
                                <span className="w-3 text-gray-400 text-xs">{row}</span>
                                {cols.map(col => {
                                  const seat = room.seats.find(s => s.seatName === `${row}${col}`);
                                  return seat ? (
                                    <div
                                      key={seat.seatID}
                                      className={`w-8 h-8 flex items-center justify-center rounded font-bold border text-xs cursor-pointer transition-all duration-200
                                        ${getSeatFillClass(seat.seatType)}
                                        ${getRoomSelection(room.cinemaRoomID).some((item) => item.seatID === seat.seatID) ? 'ring-2 ring-blue-500 scale-105' : ''}
                                        ${seat.isAvailable ? 'border-green-400 hover:scale-110 hover:shadow-lg hover:border-blue-400' : 'border-red-400 opacity-50'}
                                      `}
                                      title={`${seat.seatName} - ${getSeatTypeLabel(seat.seatType)} - ${seat.price?.toLocaleString()} đ`}
                                      onClick={() => toggleSeatSelection(seat, room)}
                                    >
                                      {seat.seatName}
                                    </div>
                                  ) : (
                                    <div key={col} className="w-8 h-8" />
                                  );
                                })}
                                <span className="w-3 text-gray-400 text-xs">{row}</span>
                              </div>
                            ))}
                            {/* Column numbers */}
                            <div className="flex gap-1 mt-1 ml-4">
                              {cols.map(col => (
                                <span key={col} className="w-8 text-center text-gray-400 text-xs">{col}</span>
                              ))}
                            </div>
                          </div>
                        </div>
                      );
                    })()}
                  </div>
                )}
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Custom Pagination */}
      <div className="flex flex-wrap justify-end items-center gap-2 mt-6">
        <button
          className={`w-9 h-9 rounded-xl font-bold shadow transition flex items-center justify-center
            ${pagination.current === 1
              ? 'bg-gray-200 text-gray-400 cursor-not-allowed'
              : 'bg-white text-blue-700 hover:bg-blue-100'}
          `}
          disabled={pagination.current === 1}
          onClick={() => {
            if (pagination.current > 1) {
              const newPage = pagination.current - 1;
              setPagination(prev => ({ ...prev, current: newPage }));
              fetchSeats({ page: newPage, pageSize: pagination.pageSize });
            }
          }}
        >
          &lt;
        </button>
        {Array.from({ length: Math.ceil(allRooms.length / pagination.pageSize) }, (_, i) => i + 1).map(page => (
          <button
            key={page}
            className={`w-9 h-9 rounded-xl font-bold shadow transition flex items-center justify-center
              ${pagination.current === page
                ? 'bg-gradient-to-br from-blue-500 to-indigo-700 text-white scale-105'
                : 'bg-white text-blue-700 hover:bg-blue-100'}
            `}
            onClick={() => {
              setPagination(prev => ({ ...prev, current: page }));
              fetchSeats({ page: page, pageSize: pagination.pageSize });
            }}
          >
            {page}
          </button>
        ))}
        <button
          className={`w-9 h-9 rounded-xl font-bold shadow transition flex items-center justify-center
            ${pagination.current === Math.ceil(allRooms.length / pagination.pageSize) || allRooms.length === 0
              ? 'bg-gray-200 text-gray-400 cursor-not-allowed'
              : 'bg-white text-blue-700 hover:bg-blue-100'}
          `}
          disabled={pagination.current === Math.ceil(allRooms.length / pagination.pageSize) || allRooms.length === 0}
          onClick={() => {
            if (pagination.current < Math.ceil(allRooms.length / pagination.pageSize)) {
              const newPage = pagination.current + 1;
              setPagination(prev => ({ ...prev, current: newPage }));
              fetchSeats({ page: newPage, pageSize: pagination.pageSize });
            }
          }}
        >
          &gt;
        </button>
        <select
          className="ml-4 rounded-lg border px-2 py-1 focus:outline-none focus:ring-2 focus:ring-blue-400 focus:border-blue-400 transition bg-white text-blue-700 border-blue-200"
          value={pagination.pageSize}
          onChange={e => {
            const newSize = Number(e.target.value);
            setPagination(prev => ({ ...prev, pageSize: newSize, current: 1 }));
            fetchSeats({ page: 1, pageSize: newSize });
          }}
        >
          {[6, 12, 24].map(size => (
            <option key={size} value={size}>{size} / page</option>
          ))}
        </select>
      </div>
      {/* Modals */}
      <Modal
        title="Thêm ghế mới"
        open={modalVisible}
        key={`add-seat-modal-${selectedRoomForAdd?.cinemaRoomID || 'no-room'}`}
        onCancel={() => {
          setModalVisible(false);
          setSelectedRoomForAdd(null); // Reset on cancel
        }}
        onOk={() => {
          // This will never be called since footer={null}, but just in case
          setSelectedRoomForAdd(null);
        }}
        afterClose={() => {
          // Reset when modal is completely closed
          setSelectedRoomForAdd(null);
        }}
        footer={null}
        width={800}
        className="!rounded-xl"
      >
        <AddSeat
          selectedRoom={selectedRoomForAdd}
          onSuccess={() => {
            setModalVisible(false);
            setSelectedRoomForAdd(null); // Reset on success
            fetchSeats({ page: pagination.current, pageSize: pagination.pageSize });
          }}
          onClose={() => {
            setModalVisible(false);
            setSelectedRoomForAdd(null); // Reset on close
          }}
        />
      </Modal>

      <Modal
        title="Chỉnh sửa ghế"
        open={showEdit}
        onCancel={() => {
          setShowEdit(false);
          setSelectedSeat(null);
        }}
        footer={null}
        width={500}
        className="!rounded-xl"
      >
        <EditSeat
          seat={selectedSeat}
          onSuccess={() => {
            setShowEdit(false);
            setSelectedSeat(null);
            fetchSeats({ page: pagination.current, pageSize: pagination.pageSize });
          }}
          onClose={() => {
            setShowEdit(false);
            setSelectedSeat(null);
          }}
        />
      </Modal>

      <Modal
        title="Điều chỉnh ghế trong phòng"
        open={showSeatActionModal}
        onCancel={() => {
          setShowSeatActionModal(false);
          setSelectedSeatsForAction([]);
          setSelectedActionRoom(null);
        }}
        footer={null}
        width={520}
      >
        {selectedActionRoom && selectedSeatsForAction.length > 0 && (
          <div className="space-y-4">
            <div className="p-3 rounded-lg border bg-gray-50">
              <div className="text-sm text-gray-600">Phòng: <span className="font-semibold text-gray-900">{selectedActionRoom.roomName}</span></div>
              <div className="text-sm text-gray-600">Số ghế đã chọn: <span className="font-semibold text-gray-900">{selectedSeatsForAction.length}</span></div>
              <div className="text-sm text-gray-600">Danh sách ghế: <span className="font-semibold text-gray-900">{selectedSeatsForAction.map((seat) => seat.seatName).join(", ")}</span></div>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Loại ghế mới</label>
              <Select
                className="w-full"
                value={selectedSeatTypeId || undefined}
                placeholder="Chọn loại ghế"
                onChange={(value) => {
                  setSelectedSeatTypeId(value);
                  const nextType = seatTypes.find((type) => type.seatTypeID === Number(value));
                  if (nextType?.basePrice != null) {
                    setSelectedSeatPrice(nextType.basePrice);
                  }
                }}
                options={seatTypes.map((type) => ({
                  value: type.seatTypeID,
                  label: `${type.name} (${Number(type.basePrice || 0).toLocaleString("vi-VN")}đ)`,
                }))}
              />
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Giá ghế</label>
              <input
                type="number"
                min={0}
                className="w-full border border-gray-300 rounded-lg px-3 py-2"
                value={selectedSeatPrice}
                onChange={(e) => setSelectedSeatPrice(e.target.value)}
              />
            </div>

            <div className="grid grid-cols-2 gap-2">
              <Button
                disabled={selectedSeatsForAction.length !== 1}
                onClick={async () => {
                  if (selectedSeatsForAction.length !== 1) return;
                  await handleSeatToggle(selectedSeatsForAction[0]);
                  setShowSeatActionModal(false);
                  setSelectedSeatsForAction([]);
                  setSelectedActionRoom(null);
                }}
              >
                {selectedSeatsForAction.length === 1 && selectedSeatsForAction[0].isAvailable ? "Khóa ghế" : "Mở ghế"}
              </Button>
              <Button type="primary" loading={actionLoading} onClick={handleSaveSeatType}>
                Lưu loại ghế
              </Button>
            </div>
          </div>
        )}
      </Modal>
    </>
  );
};

export default SeatManagement;

import React, { useEffect, useState } from "react";
import { EditOutlined, HomeOutlined, VideoCameraOutlined } from "@ant-design/icons";
import { Modal, Button, Form, Select, DatePicker, TimePicker, message, Row, Col, Input } from "antd";
import { updateShowtime, fetchAllRooms } from "../../../service/showtime";
import dayjs from "dayjs";
import { useLocation } from "react-router-dom";

const { Option } = Select;

const EditShowTime = ({ showtime, onSuccess }) => {
  const [visible, setVisible] = useState(false);
  const [form] = Form.useForm();
  const [loading, setLoading] = useState(false);

  const [allRooms, setAllRooms] = useState([]);
  const [cities, setCities] = useState([]);
  const [cinemas, setCinemas] = useState([]);
  const [cinemaRooms, setCinemaRooms] = useState([]);

  const location = useLocation();
  const params = new URLSearchParams(location.search);
  const movieIdFromUrl = params.get("movieId");
  // Ưu tiên lấy movieId từ showtime, nếu không có thì lấy từ URL
  let movieIdToUse = showtime.movieId;
  if (!movieIdToUse || movieIdToUse === 0) {
    movieIdToUse = movieIdFromUrl ? Number(movieIdFromUrl) : undefined;
  }

  useEffect(() => {
    const loadRooms = async () => {
      const res = await fetchAllRooms();
      if (!res.error) {
        setAllRooms(res.result);
        setCities(res.result.map(city => ({ id: city.cityID, name: city.name, cinemas: city.cinemas })));
      }
    };
    loadRooms();
  }, []);

  const openModal = () => {
    setVisible(true);
    // Tìm city, cinema, room theo showtime.cinemaRoomId
    let cityID, cinemaID, cinemaRoomID = showtime.cinemaRoomId;
    let cityObj, cinemaObj, roomObj;
    allRooms.forEach(city => {
      city.cinemas.forEach(cinema => {
        cinema.cinemaRooms.forEach(room => {
          if (room.cinemaRoomID === cinemaRoomID) {
            cityID = city.cityID;
            cinemaID = cinema.cinemaID;
            cityObj = city;
            cinemaObj = cinema;
            roomObj = room;
          }
        });
      });
    });
    setCinemas(cityObj ? cityObj.cinemas : []);
    setCinemaRooms(cinemaObj ? cinemaObj.cinemaRooms : []);
    form.setFieldsValue({
      showtimeId: showtime.showtimeId,
      movieId: movieIdToUse || "", // luôn set vào form, tránh undefined
      cityID: cityID,
      cinemaID: cinemaID,
      cinemaRoomId: cinemaRoomID,
      date: showtime.date ? dayjs(showtime.date) : null,
      time: showtime.time ? dayjs(showtime.time, "HH:mm") : null,
      version: showtime.version,
    });
  };

  const handleCityChange = (cityID) => {
    const city = allRooms.find(c => c.cityID === cityID);
    setCinemas(city ? city.cinemas : []);
    setCinemaRooms([]);
    form.setFieldsValue({ cinemaID: undefined, cinemaRoomId: undefined });
  };

  const handleCinemaChange = (cinemaID) => {
    const cinema = cinemas.find(c => c.cinemaID === cinemaID);
    setCinemaRooms(cinema ? cinema.cinemaRooms : []);
    form.setFieldsValue({ cinemaRoomId: undefined });
  };

  const handleOk = async () => {
    try {
      setLoading(true);
      const values = await form.validateFields();
      const payload = {
        showtimeId: values.showtimeId,
        movieId: values.movieId, // lấy trực tiếp từ form
        cinemaRoomId: values.cinemaRoomId,
        date: values.date ? values.date.format("YYYY-MM-DD") : "",
        time: values.time ? values.time.format("HH:mm") : "",
        version: values.version,
      };
      const res = await updateShowtime(payload);
      if (!res.error) {
        message.success("Cập nhật suất chiếu thành công!");
        setVisible(false);
        onSuccess && onSuccess();
      } else {
        message.error(res.message);
      }
    } catch (err) {
      // validation error
    } finally {
      setLoading(false);
    }
  };

  return (
    <>
      <Button
        icon={<EditOutlined />}
        onClick={openModal}
        type="primary"
        size="small"
        style={{ marginRight: 8 }}
      />
      <Modal
        title={
          <span className="text-2xl font-bold text-blue-700 flex items-center gap-2">
            <VideoCameraOutlined /> Chỉnh sửa suất chiếu
          </span>
        }
        open={visible}
        onOk={handleOk}
        onCancel={() => setVisible(false)}
        confirmLoading={loading}
        okText="Lưu"
        cancelText="Hủy"
        width={600}
        styles={{ body: { padding: 24 } }}
      >
        <Form form={form} layout="vertical">
          <Form.Item name="showtimeId" label="ID suất chiếu" hidden>
            <Input />
          </Form.Item>
          <Row gutter={16}>
            <Col span={12}>
              <Form.Item name="movieId" label={<span><VideoCameraOutlined /> ID phim</span>} rules={[{ required: true, message: "Bắt buộc" }]}>
                <Input disabled />
              </Form.Item>
            </Col>
            <Col span={12}>
              <Form.Item name="version" label={<span><HomeOutlined /> Phiên bản</span>} rules={[{ required: true, message: "Bắt buộc" }]}>
                <Select placeholder="Chọn phiên bản">
                  <Option value="2D">2D</Option>
                  <Option value="3D">3D</Option>
                  <Option value="IMAX">IMAX</Option>
                  <Option value="4DX">4DX</Option>
                </Select>
              </Form.Item>
            </Col>
          </Row>
          <Row gutter={16}>
            <Col span={8}>
              <Form.Item
                name="cityID"
                label="Thành phố"
                rules={[{ required: true, message: "Vui lòng chọn thành phố" }]}
              >
                <Select placeholder="Chọn thành phố" onChange={handleCityChange}>
                  {cities.map(city => (
                    <Option key={city.id} value={city.id}>{city.name}</Option>
                  ))}
                </Select>
              </Form.Item>
            </Col>
            <Col span={8}>
              <Form.Item
                name="cinemaID"
                label="Rạp"
                rules={[{ required: true, message: "Vui lòng chọn rạp" }]}
              >
                <Select placeholder="Chọn rạp" onChange={handleCinemaChange} disabled={!cinemas.length}>
                  {cinemas.map(cinema => (
                    <Option key={cinema.cinemaID} value={cinema.cinemaID}>{cinema.name}</Option>
                  ))}
                </Select>
              </Form.Item>
            </Col>
            <Col span={8}>
              <Form.Item
                name="cinemaRoomId"
                label="Phòng chiếu"
                rules={[{ required: true, message: "Vui lòng chọn phòng chiếu" }]}
              >
                <Select placeholder="Chọn phòng chiếu" disabled={!cinemaRooms.length}>
                  {cinemaRooms.map(room => (
                    <Option key={room.cinemaRoomID} value={room.cinemaRoomID}>{room.roomName}</Option>
                  ))}
                </Select>
              </Form.Item>
            </Col>
          </Row>
          <Row gutter={16}>
            <Col span={12}>
              <Form.Item name="date" label="Ngày chiếu" rules={[{ required: true, message: "Bắt buộc" }]}>
                <DatePicker format="YYYY-MM-DD" style={{ width: "100%" }} />
              </Form.Item>
            </Col>
            <Col span={12}>
              <Form.Item name="time" label="Giờ chiếu" rules={[{ required: true, message: "Bắt buộc" }]}>
                <TimePicker format="HH:mm" style={{ width: "100%" }} />
              </Form.Item>
            </Col>
          </Row>
        </Form>
      </Modal>
    </>
  );
};

export default EditShowTime;

import React, { useEffect, useState } from "react";
import { EditOutlined, HomeOutlined, VideoCameraOutlined } from "@ant-design/icons";
import { Modal, Button, Form, Select, DatePicker, TimePicker, message, Row, Col, Input } from "antd";
import { updateShowtime, fetchAllRooms } from "../../../service/showtime";
import dayjs from "dayjs";

const { Option } = Select;

const EditShowTime = ({
  showtime,
  onSuccess,
  visible: controlledVisible,
  onCancel,
  hideTrigger = false,
  buttonProps = {},
}) => {
  const [internalVisible, setInternalVisible] = useState(false);
  const [form] = Form.useForm();
  const [loading, setLoading] = useState(false);

  const [allRooms, setAllRooms] = useState([]);
  const [cities, setCities] = useState([]);
  const [cinemas, setCinemas] = useState([]);
  const [cinemaRooms, setCinemaRooms] = useState([]);

  const isControlled = typeof controlledVisible === "boolean";
  const visible = isControlled ? controlledVisible : internalVisible;

  const closeModal = () => {
    if (!isControlled) {
      setInternalVisible(false);
    }
    onCancel?.();
  };

  useEffect(() => {
    const loadRooms = async () => {
      const res = await fetchAllRooms();
      if (!res.error) {
        setAllRooms(res.result);
        setCities(res.result.map(city => ({ id: city.cityID, name: city.name, cinemas: city.cinemas })));
      }
    };
    loadRooms();
  }, []);

  useEffect(() => {
    if (!visible || !showtime || allRooms.length === 0) return;

    const movieIdToUse = showtime.movieId ? Number(showtime.movieId) : undefined;
    let cityID, cinemaID, cinemaRoomID = showtime.cinemaRoomId;
    let cityObj, cinemaObj;
    allRooms.forEach(city => {
      city.cinemas.forEach(cinema => {
        cinema.cinemaRooms.forEach(room => {
          if (room.cinemaRoomID === cinemaRoomID) {
            cityID = city.cityID;
            cinemaID = cinema.cinemaID;
            cityObj = city;
            cinemaObj = cinema;
          }
        });
      });
    });
    setCinemas(cityObj ? cityObj.cinemas : []);
    setCinemaRooms(cinemaObj ? cinemaObj.cinemaRooms : []);
    form.setFieldsValue({
      showtimeId: showtime.showtimeId || showtime.id,
      movieId: movieIdToUse || "", // luôn set vào form, tránh undefined
      cityID: cityID,
      cinemaID: cinemaID,
      cinemaRoomId: cinemaRoomID,
      date: showtime.date ? dayjs(showtime.date) : null,
      time: showtime.time ? dayjs(showtime.time?.slice(0, 5), "HH:mm") : null,
      version: showtime.version,
    });
  }, [visible, showtime, allRooms, form]);

  const openModal = () => {
    if (!isControlled) {
      setInternalVisible(true);
    }
  };

  const handleCityChange = (cityID) => {
    const city = allRooms.find(c => c.cityID === cityID);
    setCinemas(city ? city.cinemas : []);
    setCinemaRooms([]);
    form.setFieldsValue({ cinemaID: undefined, cinemaRoomId: undefined });
  };

  const handleCinemaChange = (cinemaID) => {
    const cinema = cinemas.find(c => c.cinemaID === cinemaID);
    setCinemaRooms(cinema ? cinema.cinemaRooms : []);
    form.setFieldsValue({ cinemaRoomId: undefined });
  };

  const handleOk = async () => {
    try {
      setLoading(true);
      const values = await form.validateFields();
      const payload = {
        showtimeId: values.showtimeId,
        movieId: values.movieId, // lấy trực tiếp từ form
        cinemaRoomId: values.cinemaRoomId,
        date: values.date ? values.date.format("YYYY-MM-DD") : "",
        time: values.time ? values.time.format("HH:mm") : "",
        version: values.version,
      };
      const res = await updateShowtime(payload);
      if (!res.error) {
        message.success("Cập nhật suất chiếu thành công!");
        closeModal();
        onSuccess && onSuccess();
      } else {
        message.error(res.message);
      }
    } catch (err) {
      // validation error
    } finally {
      setLoading(false);
    }
  };

  return (
    <>
      {!hideTrigger && (
        <Button
          icon={<EditOutlined />}
          onClick={openModal}
          type="primary"
          size="small"
          style={{ marginRight: 8 }}
          {...buttonProps}
        />
      )}
      <Modal
        title={
          <span className="text-2xl font-bold text-blue-700 flex items-center gap-2">
            <VideoCameraOutlined /> Chỉnh sửa suất chiếu
          </span>
        }
        open={visible}
        onOk={handleOk}
        onCancel={closeModal}
        confirmLoading={loading}
        okText="Lưu"
        cancelText="Hủy"
        width={600}
        styles={{ body: { padding: 24 } }}
      >
        <Form form={form} layout="vertical">
          <Form.Item name="showtimeId" label="ID suất chiếu" hidden>
            <Input />
          </Form.Item>
          <Row gutter={16}>
            <Col span={12}>
              <Form.Item name="movieId" label={<span><VideoCameraOutlined /> ID phim</span>} rules={[{ required: true, message: "Bắt buộc" }]}>
                <Input disabled />
              </Form.Item>
            </Col>
            <Col span={12}>
              <Form.Item name="version" label={<span><HomeOutlined /> Phiên bản</span>} rules={[{ required: true, message: "Bắt buộc" }]}>
                <Select placeholder="Chọn phiên bản">
                  <Option value="2D">2D</Option>
                  <Option value="3D">3D</Option>
                  <Option value="IMAX">IMAX</Option>
                  <Option value="4DX">4DX</Option>
                </Select>
              </Form.Item>
            </Col>
          </Row>
          <Row gutter={16}>
            <Col span={8}>
              <Form.Item
                name="cityID"
                label="Thành phố"
                rules={[{ required: true, message: "Vui lòng chọn thành phố" }]}
              >
                <Select placeholder="Chọn thành phố" onChange={handleCityChange}>
                  {cities.map(city => (
                    <Option key={city.id} value={city.id}>{city.name}</Option>
                  ))}
                </Select>
              </Form.Item>
            </Col>
            <Col span={8}>
              <Form.Item
                name="cinemaID"
                label="Rạp"
                rules={[{ required: true, message: "Vui lòng chọn rạp" }]}
              >
                <Select placeholder="Chọn rạp" onChange={handleCinemaChange} disabled={!cinemas.length}>
                  {cinemas.map(cinema => (
                    <Option key={cinema.cinemaID} value={cinema.cinemaID}>{cinema.name}</Option>
                  ))}
                </Select>
              </Form.Item>
            </Col>
            <Col span={8}>
              <Form.Item
                name="cinemaRoomId"
                label="Phòng chiếu"
                rules={[{ required: true, message: "Vui lòng chọn phòng chiếu" }]}
              >
                <Select placeholder="Chọn phòng chiếu" disabled={!cinemaRooms.length}>
                  {cinemaRooms.map(room => (
                    <Option key={room.cinemaRoomID} value={room.cinemaRoomID}>{room.roomName}</Option>
                  ))}
                </Select>
              </Form.Item>
            </Col>
          </Row>
          <Row gutter={16}>
            <Col span={12}>
              <Form.Item name="date" label="Ngày chiếu" rules={[{ required: true, message: "Bắt buộc" }]}>
                <DatePicker format="YYYY-MM-DD" style={{ width: "100%" }} />
              </Form.Item>
            </Col>
            <Col span={12}>
              <Form.Item name="time" label="Giờ chiếu" rules={[{ required: true, message: "Bắt buộc" }]}>
                <TimePicker format="HH:mm" style={{ width: "100%" }} />
              </Form.Item>
            </Col>
          </Row>
        </Form>
      </Modal>
    </>
  );
};

export default EditShowTime;

import React, { useState } from "react";
import { Button } from "antd";
import { 
  HomeOutlined, 
  UserOutlined, 
  CalendarOutlined, 
  PlayCircleOutlined, 
  PlusOutlined 
} from "@ant-design/icons";
import CinemaRoomManagement from "../CinemaRoom/CinemaRoomManagement";
import SeatManagement from "../Seat/SeatManagement";
import CalendarManagement from "../Calendar/CalendarManagement";
import ShowTimeManagement from "../ShowTime/ShowTimeManagement";

const TheaterManagement = () => {
  const [activeTab, setActiveTab] = useState("cinemaroom");

  // Modal states for each component
  const [cinemaRoomModalVisible, setCinemaRoomModalVisible] = useState(false);
  const [seatModalVisible, setSeatModalVisible] = useState(false);
  const [calendarModalVisible, setCalendarModalVisible] = useState(false);
  const [showTimeModalVisible, setShowTimeModalVisible] = useState(false);

  const tabs = [
    {
      key: "cinemaroom",
      label: "Quản lý phòng chiếu",
      icon: <HomeOutlined className="text-xl text-white" />,
      component: <CinemaRoomManagement addModalVisible={cinemaRoomModalVisible} setAddModalVisible={setCinemaRoomModalVisible} />,
      header: {
        title: "Quản lý phòng chiếu",
        subtitle: "Quản lý các phòng chiếu phim",
        bgColor: "from-blue-500 to-indigo-600",
        headerBg: "bg-blue-50",
        borderColor: "border-blue-200",
        buttonColor: "from-blue-600 to-indigo-600 hover:from-blue-700 hover:to-indigo-700",
        activeRingColor: "ring-blue-500",
        activeBorderColor: "border-blue-400"
      }
    },
    {
      key: "seat",
      label: "Quản lý ghế",
      icon: <UserOutlined className="text-xl text-white" />,
      component: <SeatManagement addModalVisible={seatModalVisible} setAddModalVisible={setSeatModalVisible} />,
      header: {
        title: "Quản lý ghế",
        subtitle: "Quản lý ghế ngồi trong phòng chiếu",
        bgColor: "from-green-500 to-emerald-600",
        headerBg: "bg-green-50",
        borderColor: "border-green-200",
        buttonColor: "from-green-600 to-emerald-600 hover:from-green-700 hover:to-emerald-700",
        activeRingColor: "ring-green-500",
        activeBorderColor: "border-green-400"
      }
    },
    {
      key: "calendar",
      label: "Quản lý lịch chiếu",
      icon: <CalendarOutlined className="text-xl text-white" />,
      component: <CalendarManagement addModalVisible={calendarModalVisible} setAddModalVisible={setCalendarModalVisible} />,
      header: {
        title: "Quản lý lịch chiếu",
        subtitle: "Quản lý lịch chiếu phim theo ngày",
        bgColor: "from-purple-500 to-violet-600",
        headerBg: "bg-purple-50",
        borderColor: "border-purple-200",
        buttonColor: "from-purple-600 to-violet-600 hover:from-purple-700 hover:to-violet-700",
        activeRingColor: "ring-purple-500",
        activeBorderColor: "border-purple-400"
      }
    },
    {
      key: "showtime",
      label: "Quản lý suất chiếu",
      icon: <PlayCircleOutlined className="text-xl text-white" />,
      component: <ShowTimeManagement />,
      header: {
        title: "Quản lý suất chiếu",
        subtitle: "Quản lý các suất chiếu phim",
        bgColor: "from-orange-500 to-red-600",
        headerBg: "bg-orange-50",
        borderColor: "border-orange-200",
        buttonColor: "from-orange-600 to-red-600 hover:from-orange-700 hover:to-red-700",
        activeRingColor: "ring-orange-500",
        activeBorderColor: "border-orange-400"
      }
    }
  ];

  const currentTab = tabs.find(tab => tab.key === activeTab);

  // Function to handle add button clicks
  const handleAddClick = (e, tabKey) => {
    e.stopPropagation();

    // Switch to the tab first, then open modal
    setActiveTab(tabKey);

    // Small delay to ensure tab switch completes
    setTimeout(() => {
      switch (tabKey) {
        case "cinemaroom":
          setCinemaRoomModalVisible(true);
          break;
        case "seat":
          setSeatModalVisible(true);
          break;
        case "calendar":
          setCalendarModalVisible(true);
          break;
        case "showtime":
          setShowTimeModalVisible(true);
          break;
        default:
          break;
      }
    }, 100);
  };

  return (
    <div>
      {/* Header Selection Bar */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-6">
        {tabs.map((tab) => (
          <div
            key={tab.key}
            onClick={() => setActiveTab(tab.key)}
            className={`${tab.header.headerBg} rounded-lg shadow-md border ${tab.header.borderColor} p-4 cursor-pointer transition-all duration-300 hover:shadow-lg relative ${
              activeTab === tab.key
                ? `ring-2 ${tab.header.activeRingColor} ring-opacity-50 ${tab.header.activeBorderColor} transform scale-105 z-10`
                : 'hover:scale-105 hover:z-10'
            }`}
          >
            <div className="flex items-center justify-between gap-4">
              <div className="flex items-center gap-3">
                <div className={`w-10 h-10 bg-gradient-to-br ${tab.header.bgColor} rounded-lg flex items-center justify-center shadow-md`}>
                  {tab.icon}
                </div>
                <div>
                  <h1 className="text-sm font-bold text-gray-900 line-clamp-1">{tab.header.title}</h1>
                  <p className="text-xs text-gray-600 line-clamp-1">{tab.header.subtitle}</p>
                </div>
              </div>
              {/* Ẩn nút + ở tab Quản lý suất chiếu */}
              {tab.key !== "showtime" && (
                <div className="flex-shrink-0">
                  <Button
                    type="primary"
                    icon={<PlusOutlined />}
                    size="small"
                    onClick={(e) => handleAddClick(e, tab.key)}
                    className={`bg-gradient-to-r ${tab.header.buttonColor} border-0 shadow-md hover:shadow-lg transition-all duration-300`}
                  />
                </div>
              )}
            </div>
          </div>
        ))}
      </div>

      {/* Content Area */}
      <div>
        {currentTab?.component}
      </div>
    </div>
  );
};

export default TheaterManagement;

import React, { useState } from "react";
import { Button } from "antd";
import { 
  HomeOutlined, 
  ShopOutlined,
  UserOutlined, 
  CalendarOutlined, 
  PlayCircleOutlined, 
  PlusOutlined 
} from "@ant-design/icons";
import CinemaManagement from "../Cinema/CinemaManagement";
import CinemaRoomManagement from "../CinemaRoom/CinemaRoomManagement";
import SeatManagement from "../Seat/SeatManagement";
import CalendarManagement from "../Calendar/CalendarManagement";
import ShowTimeManagement from "../ShowTime/ShowTimeManagement";

const TheaterManagement = () => {
  const [activeTab, setActiveTab] = useState("cinema");

  // Modal states for each component
  const [cinemaModalVisible, setCinemaModalVisible] = useState(false);
  const [cinemaRoomModalVisible, setCinemaRoomModalVisible] = useState(false);
  const [seatModalVisible, setSeatModalVisible] = useState(false);
  const [calendarModalVisible, setCalendarModalVisible] = useState(false);
  const [showTimeModalVisible, setShowTimeModalVisible] = useState(false);

  const tabs = [
    {
      key: "cinema",
      label: "Quan ly rap phim",
      icon: <ShopOutlined className="text-xl text-white" />,
      component: <CinemaManagement addModalVisible={cinemaModalVisible} setAddModalVisible={setCinemaModalVisible} />,
      header: {
        title: "Quan ly rap phim",
        subtitle: "Quan ly danh sach rap phim",
        bgColor: "from-cyan-500 to-blue-600",
        headerBg: "bg-cyan-50",
        borderColor: "border-cyan-200",
        buttonColor: "from-cyan-600 to-blue-600 hover:from-cyan-700 hover:to-blue-700",
        activeRingColor: "ring-cyan-500",
        activeBorderColor: "border-cyan-400"
      }
    },
    {
      key: "cinemaroom",
      label: "Quản lý phòng chiếu",
      icon: <HomeOutlined className="text-xl text-white" />,
      component: <CinemaRoomManagement addModalVisible={cinemaRoomModalVisible} setAddModalVisible={setCinemaRoomModalVisible} />,
      header: {
        title: "Quản lý phòng chiếu",
        subtitle: "Quản lý các phòng chiếu phim",
        bgColor: "from-blue-500 to-indigo-600",
        headerBg: "bg-blue-50",
        borderColor: "border-blue-200",
        buttonColor: "from-blue-600 to-indigo-600 hover:from-blue-700 hover:to-indigo-700",
        activeRingColor: "ring-blue-500",
        activeBorderColor: "border-blue-400"
      }
    },
    {
      key: "seat",
      label: "Quản lý ghế",
      icon: <UserOutlined className="text-xl text-white" />,
      component: <SeatManagement addModalVisible={seatModalVisible} setAddModalVisible={setSeatModalVisible} />,
      header: {
        title: "Quản lý ghế",
        subtitle: "Quản lý ghế ngồi trong phòng chiếu",
        bgColor: "from-green-500 to-emerald-600",
        headerBg: "bg-green-50",
        borderColor: "border-green-200",
        buttonColor: "from-green-600 to-emerald-600 hover:from-green-700 hover:to-emerald-700",
        activeRingColor: "ring-green-500",
        activeBorderColor: "border-green-400"
      }
    },
    {
      key: "calendar",
      label: "Quản lý lịch chiếu",
      icon: <CalendarOutlined className="text-xl text-white" />,
      component: <CalendarManagement addModalVisible={calendarModalVisible} setAddModalVisible={setCalendarModalVisible} />,
      header: {
        title: "Quản lý lịch chiếu",
        subtitle: "Quản lý lịch chiếu phim theo ngày",
        bgColor: "from-purple-500 to-violet-600",
        headerBg: "bg-purple-50",
        borderColor: "border-purple-200",
        buttonColor: "from-purple-600 to-violet-600 hover:from-purple-700 hover:to-violet-700",
        activeRingColor: "ring-purple-500",
        activeBorderColor: "border-purple-400"
      }
    },
    {
      key: "showtime",
      label: "Quản lý suất chiếu",
      icon: <PlayCircleOutlined className="text-xl text-white" />,
      component: <ShowTimeManagement />,
      header: {
        title: "Quản lý suất chiếu",
        subtitle: "Quản lý các suất chiếu phim",
        bgColor: "from-orange-500 to-red-600",
        headerBg: "bg-orange-50",
        borderColor: "border-orange-200",
        buttonColor: "from-orange-600 to-red-600 hover:from-orange-700 hover:to-red-700",
        activeRingColor: "ring-orange-500",
        activeBorderColor: "border-orange-400"
      }
    }
  ];

  const currentTab = tabs.find(tab => tab.key === activeTab);

  // Function to handle add button clicks
  const handleAddClick = (e, tabKey) => {
    e.stopPropagation();

    // Switch to the tab first, then open modal
    setActiveTab(tabKey);

    // Small delay to ensure tab switch completes
    setTimeout(() => {
      switch (tabKey) {
        case "cinema":
          setCinemaModalVisible(true);
          break;
        case "cinemaroom":
          setCinemaRoomModalVisible(true);
          break;
        case "seat":
          setSeatModalVisible(true);
          break;
        case "calendar":
          setCalendarModalVisible(true);
          break;
        case "showtime":
          setShowTimeModalVisible(true);
          break;
        default:
          break;
      }
    }, 100);
  };

  return (
    <div>
      {/* Header Selection Bar */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-6 mb-6">
        {tabs.map((tab) => (
          <div
            key={tab.key}
            onClick={() => setActiveTab(tab.key)}
            className={`${tab.header.headerBg} rounded-lg shadow-md border ${tab.header.borderColor} p-4 cursor-pointer transition-all duration-300 hover:shadow-lg relative ${
              activeTab === tab.key
                ? `ring-2 ${tab.header.activeRingColor} ring-opacity-50 ${tab.header.activeBorderColor} transform scale-105 z-10`
                : 'hover:scale-105 hover:z-10'
            }`}
          >
            <div className="flex items-center justify-between gap-4">
              <div className="flex items-center gap-3">
                <div className={`w-10 h-10 bg-gradient-to-br ${tab.header.bgColor} rounded-lg flex items-center justify-center shadow-md`}>
                  {tab.icon}
                </div>
                <div>
                  <h1 className="text-sm font-bold text-gray-900 line-clamp-1">{tab.header.title}</h1>
                  <p className="text-xs text-gray-600 line-clamp-1">{tab.header.subtitle}</p>
                </div>
              </div>
              {/* Ẩn nút + ở tab Quản lý suất chiếu */}
              {tab.key !== "showtime" && (
                <div className="flex-shrink-0">
                  <Button
                    type="primary"
                    icon={<PlusOutlined />}
                    size="small"
                    onClick={(e) => handleAddClick(e, tab.key)}
                    className={`bg-gradient-to-r ${tab.header.buttonColor} border-0 shadow-md hover:shadow-lg transition-all duration-300`}
                  />
                </div>
              )}
            </div>
          </div>
        ))}
      </div>

      {/* Content Area */}
      <div>
        {currentTab?.component}
      </div>
    </div>
  );
};

export default TheaterManagement;

import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom"; // Thêm dòng này
import { getShowtimesByMovie } from "../../../service/bookmovieticket";
import BookSeat from "./BookSeat";
import ConfirmBooking from "./ConfirmBooking";
import { FiLogIn } from "react-icons/fi";
import { MdEventBusy } from "react-icons/md";
import Snackbar from "./Snackbar"; // Import Snackbar

const BookMovieTicket = ({ movieId, movieTitle, poster, quickBooking, bookingInfo, setBookingInfo, onShowtimeChange, selectedFoods, setSelectedFoods }) => {
  const [showtimes, setShowtimes] = useState([]);
  const [cities, setCities] = useState([]);
  const [cinemas, setCinemas] = useState([]);
  const [rooms, setRooms] = useState([]);
  const [dates, setDates] = useState([]);
  const [times, setTimes] = useState([]);
  const [selected, setSelected] = useState({
    city: "",
    cinema: "",
    room: "",
    date: "",
    time: "",
    showtime: null,
  });
  const [availableSeats, setAvailableSeats] = useState([]);
  const [selectedSeats, setSelectedSeats] = useState([]);
  const [step, setStep] = useState(1);
  const [confirmInfo, setConfirmInfo] = useState(null);
  const [successInfo, setSuccessInfo] = useState(null);
  const [loading, setLoading] = useState(false);
  const [apiMessage, setApiMessage] = useState("");
  const [error, setError] = useState("");
  const [showRoomDropdown, setShowRoomDropdown] = useState(true);
  const [selectedDate, setSelectedDate] = useState(""); // Thêm state này
  const navigate = useNavigate(); // Thêm dòng này

  // Lấy dữ liệu suất chiếu và flatten
  useEffect(() => {
    const fetchShowtimes = async () => {
      setLoading(true);
      try {
        const res = await getShowtimesByMovie(movieId);
        const result = res.data.result;
        let flatShowtimes = [];
        if (result && result.dates) {
          result.dates.forEach(dateObj => {
            const showDate = dateObj.date;
            dateObj.cities.forEach(city => {
              const cityName = city.name;
              city.cinemas.forEach(cinema => {
                const cinemaName = cinema.name;
                cinema.cinemaRooms.forEach(room => {
                  const cinemaRoomName = room.roomName;
                  const cinemaRoomId = room.cinemaRoomID || room.cinemaRoomId;
                  // Lọc chỉ times active
                  room.times
                    .filter(time => time.active)
                    .forEach(time => {
                      flatShowtimes.push({
                        cityName,
                        cinemaName,
                        cinemaRoomName,
                        cinemaRoomId,
                        showDate,
                        showTime: time.time,
                        seats: time.seats,
                      });
                    });
                });
              });
            });
          });
        }
        setShowtimes(flatShowtimes);
        setCities([...new Set(flatShowtimes.map((s) => s.cityName))]);
      } catch {
        setError("Đăng nhập để đặt vé.");
      }
      setLoading(false);
    };
    fetchShowtimes();
  }, [movieId]);

  // Dropdown logic
  useEffect(() => {
    if (!selected.city) {
      setCinemas([]);
      setSelected(prev => ({ ...prev, cinema: "", date: "", time: "", room: "", showtime: null }));
      return;
    }
    const filtered = showtimes.filter(s => s.cityName === selected.city);
    setCinemas([...new Set(filtered.map(s => s.cinemaName))]);
    // Không reset cinema nếu đã chọn
  }, [selected.city, showtimes]);

  // Khi chọn rạp, chỉ reset ngày, giờ, phòng, showtime
  useEffect(() => {
    if (!selected.cinema) {
      setDates([]);
      setSelected(prev => ({ ...prev, date: "", time: "", room: "", showtime: null }));
      return;
    }
    const filtered = showtimes.filter(
      s => s.cityName === selected.city && s.cinemaName === selected.cinema
    );
    setDates([...new Set(filtered.map(s => s.showDate))]);
    // Không reset cinema ở đây nữa
  }, [selected.cinema, selected.city, showtimes]);

  // Khi chọn ngày, chỉ reset giờ, phòng, showtime
  useEffect(() => {
    if (!selected.date) {
      setTimes([]);
      setSelected(prev => ({ ...prev, time: "", room: "", showtime: null }));
      return;
    }
    const filtered = showtimes.filter(
      s =>
        s.cityName === selected.city &&
        s.cinemaName === selected.cinema &&
        s.showDate === selected.date
    );
    setTimes([...new Set(filtered.map(s => s.showTime))]);
    // Không reset date ở đây nữa
  }, [selected.date, selected.cinema, selected.city, showtimes]);

  // Khi chọn giờ, chỉ reset phòng, showtime
  useEffect(() => {
    if (!selected.time) {
      setShowRoomDropdown(true);
      setRooms([]);
      setSelected(prev => ({ ...prev, room: "", showtime: null }));
      return;
    }
    const filtered = showtimes.filter(
      s =>
        s.cityName === selected.city &&
        s.cinemaName === selected.cinema &&
        s.showDate === selected.date &&
        s.showTime === selected.time
    );
    const uniqueRooms = [...new Set(filtered.map(s => s.cinemaRoomName))];
    setRooms(uniqueRooms);

    if (uniqueRooms.length === 1) {
      setShowRoomDropdown(false);
      setSelected(prev => ({
        ...prev,
        room: uniqueRooms[0],
        showtime: filtered.find(s => s.cinemaRoomName === uniqueRooms[0]),
      }));
      setAvailableSeats(filtered[0]?.seats || []);
      setSelectedSeats([]);
    } else {
      setShowRoomDropdown(true);
      setSelected(prev => ({ ...prev, room: "", showtime: null }));
      setAvailableSeats([]);
      setSelectedSeats([]);
    }
  }, [selected.time, selected.date, selected.cinema, selected.city, showtimes]);

  useEffect(() => {
    if (!showRoomDropdown || !selected.room) return;
    const showtime = showtimes.find(
      s =>
        s.cityName === selected.city &&
        s.cinemaName === selected.cinema &&
        s.showDate === selected.date &&
        s.showTime === selected.time &&
        s.cinemaRoomName === selected.room
    );
    setSelected(prev => ({ ...prev, showtime }));
    setAvailableSeats(showtime ? showtime.seats : []);
    setSelectedSeats([]);
  }, [selected.room, showRoomDropdown, selected.city, selected.cinema, selected.date, selected.time, showtimes]);

  // Chọn ghế
  const handleSelectSeat = seat => {
    if (seat.status === "sold" || seat.isAvailable === false) return;
    setSelectedSeats(prev =>
      prev.some(s => s.seatID === seat.seatID)
        ? prev.filter(s => s.seatID !== seat.seatID)
        : [...prev, seat]
    );
    setError("");
  };

  // Khi có quickBooking, tự động set các dropdown
  useEffect(() => {
    if (
      quickBooking &&
      quickBooking.city &&
      quickBooking.cinema &&
      quickBooking.date &&
      quickBooking.time
    ) {
      setSelected(prev => ({
        ...prev,
        city: quickBooking.city,
        cinema: quickBooking.cinema,
        date: quickBooking.date,
        time: quickBooking.time,
      }));
      setSelectedDate(quickBooking.date); // Nếu bạn dùng selectedDate cho UI ngày

      // Nếu có showtime từ quickBooking, sử dụng nó
      if (quickBooking.showtime) {
        setSelected(prev => ({
          ...prev,
          showtime: quickBooking.showtime,
          room: quickBooking.showtime.cinemaRoomName,
        }));
        setAvailableSeats(quickBooking.showtime.seats || []);
        setSelectedSeats([]);
      }
    }
  }, [quickBooking, showtimes]);

  // Cập nhật thông tin booking khi chọn thành phố, rạp, ngày, giờ
  useEffect(() => {
    setBookingInfo(prev => ({
      ...prev,
      movieTitle,
      cityName: selected.city,
      cinemaName: selected.cinema,
      date: selected.date,
      time: selected.time,
    }));
  }, [selected.city, selected.cinema, selected.date, selected.time, movieTitle, setBookingInfo]);

  // Cập nhật khi chọn ghế
  useEffect(() => {
    const totalPrice = selectedSeats.reduce((sum, seat) => sum + (seat.price || 75000), 0);
    setBookingInfo(prev => ({
      ...prev,
      selectedSeats,
      totalPrice,
    }));
  }, [selectedSeats, setBookingInfo]);

  // Đồng bộ selectedFoods vào bookingInfo
  useEffect(() => {
    setBookingInfo(prev => ({
      ...prev,
      selectedFoods,
    }));
  }, [selectedFoods, setBookingInfo]);

  // Cập nhật khi showtime thay đổi
  useEffect(() => {
    if (onShowtimeChange && selected.showtime) {
      onShowtimeChange(selected.showtime);
    }
  }, [selected.showtime, onShowtimeChange]);

  // UI
  if (loading) return <div className="text-center py-4 text-orange-500 font-semibold">Đang tải...</div>;

  if (error === "Đăng nhập để đặt vé.") {
    return (
      <div className="flex items-center justify-center gap-2 text-orange-500 font-extrabold text-xl text-center drop-shadow-lg animate-pulse">
        <FiLogIn size={38} />
        <span className="drop-shadow">ĐĂNG NHẬP ĐỂ ĐẶT VÉ</span>
      </div>
    );
  }
  if (error === "Vui lòng đăng nhập để đặt vé!") {
    return (
      <div className="flex items-center justify-center gap-2 text-orange-500 font-extrabold text-xl text-center drop-shadow-lg animate-pulse">
        <FiLogIn size={38} />
        <span className="drop-shadow">VUI LÒNG ĐĂNG NHẬP ĐỂ ĐẶT VÉ!</span>
      </div>
    );
  } else if (error) {
    return <div className="text-orange-500 text-center mt-2 font-semibold">{error}</div>;
  }

  // THÊM ĐOẠN NÀY để xử lý trường hợp không có suất chiếu
  if (step === 1 && showtimes.length === 0) {
    return (
      <div className="flex items-center justify-center gap-2 text-orange-500 font-extrabold text-xl text-center drop-shadow-lg animate-pulse">
        <MdEventBusy size={38} />
        <span className="drop-shadow">HIỆN CHƯA CÓ LỊCH CHIẾU</span>
      </div>
    );
  }

  if (step === 1)
    return (
      <div className="flex justify-center items-center bg-transparent py-6" style={{ fontSize: "80%" }}>
        <div className="w-full">
          <h2 className="font-bold text-2xl mb-3 text-orange-500 text-center tracking-wide drop-shadow-lg uppercase">LỊCH CHIẾU</h2>
          {/* Thành phố */}
          <div className="mb-4 flex justify-center items-center gap-2">
            <select
              className="px-3 py-1.5 rounded-lg border border-orange-400 focus:border-orange-600 focus:outline-none min-w-[110px] text-gray-900 font-bold bg-white shadow transition text-sm"
              value={selected.city}
              onChange={e => {
                setSelected(prev => ({ ...prev, city: e.target.value, cinema: "", date: "", time: "", room: "", showtime: null }));
                setSelectedDate("");
              }}
            >
              <option value="">-- Chọn thành phố --</option>
              {cities.map(city => (
                <option key={city} className="text-sm">{city}</option>
              ))}
            </select>
          </div>

          {/* Chọn ngày */}
          {selected.city && (() => {
            const showtimesOfCity = showtimes.filter(s => s.cityName === selected.city);
            const allDates = [...new Set(showtimesOfCity.map(s => s.showDate))];
            if (allDates.length === 0) return null;
            return (
              <div className="mb-4 flex gap-2 justify-center">
                {allDates.map(date => (
                  <button
                    key={date}
                    className={`px-4 py-1.5 rounded-lg font-bold border shadow transition-all duration-200 text-sm
                      ${selectedDate === date
                        ? "bg-gradient-to-r from-orange-400 to-orange-500 text-white border-orange-600 scale-105"
                        : "bg-white text-orange-700 border-orange-400 hover:bg-orange-50 hover:scale-105"}`}
                    onClick={() => {
                      setSelectedDate(date);
                      setSelected(prev => ({ ...prev, date, cinema: "", time: "", room: "", showtime: null }));
                    }}
                  >
                    {date}
                  </button>
                ))}
              </div>
            );
          })()}

          {/* Danh sách rạp, giờ */}
          {selected.city && selectedDate && (
            <div>
              <h3 className="font-bold text-sm mb-2 text-orange-700 text-center tracking-wide uppercase">
                DANH SÁCH RẠP
              </h3>
              {cinemas.length === 0 && (
                <div className="text-gray-400 italic text-center">Không có rạp nào trong thành phố này.</div>
              )}
              {cinemas.map(cinemaName => {
                const showtimesOfCinema = showtimes.filter(
                  s => s.cityName === selected.city && s.cinemaName === cinemaName && s.showDate === selectedDate
                );
                if (showtimesOfCinema.length === 0) return null;
                const timesOfDate = [...new Set(showtimesOfCinema.map(s => s.showTime))];
                return (
                  <div key={cinemaName} className="mb-4 bg-gradient-to-r from-gray-100 to-gray-200 rounded-xl p-3 shadow-inner border border-gray-200">
                    <div className="font-bold text-sm text-orange-700 mb-1 text-center uppercase tracking-wide">{cinemaName}</div>
                    {timesOfDate.length === 0 ? (
                      <div className="text-gray-400 italic text-center">Hiện chưa có lịch chiếu</div>
                    ) : (
                      <div className="flex flex-wrap gap-2 justify-center">
                        {timesOfDate.map(time => {
                          const showtimeObj = showtimesOfCinema.find(s => s.showTime === time);
                          const isSelected = selected.time === time && selected.cinema === cinemaName;
                          return (
                            <button
                              key={time}
                              className={`px-4 py-1.5 rounded-lg font-bold border shadow transition-all duration-200 text-sm
                                ${isSelected
                                  ? "bg-gradient-to-r from-orange-400 to-orange-500 text-white border-orange-600 scale-105"
                                  : "bg-white text-orange-700 border-orange-400 hover:bg-orange-50 hover:scale-105"}`}
                              onClick={() => {
                                setSelected(prev => ({
                                  ...prev,
                                  city: prev.city,
                                  cinema: cinemaName,
                                  date: selectedDate,
                                  time,
                                  room: showtimeObj.cinemaRoomName,
                                  showtime: showtimeObj,
                                }));
                                setAvailableSeats(showtimeObj.seats || []);
                                setSelectedSeats([]);
                              }}
                            >
                              {time}
                            </button>
                          );
                        })}
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          )}

          {/* Hiển thị chọn ghế nếu đã chọn đủ thành phố, ngày, rạp, giờ */}
          {selected.city && selected.cinema && selected.date && selected.time && selected.showtime && (
            <div className="mt-6 transition-all duration-500">
              <BookSeat
                movie={movieTitle}
                availableSeats={availableSeats}
                selectedSeats={selectedSeats}
                handleSelectSeat={handleSelectSeat}
                handleBack={() => {}}
                setBookingInfo={setBookingInfo}
                bookingInfo={bookingInfo}
                selectedFoods={selectedFoods}
                setSelectedFoods={setSelectedFoods}
              />
            </div>
          )}
        </div>
      </div>
    );

  // Bước 2: Chọn ghế
  if (step === 2)
    return (
      <BookSeat
        movie={movieTitle}
        availableSeats={availableSeats}
        selectedSeats={selectedSeats}
        handleSelectSeat={handleSelectSeat}
        handleBack={() => setStep(1)}
        selectedFoods={selectedFoods}
        setSelectedFoods={setSelectedFoods}
      />
    );

  if (step === 3)
    return (
      <div className="text-center py-8">
        <h2 className="text-2xl font-bold text-orange-600 mb-4 drop-shadow-lg">Đặt vé thành công!</h2>
        <pre className="bg-gray-100 rounded p-4 text-left inline-block text-gray-800">{JSON.stringify(successInfo, null, 2)}</pre>
      </div>
    );

  return (
    <>
      {/* ...UI các bước chọn... */}
      {/* Chỉ hiển thị Snackbar khi đã chọn giờ và có đủ thông tin */}
      {selected.time && (
        <Snackbar
          movieId={movieId}
          movieTitle={bookingInfo.movieTitle}
          cinemaName={bookingInfo.cinemaName}
          cityName={bookingInfo.cityName}
          selectedSeats={bookingInfo.selectedSeats}
          totalPrice={bookingInfo.totalPrice}
          date={bookingInfo.date}
          time={bookingInfo.time}
          showtime={selected.showtime}
          onError={setError}
          disabled={
            !bookingInfo.cityName ||
            !bookingInfo.cinemaName ||
            !bookingInfo.date ||
            !bookingInfo.time ||
            bookingInfo.selectedSeats.length === 0
          }
          selectedFoods={selectedFoods}
        />
      )}
    </>
  );
};

export default BookMovieTicket;

import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom"; // Thêm dòng này
import { getShowtimesByMovie } from "../../../service/bookmovieticket";
import BookSeat from "./BookSeat";
import ConfirmBooking from "./ConfirmBooking";
import { FiLogIn } from "react-icons/fi";
import { MdEventBusy } from "react-icons/md";
import Snackbar from "./Snackbar"; // Import Snackbar

const BookMovieTicket = ({ movieId, movieTitle, poster, isComingSoon = false, quickBooking, bookingInfo, setBookingInfo, onShowtimeChange, selectedFoods, setSelectedFoods }) => {
  const [showtimes, setShowtimes] = useState([]);
  const [cities, setCities] = useState([]);
  const [cinemas, setCinemas] = useState([]);
  const [rooms, setRooms] = useState([]);
  const [dates, setDates] = useState([]);
  const [times, setTimes] = useState([]);
  const [selected, setSelected] = useState({
    city: "",
    cinema: "",
    room: "",
    date: "",
    time: "",
    showtime: null,
  });
  const [availableSeats, setAvailableSeats] = useState([]);
  const [selectedSeats, setSelectedSeats] = useState([]);
  const [step, setStep] = useState(1);
  const [confirmInfo, setConfirmInfo] = useState(null);
  const [successInfo, setSuccessInfo] = useState(null);
  const [loading, setLoading] = useState(false);
  const [apiMessage, setApiMessage] = useState("");
  const [error, setError] = useState("");
  const [showRoomDropdown, setShowRoomDropdown] = useState(true);
  const [selectedDate, setSelectedDate] = useState(""); // Thêm state này
  const navigate = useNavigate(); // Thêm dòng này

  // Lấy dữ liệu suất chiếu và flatten
  useEffect(() => {
    const fetchShowtimes = async () => {
      setLoading(true);
      try {
        const res = await getShowtimesByMovie(movieId);
        const result = res.data.result;
        let flatShowtimes = [];
        if (result && result.dates) {
          result.dates.forEach(dateObj => {
            const showDate = dateObj.date;
            dateObj.cities.forEach(city => {
              const cityName = city.name;
              city.cinemas.forEach(cinema => {
                const cinemaName = cinema.name;
                cinema.cinemaRooms.forEach(room => {
                  const cinemaRoomName = room.roomName;
                  const cinemaRoomId = room.cinemaRoomID || room.cinemaRoomId;
                  // Lọc chỉ times active
                  room.times
                    .filter(time => time.active)
                    .forEach(time => {
                      flatShowtimes.push({
                        cityName,
                        cinemaName,
                        cinemaRoomName,
                        cinemaRoomId,
                        showDate,
                        showTime: time.time,
                        seats: time.seats,
                      });
                    });
                });
              });
            });
          });
        }
        setShowtimes(flatShowtimes);
        setCities([...new Set(flatShowtimes.map((s) => s.cityName))]);
      } catch {
        setError("Đăng nhập để đặt vé.");
      }
      setLoading(false);
    };
    fetchShowtimes();
  }, [movieId]);

  // Dropdown logic
  useEffect(() => {
    if (!selected.city) {
      setCinemas([]);
      setSelected(prev => ({ ...prev, cinema: "", date: "", time: "", room: "", showtime: null }));
      return;
    }
    const filtered = showtimes.filter(s => s.cityName === selected.city);
    setCinemas([...new Set(filtered.map(s => s.cinemaName))]);
    // Không reset cinema nếu đã chọn
  }, [selected.city, showtimes]);

  // Khi chọn rạp, chỉ reset ngày, giờ, phòng, showtime
  useEffect(() => {
    if (!selected.cinema) {
      setDates([]);
      setSelected(prev => ({ ...prev, date: "", time: "", room: "", showtime: null }));
      return;
    }
    const filtered = showtimes.filter(
      s => s.cityName === selected.city && s.cinemaName === selected.cinema
    );
    setDates([...new Set(filtered.map(s => s.showDate))]);
    // Không reset cinema ở đây nữa
  }, [selected.cinema, selected.city, showtimes]);

  // Khi chọn ngày, chỉ reset giờ, phòng, showtime
  useEffect(() => {
    if (!selected.date) {
      setTimes([]);
      setSelected(prev => ({ ...prev, time: "", room: "", showtime: null }));
      return;
    }
    const filtered = showtimes.filter(
      s =>
        s.cityName === selected.city &&
        s.cinemaName === selected.cinema &&
        s.showDate === selected.date
    );
    setTimes([...new Set(filtered.map(s => s.showTime))]);
    // Không reset date ở đây nữa
  }, [selected.date, selected.cinema, selected.city, showtimes]);

  // Khi chọn giờ, chỉ reset phòng, showtime
  useEffect(() => {
    if (!selected.time) {
      setShowRoomDropdown(true);
      setRooms([]);
      setSelected(prev => ({ ...prev, room: "", showtime: null }));
      return;
    }
    const filtered = showtimes.filter(
      s =>
        s.cityName === selected.city &&
        s.cinemaName === selected.cinema &&
        s.showDate === selected.date &&
        s.showTime === selected.time
    );
    const uniqueRooms = [...new Set(filtered.map(s => s.cinemaRoomName))];
    setRooms(uniqueRooms);

    if (uniqueRooms.length === 1) {
      setShowRoomDropdown(false);
      setSelected(prev => ({
        ...prev,
        room: uniqueRooms[0],
        showtime: filtered.find(s => s.cinemaRoomName === uniqueRooms[0]),
      }));
      setAvailableSeats(filtered[0]?.seats || []);
      setSelectedSeats([]);
    } else {
      setShowRoomDropdown(true);
      setSelected(prev => ({ ...prev, room: "", showtime: null }));
      setAvailableSeats([]);
      setSelectedSeats([]);
    }
  }, [selected.time, selected.date, selected.cinema, selected.city, showtimes]);

  useEffect(() => {
    if (!showRoomDropdown || !selected.room) return;
    const showtime = showtimes.find(
      s =>
        s.cityName === selected.city &&
        s.cinemaName === selected.cinema &&
        s.showDate === selected.date &&
        s.showTime === selected.time &&
        s.cinemaRoomName === selected.room
    );
    setSelected(prev => ({ ...prev, showtime }));
    setAvailableSeats(showtime ? showtime.seats : []);
    setSelectedSeats([]);
  }, [selected.room, showRoomDropdown, selected.city, selected.cinema, selected.date, selected.time, showtimes]);

  // Chọn ghế
  const handleSelectSeat = seat => {
    if (seat.status === "sold" || seat.isAvailable === false) return;
    setSelectedSeats(prev =>
      prev.some(s => s.seatID === seat.seatID)
        ? prev.filter(s => s.seatID !== seat.seatID)
        : [...prev, seat]
    );
    setError("");
  };

  // Khi có quickBooking, tự động set các dropdown
  useEffect(() => {
    if (
      quickBooking &&
      quickBooking.city &&
      quickBooking.cinema &&
      quickBooking.date &&
      quickBooking.time
    ) {
      setSelected(prev => ({
        ...prev,
        city: quickBooking.city,
        cinema: quickBooking.cinema,
        date: quickBooking.date,
        time: quickBooking.time,
      }));
      setSelectedDate(quickBooking.date); // Nếu bạn dùng selectedDate cho UI ngày
      
      // Nếu có showtime từ quickBooking, sử dụng nó
      if (quickBooking.showtime) {
        setSelected(prev => ({
          ...prev,
          showtime: quickBooking.showtime,
          room: quickBooking.showtime.cinemaRoomName,
        }));
        setAvailableSeats(quickBooking.showtime.seats || []);
        setSelectedSeats([]);
      }
    }
  }, [quickBooking, showtimes]);

  // Cập nhật thông tin booking khi chọn thành phố, rạp, ngày, giờ
  useEffect(() => {
    setBookingInfo(prev => ({
      ...prev,
      movieTitle,
      cityName: selected.city,
      cinemaName: selected.cinema,
      date: selected.date,
      time: selected.time,
    }));
  }, [selected.city, selected.cinema, selected.date, selected.time, movieTitle, setBookingInfo]);

  // Cập nhật khi chọn ghế
  useEffect(() => {
    const totalPrice = selectedSeats.reduce((sum, seat) => sum + (seat.price || 75000), 0);
    setBookingInfo(prev => ({
      ...prev,
      selectedSeats,
      totalPrice,
    }));
  }, [selectedSeats, setBookingInfo]);

  // Đồng bộ selectedFoods vào bookingInfo
  useEffect(() => {
    setBookingInfo(prev => ({
      ...prev,
      selectedFoods,
    }));
  }, [selectedFoods, setBookingInfo]);

  // Cập nhật khi showtime thay đổi
  useEffect(() => {
    if (onShowtimeChange && selected.showtime) {
      onShowtimeChange(selected.showtime);
    }
  }, [selected.showtime, onShowtimeChange]);

  useEffect(() => {
    if (!isComingSoon) return;

    setSelected(prev => ({
      ...prev,
      cinema: prev.cinema,
      date: prev.date,
      time: "",
      room: "",
      showtime: null,
    }));
    setAvailableSeats([]);
    setSelectedSeats([]);
    setBookingInfo(prev => ({
      ...prev,
      time: "",
      selectedSeats: [],
      totalPrice: 0,
    }));
  }, [isComingSoon, setBookingInfo]);

  // UI
  if (loading) return <div className="text-center py-4 text-orange-500 font-semibold">Đang tải...</div>;

  if (error === "Đăng nhập để đặt vé.") {
    return (
      <div className="flex items-center justify-center gap-2 text-orange-500 font-extrabold text-xl text-center drop-shadow-lg animate-pulse">
        <FiLogIn size={38} />
        <span className="drop-shadow">ĐĂNG NHẬP ĐỂ ĐẶT VÉ</span>
      </div>
    );
  }
  if (error === "Vui lòng đăng nhập để đặt vé!") {
    return (
      <div className="flex items-center justify-center gap-2 text-orange-500 font-extrabold text-xl text-center drop-shadow-lg animate-pulse">
        <FiLogIn size={38} />
        <span className="drop-shadow">VUI LÒNG ĐĂNG NHẬP ĐỂ ĐẶT VÉ!</span>
      </div>
    );
  } else if (error) {
    return <div className="text-orange-500 text-center mt-2 font-semibold">{error}</div>;
  }

  // THÊM ĐOẠN NÀY để xử lý trường hợp không có suất chiếu
  if (step === 1 && showtimes.length === 0) {
    return (
      <div className="flex items-center justify-center gap-2 text-orange-500 font-extrabold text-xl text-center drop-shadow-lg animate-pulse">
        <MdEventBusy size={38} />
        <span className="drop-shadow">HIỆN CHƯA CÓ LỊCH CHIẾU</span>
      </div>
    );
  }

  if (step === 1)
    return (
      <div className="flex justify-center items-center bg-transparent py-6" style={{ fontSize: "80%" }}>
        <div className="w-full">
          <h2 className="font-bold text-2xl mb-3 text-orange-500 text-center tracking-wide drop-shadow-lg uppercase">LỊCH CHIẾU</h2>
          {/* Thành phố */}
          <div className="mb-4 flex justify-center items-center gap-2">
            <select
              className="px-3 py-1.5 rounded-lg border border-orange-400 focus:border-orange-600 focus:outline-none min-w-[110px] text-gray-900 font-bold bg-white shadow transition text-sm"
              value={selected.city}
              onChange={e => {
                setSelected(prev => ({ ...prev, city: e.target.value, cinema: "", date: "", time: "", room: "", showtime: null }));
                setSelectedDate("");
              }}
            >
              <option value="">-- Chọn thành phố --</option>
              {cities.map(city => (
                <option key={city} className="text-sm">{city}</option>
              ))}
            </select>
          </div>

          {/* Chọn ngày */}
          {selected.city && (() => {
            const showtimesOfCity = showtimes.filter(s => s.cityName === selected.city);
            const allDates = [...new Set(showtimesOfCity.map(s => s.showDate))];
            if (allDates.length === 0) return null;
            return (
              <div className="mb-4 flex gap-2 justify-center">
                {allDates.map(date => (
                  <button
                    key={date}
                    className={`px-4 py-1.5 rounded-lg font-bold border shadow transition-all duration-200 text-sm
                      ${selectedDate === date
                        ? "bg-gradient-to-r from-orange-400 to-orange-500 text-white border-orange-600 scale-105"
                        : "bg-white text-orange-700 border-orange-400 hover:bg-orange-50 hover:scale-105"}`}
                    onClick={() => {
                      setSelectedDate(date);
                      setSelected(prev => ({ ...prev, date, cinema: "", time: "", room: "", showtime: null }));
                    }}
                  >
                    {date}
                  </button>
                ))}
              </div>
            );
          })()}

          {/* Danh sách rạp, giờ */}
          {selected.city && selectedDate && (
            <div>
              <h3 className="font-bold text-sm mb-2 text-orange-700 text-center tracking-wide uppercase">
                DANH SÁCH RẠP
              </h3>
              {isComingSoon && (
                <div className="text-center text-orange-400 font-bold mb-3">
                  Phim sắp chiếu - hiện chưa mở chọn suất và đặt vé.
                </div>
              )}
              {cinemas.length === 0 && (
                <div className="text-gray-400 italic text-center">Không có rạp nào trong thành phố này.</div>
              )}
              {cinemas.map(cinemaName => {
                const showtimesOfCinema = showtimes.filter(
                  s => s.cityName === selected.city && s.cinemaName === cinemaName && s.showDate === selectedDate
                );
                if (showtimesOfCinema.length === 0) return null;
                const timesOfDate = [...new Set(showtimesOfCinema.map(s => s.showTime))];
                return (
                  <div key={cinemaName} className="mb-4 bg-gradient-to-r from-gray-100 to-gray-200 rounded-xl p-3 shadow-inner border border-gray-200">
                    <div className="font-bold text-sm text-orange-700 mb-1 text-center uppercase tracking-wide">{cinemaName}</div>
                    {timesOfDate.length === 0 ? (
                      <div className="text-gray-400 italic text-center">Hiện chưa có lịch chiếu</div>
                    ) : (
                      <div className="flex flex-wrap gap-2 justify-center">
                        {timesOfDate.map(time => {
                          const showtimeObj = showtimesOfCinema.find(s => s.showTime === time);
                          const isSelected = selected.time === time && selected.cinema === cinemaName;
                          return (
                            <button
                              key={time}
                              className={`px-4 py-1.5 rounded-lg font-bold border shadow transition-all duration-200 text-sm
                                ${isComingSoon
                                  ? "bg-gray-200 text-gray-500 border-gray-300 cursor-not-allowed hover:scale-100"
                                  : ""}
                                ${isSelected
                                  ? "bg-gradient-to-r from-orange-400 to-orange-500 text-white border-orange-600 scale-105"
                                  : "bg-white text-orange-700 border-orange-400 hover:bg-orange-50 hover:scale-105"}`}
                              onClick={() => {
                                if (isComingSoon) return;
                                setSelected(prev => ({
                                  ...prev,
                                  city: prev.city,
                                  cinema: cinemaName,
                                  date: selectedDate,
                                  time,
                                  room: showtimeObj.cinemaRoomName,
                                  showtime: showtimeObj,
                                }));
                                setAvailableSeats(showtimeObj.seats || []);
                                setSelectedSeats([]);
                              }}
                              disabled={isComingSoon}
                            >
                              {time}
                            </button>
                          );
                        })}
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          )}

          {/* Hiển thị chọn ghế nếu đã chọn đủ thành phố, ngày, rạp, giờ */}
          {selected.city && selected.cinema && selected.date && selected.time && selected.showtime && (
            <div className="mt-6 transition-all duration-500">
              <BookSeat
                movie={movieTitle}
                availableSeats={availableSeats}
                selectedSeats={selectedSeats}
                handleSelectSeat={handleSelectSeat}
                handleBack={() => {}}
                setBookingInfo={setBookingInfo}
                bookingInfo={bookingInfo}
                selectedFoods={selectedFoods}
                setSelectedFoods={setSelectedFoods}
              />
            </div>
          )}
        </div>
      </div>
    );

  // Bước 2: Chọn ghế
  if (step === 2)
    return (
      <BookSeat
        movie={movieTitle}
        availableSeats={availableSeats}
        selectedSeats={selectedSeats}
        handleSelectSeat={handleSelectSeat}
        handleBack={() => setStep(1)}
        selectedFoods={selectedFoods}
        setSelectedFoods={setSelectedFoods}
      />
    );

  if (step === 3)
    return (
      <div className="text-center py-8">
        <h2 className="text-2xl font-bold text-orange-600 mb-4 drop-shadow-lg">Đặt vé thành công!</h2>
        <pre className="bg-gray-100 rounded p-4 text-left inline-block text-gray-800">{JSON.stringify(successInfo, null, 2)}</pre>
      </div>
    );

  return (
    <>
      {/* ...UI các bước chọn... */}
      {/* Chỉ hiển thị Snackbar khi đã chọn giờ và có đủ thông tin */}
      {selected.time && (
        <Snackbar
          movieId={movieId}
          movieTitle={bookingInfo.movieTitle}
          cinemaName={bookingInfo.cinemaName}
          cityName={bookingInfo.cityName}
          selectedSeats={bookingInfo.selectedSeats}
          totalPrice={bookingInfo.totalPrice}
          date={bookingInfo.date}
          time={bookingInfo.time}
          showtime={selected.showtime}
          onError={setError}
          disabled={
            isComingSoon ||
            !bookingInfo.cityName ||
            !bookingInfo.cinemaName ||
            !bookingInfo.date ||
            !bookingInfo.time ||
            bookingInfo.selectedSeats.length === 0
          }
          selectedFoods={selectedFoods}
        />
      )}
    </>
  );
};

