      city: cityName,
      date: "",
      time: ""
    }));
  };


  const handlePrimaryChange = (e) => {
    const value = e.target.value;
    if (isShowtimeMode) {
      setSelected(prev => ({
        ...prev,
        city: value,
        cinema: "",
        date: "",
