            </div>
            <div className="font-medium text-gray-600">Trạng thái:</div>
            <div className="font-semibold capitalize">{order.status || "Không có"}</div>
            <div className="font-medium text-gray-600">Ngày đặt vé:</div>
            <div className="font-semibold">
              {order.bookingDate
                ? new Date(order.bookingDate).toLocaleString("vi-VN")
                : "Không có"}
            </div>

          </div>
          {/* Lưu ý */}
          <div className="bg-gray-50 border border-gray-200 rounded p-2 text-xs text-gray-700 mb-2">
            <strong>Lưu ý/Note:</strong>
            <br />
            Vé đã mua không thể huỷ, đổi hoặc trả lại. Vui lòng liên hệ Ban Quản Lý rạp hoặc tra cứu thông tin tại mục{" "}
            <a href="#" className="text-blue-600 underline">Điều khoản mua và sử dụng vé xem phim</a> để biết thêm chi tiết.
            Cảm ơn bạn đã lựa chọn mua vé! Chúc bạn xem phim vui vẻ!
          </div>
          <button
            onClick={() => handleDownloadTicket(cardRef.current, `ve_xem_phim_${order.ticketId || order.bookingId}.png`)}
            className="w-full py-2 bg-gradient-to-r from-orange-600 to-yellow-500 hover:from-orange-500 hover:to-yellow-400 text-black rounded font-semibold transition"
          >
            Lưu vé
          </button>

          <button
            onClick={() => navigate("/profile")}
            className="w-full mt-2 py-2 bg-black text-white rounded font-semibold hover:bg-gray-800 transition mb-2"
          >
            Quay lại
          </button>

        </div>
      </div>
    </div>
  );
};

export default MyOrderedDetail;

import { useState, useEffect } from "react";
import { getScoreHistories, getAllPromotionsForCustomer } from "../../../../service/voucher/index";
import { FiSearch, FiFilter } from "react-icons/fi";
import { motion, AnimatePresence } from "framer-motion";

/**
 * Lấy customerID từ token hoặc localStorage (giả sử lưu ở user.customerID)
 */
function getCustomerID() {
  return localStorage.getItem("id");
}

const MyVoucher = (props) => {
  const [scoreHistories, setScoreHistories] = useState([]);
  const [vouchers, setVouchers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState(props.defaultTab || "score"); // "score" hoặc "voucher"
  const [search, setSearch] = useState("");
  const [typeFilter, setTypeFilter] = useState(""); // "plus", "minus", ""
  const [dateFilter, setDateFilter] = useState(""); // yyyy-mm-dd
  const PAGE_SIZE_OPTIONS = [10, 25, 50];
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(PAGE_SIZE_OPTIONS[0]);
  const [selectedVoucher, setSelectedVoucher] = useState(null);
  const [showModal, setShowModal] = useState(false);
  useEffect(() => { setPage(1); }, [search, typeFilter, dateFilter, pageSize]);

  useEffect(() => {
    const customerID = getCustomerID();
    if (!customerID) {
      setLoading(false);
      return;
    }
    const fetchData = async () => {
      setLoading(true);
      try {
        const scoreRes = await getScoreHistories(customerID);
        setScoreHistories(Array.isArray(scoreRes.result) ? scoreRes.result : []);
        if (activeTab === "voucher") {
          const promoRes = await getAllPromotionsForCustomer();
          setVouchers(Array.isArray(promoRes.result) ? promoRes.result : []);
        }
      } catch (error) {
        setScoreHistories([]);
        setVouchers([]);
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, [activeTab]);

  // Filtered histories
  const filteredScores = scoreHistories.filter(item => {
    const q = search.toLowerCase();
    const matchSearch = !q || (item.movieName && item.movieName.toLowerCase().includes(q));
    const matchType = !typeFilter || item.actionType === typeFilter;
    const matchDate = !dateFilter || (item.dateCreate && new Date(item.dateCreate).toISOString().slice(0,10) === dateFilter);
    return matchSearch && matchType && matchDate;
  });

  const total = filteredScores.length;
  const totalPages = Math.ceil(total / pageSize);
  const pagedScores = filteredScores.slice((page - 1) * pageSize, page * pageSize);

  // Khi đổi pageSize, nếu page hiện tại > tổng số trang mới, set page về tổng số trang mới
  useEffect(() => {
    const totalPages = Math.ceil(filteredScores.length / pageSize);
    if (page > totalPages) setPage(totalPages || 1);
  }, [pageSize, filteredScores.length]);

  if (loading) {
    return <div className="text-center py-4">Đang tải dữ liệu...</div>;
  }

  return (
    <>
      {/* Modal chi tiết voucher - render ngoài cùng để không bị giới hạn max-w */}
      {showModal && selectedVoucher && (
        <div className="fixed z-50 left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 flex items-center justify-center pointer-events-auto px-2">
          <div className="bg-white rounded-2xl py-5 px-6 max-w-full w-[450px] shadow-2xl relative border-2 border-orange-300 flex flex-col items-center gap-3">
            <button
              className="absolute top-3 right-4 text-gray-500 hover:text-orange-500 text-3xl font-bold"
              onClick={() => setShowModal(false)}
            >
              &times;
            </button>
            <img src={selectedVoucher.image} alt={selectedVoucher.title} className="w-40 h-28 object-contain rounded-xl border bg-white mb-2" />
            <h2 className="text-2xl font-bold text-orange-600 mb-1 text-center line-clamp-2">{selectedVoucher.title}</h2>
            <div className="flex items-center gap-2 mb-2 justify-center">
              <span className={`px-2 py-0.5 rounded-full text-xs font-bold tracking-wide shadow-sm ${selectedVoucher.promotionType === 'PERCENTAGE' ? 'bg-orange-100 text-orange-600' : 'bg-blue-100 text-blue-600'}`}>{selectedVoucher.promotionType === 'PERCENTAGE' ? 'Giảm %' : 'Giảm giá'}</span>
              <span className="text-lg font-extrabold text-orange-500">{selectedVoucher.value}{selectedVoucher.promotionType === "PERCENTAGE" ? "%" : "đ"}</span>
              {selectedVoucher.maxDiscountAmount && (
                <span className="text-xs text-gray-500">(Tối đa {selectedVoucher.maxDiscountAmount.toLocaleString()}đ)</span>
              )}
            </div>
            <div className="text-base text-gray-700 mb-2 text-center line-clamp-3">{selectedVoucher.detail}</div>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 mt-1 text-sm w-full">
              <div><span className="font-semibold">Thời gian:</span> {selectedVoucher.startTime ? new Date(selectedVoucher.startTime).toLocaleString("vi-VN") : ""} - {selectedVoucher.endTime ? new Date(selectedVoucher.endTime).toLocaleString("vi-VN") : ""}</div>
              {selectedVoucher.condition?.minOrderAmount && (
                <div><span className="font-semibold">Đơn tối thiểu:</span> {selectedVoucher.condition.minOrderAmount.toLocaleString()}đ</div>
              )}
              {selectedVoucher.groupCode && (
                <div><span className="font-semibold">Group code:</span> {selectedVoucher.groupCode}</div>
              )}
              {selectedVoucher.isExclusive !== undefined && (
                <div><span className="font-semibold">Độc quyền:</span> {selectedVoucher.isExclusive ? "Có" : "Không"}</div>
              )}
              {selectedVoucher.maxTotalUsage && (
                <div><span className="font-semibold">Tổng số lượt sử dụng tối đa:</span> {selectedVoucher.maxTotalUsage}</div>
              )}
              {selectedVoucher.maxUsagePerCustomer && (
                <div><span className="font-semibold">Số lượt sử dụng tối đa mỗi khách:</span> {selectedVoucher.maxUsagePerCustomer}</div>
              )}
              {selectedVoucher.condition?.applicableRoles && selectedVoucher.condition.applicableRoles.length > 0 && (
                <div><span className="font-semibold">Áp dụng cho vai trò:</span> {selectedVoucher.condition.applicableRoles.join(", ")}</div>
              )}
              {selectedVoucher.condition?.applicableRanks && selectedVoucher.condition.applicableRanks.length > 0 && (
                <div><span className="font-semibold">Áp dụng cho hạng:</span> {selectedVoucher.condition.applicableRanks.join(", ")}</div>
              )}
              {selectedVoucher.condition?.dayOfWeek && selectedVoucher.condition.dayOfWeek.length > 0 && (
                <div><span className="font-semibold">Áp dụng các ngày:</span> {selectedVoucher.condition.dayOfWeek.join(", ")}</div>
              )}
            </div>
            <div className="mt-6 flex justify-end">
              <button
                className="px-5 py-2 bg-orange-500 text-white rounded-lg hover:bg-orange-600 font-semibold shadow"
                onClick={() => setShowModal(false)}
              >
                Đóng
              </button>
            </div>
          </div>
        </div>
      )}
      <div className="max-w-2xl mx-auto mt-8 space-y-10">
        {/* Tabs */}
        <div className="flex justify-center mb-8 gap-4">
          <button
            className={`px-6 py-2 rounded-lg font-semibold border transition focus:outline-none ${
              activeTab === "voucher"
                ? "bg-orange-500 text-white border-orange-500 shadow"
                : "bg-white text-orange-500 border-orange-300 hover:bg-orange-50"
            }`}
            onClick={() => setActiveTab("voucher")}
          >
            Voucher của tôi
          </button>
        </div>

        {/* Nội dung bảng tương ứng */}
        <div key={activeTab} className="transition-all duration-500 ease-out animate-fade-in-slide">
          {activeTab === "score" && (
            <div>
              <h2 className="text-2xl font-bold mb-6 text-center text-gray-800">
                Lịch sử nhận điểm khi mua vé
              </h2>
              {/* Filter bar nhỏ gọn */}
              <div className="flex flex-col sm:flex-row sm:items-end sm:gap-4 gap-2 mb-4">
                {/* Search phim */}
                <div className="flex flex-col flex-1 min-w-[120px]">
                  <label className="text-gray-700 font-medium mb-1 flex items-center gap-1 text-sm" htmlFor="score-search">
                    <FiSearch className="inline" size={14} /> Tìm phim
                  </label>
                  <input
                    id="score-search"
                    type="text"
                    className="border px-2 py-1 text-sm focus:ring-2 focus:ring-blue-400 focus:border-blue-400 transition placeholder:text-gray-400 rounded-xl"
                    placeholder="Tên phim..."
                    value={search}
                    onChange={e => setSearch(e.target.value)}
                  />
                </div>
                {/* Filter loại */}
                <div className="flex flex-col min-w-[100px]">
                  <label className="text-gray-700 font-medium mb-1 flex items-center gap-1 text-sm" htmlFor="score-type">
                    <FiFilter className="inline" size={14} /> Loại
                  </label>
                  <select
                    id="score-type"
                    className="border px-2 py-1 text-sm focus:ring-2 focus:ring-blue-400 focus:border-blue-400 transition rounded-xl"
                    value={typeFilter}
                    onChange={e => setTypeFilter(e.target.value)}
                  >
                    <option value="">Tất cả</option>
                    <option value="plus">Cộng</option>
                    <option value="minus">Trừ</option>
                  </select>
                </div>
                {/* Filter ngày */}
                <div className="flex flex-col min-w-[120px]">
                  <label className="text-gray-700 font-medium mb-1 flex items-center gap-1 text-sm" htmlFor="score-date">
                    <svg xmlns='http://www.w3.org/2000/svg' className='inline w-4 h-4' fill='none' viewBox='0 0 24 24' stroke='currentColor'><path strokeLinecap='round' strokeLinejoin='round' strokeWidth={2} d='M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z' /></svg> Ngày
                  </label>
                  <input
                    id="score-date"
                    type="date"
                    className="border px-2 py-1 text-sm focus:ring-2 focus:ring-blue-400 focus:border-blue-400 transition rounded-xl"
                    value={dateFilter}
                    onChange={e => setDateFilter(e.target.value)}
                    pattern="(0[1-9]|1[0-2])/[0-3][0-9]/[0-9]{4}"
                  />
                </div>
              </div>
              {pagedScores.length === 0 ? (
                <div className="text-gray-600 text-center py-8 bg-gray-50 rounded-lg shadow">
                  Bạn chưa có lịch sử nhận điểm nào.
                </div>
              ) : (
                <div className="w-full">
                  <ul className="flex flex-col gap-1">
                    {/* Header row */}

                    {pagedScores.map((item) => (
                      <li
                        key={item.scoreID}
                        className="flex items-center px-2 py-2 rounded-xl hover:bg-blue-50 transition text-base group border border-gray-100"
                      >
                        {/* Icon loại điểm */}
                        <span className={`inline-flex items-center justify-center rounded-full w-7 h-7 text-base font-bold mr-2 ${item.actionType === 'plus' ? 'bg-green-100 text-green-600' : 'bg-red-100 text-red-600'}`}>{item.actionType === 'plus' ? '+' : '-'}</span>
                        {/* Ngày */}
                        <span className="min-w-[100px] w-[100px] text-gray-500 text-sm tabular-nums">
                          {item.dateCreate ? new Date(item.dateCreate).toLocaleDateString("vi-VN") : ""}
                        </span>
                        {/* Tên phim */}
                        <span className="flex-1 font-medium text-gray-800 truncate max-w-[180px]" title={item.movieName}>
                          {item.movieName}
                        </span>
                        {/* Loại */}
                        <span className="w-[70px] flex justify-center items-center flex-shrink-0">
                          <span className={`inline-flex items-center justify-center rounded-full px-3 py-0.5 text-sm font-semibold min-w-[48px] ${item.actionType === 'plus' ? 'bg-green-50 text-green-700 border border-green-200' : 'bg-red-50 text-red-700 border border-red-200'}`}>{item.actionType === 'plus' ? 'Cộng' : 'Trừ'}</span>
                        </span>
                        {/* Số điểm */}
                        <span className={`w-[90px] text-right font-bold tabular-nums flex-shrink-0 ${item.actionType === 'plus' ? 'text-green-600' : 'text-red-600'}`}>
                          <span className="text-lg align-middle">{item.actionType === 'plus' ? '+' : '-'}</span>
                          <span className="align-middle">{item.amount}</span>
                          <span className="text-xs font-normal text-gray-400 ml-0.5 align-middle">đ</span>
                        </span>
                      </li>
                    ))}
                  </ul>
                  {/* Pagination + PageSize select nhỏ gọn, nằm trong container, không fixed */}
                  <div className="flex flex-col sm:flex-row sm:items-center justify-between mt-6 gap-2 bg-white rounded-xl border border-blue-100 shadow-sm px-2 py-2">
                    <div className="flex justify-center sm:justify-start gap-1">
                      <button
                        className="px-2 py-1 rounded-md border bg-white hover:bg-blue-50 disabled:opacity-50 flex items-center justify-center text-sm"
                        onClick={() => setPage(p => Math.max(1, p - 1))}
                        disabled={page === 1}
                        aria-label="Trang trước"
                      >
                        <svg width="16" height="16" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" d="M15 19l-7-7 7-7" /></svg>
                      </button>
                      {Array.from({ length: totalPages }, (_, i) => (
                        <button
                          key={i}
                          className={`px-2 py-1 rounded-md border flex items-center justify-center text-sm font-medium ${page === i + 1 ? 'bg-blue-500 text-white border-blue-500' : 'bg-white hover:bg-blue-50'}`}
                          onClick={() => setPage(i + 1)}
                        >
                          {i + 1}
                        </button>
                      ))}
                      <button
                        className="px-2 py-1 rounded-md border bg-white hover:bg-blue-50 disabled:opacity-50 flex items-center justify-center text-sm"
                        onClick={() => setPage(p => Math.min(totalPages, p + 1))}
                        disabled={page === totalPages}
                        aria-label="Trang sau"
                      >
                        <svg width="16" height="16" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" d="M9 5l7 7-7 7" /></svg>
                      </button>
                    </div>
                    <div className="flex justify-center sm:justify-end">
                      <select
                        className="border rounded-md px-2 py-1 text-sm focus:ring-2 focus:ring-blue-400"
                        value={pageSize}
                        onChange={e => setPageSize(Number(e.target.value))}
                      >
                        {PAGE_SIZE_OPTIONS.map(opt => (
                          <option key={opt} value={opt}>{opt} / page</option>
                        ))}
                      </select>
                    </div>
                  </div>
                </div>
              )}
            </div>
          )}

          {activeTab === "voucher" && (
            <div>
              <h2 className="text-2xl font-bold mb-6 text-center text-gray-800">
                Danh sách voucher của bạn
              </h2>
              {vouchers.length === 0 ? (
                <div className="text-gray-600 text-center py-8 bg-gray-50 rounded-lg shadow">
                  Bạn chưa có voucher nào.
                </div>
              ) : (
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                  <AnimatePresence>
                    {vouchers.map((voucher, idx) => (
                      <motion.div
                        key={voucher.promotionId}
                        initial={{ opacity: 0, y: 40 }}
                        animate={{ opacity: 1, y: 0 }}
                        exit={{ opacity: 0, y: 40 }}
                        transition={{ duration: 0.5, delay: idx * 0.08 }}
                        className="relative flex flex-col bg-orange-50 hover:bg-white rounded-2xl shadow-lg border-2 border-transparent hover:border-orange-400 transition-all duration-300 p-2 overflow-hidden group min-h-[100px] cursor-pointer"
                        onClick={() => {
                          setSelectedVoucher(voucher);
                          setShowModal(true);
                        }}
                      >
                        {/* Ảnh voucher */}
                        {voucher.image && (
                          <img
                            src={voucher.image}
                            alt={voucher.title}
                            className="w-full h-24 object-contain rounded-lg mb-1 border bg-white"
                          />
                        )}
                        {/* Badge loại voucher */}
                        <span className={`absolute top-2 right-2 px-2 py-0.5 rounded-full text-xs font-bold tracking-wide shadow-sm
                          ${voucher.promotionType === 'PERCENTAGE' ? 'bg-orange-100 text-orange-600' : 'bg-blue-100 text-blue-600'}`}
                        >
                          {voucher.promotionType === 'PERCENTAGE' ? 'Giảm %' : 'Giảm giá'}
                        </span>
                        {/* Giá trị giảm giá nổi bật */}
                        <div className="flex items-center gap-2 mb-1">
                          <motion.div
                            whileHover={{ scale: 1.1 }}
                            className="text-2xl font-extrabold text-orange-500 drop-shadow-lg group-hover:scale-105 transition-transform duration-200"
                          >
                            {voucher.value}{voucher.promotionType === "PERCENTAGE" ? "%" : "đ"}
                          </motion.div>
                          <div className="flex flex-col">
                            <span className="text-sm font-semibold text-gray-800 line-clamp-1">{voucher.title}</span>
                            <span className="text-xs text-gray-400">Từ: {voucher.startTime ? new Date(voucher.startTime).toLocaleDateString("vi-VN") : ""} - Đến: {voucher.endTime ? new Date(voucher.endTime).toLocaleDateString("vi-VN") : ""}</span>
                          </div>
                        </div>
                        {/* Chi tiết */}
                        <div className="text-xs text-gray-600 mb-1 line-clamp-2">{voucher.detail}</div>
                        {/* Thông tin bổ sung */}
                        {voucher.condition?.minOrderAmount && (
                          <div className="text-xs text-gray-500 italic mb-1">Áp dụng cho đơn từ {voucher.condition.minOrderAmount.toLocaleString()}đ</div>
                        )}
                        {/* Trạng thái */}
                        <div className="mt-auto flex items-center gap-1">
                          <span className={`inline-block w-2 h-2 rounded-full ${voucher.status === 'ACTIVE' ? 'bg-green-500' : 'bg-gray-400'}`}></span>
                          <span className={`text-xs font-semibold ${voucher.status === 'ACTIVE' ? 'text-green-600' : 'text-gray-500'}`}>{voucher.status === 'ACTIVE' ? 'Đang khả dụng' : 'Không khả dụng'}</span>
                        </div>
                      </motion.div>
                    ))}
                  </AnimatePresence>
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </>
  );
};

export default MyVoucher;

import { useState, useEffect } from "react";
import { getScoreHistories, getAllPromotionsForCustomer, getMyGameCoupons } from "../../../../service/voucher/index";
import { FiSearch, FiFilter } from "react-icons/fi";
import { motion, AnimatePresence } from "framer-motion";

/**
 * Lấy customerID từ token hoặc localStorage (giả sử lưu ở user.customerID)
 */
function getCustomerID() {
  return localStorage.getItem("id");
}

const MyVoucher = (props) => {
  const [scoreHistories, setScoreHistories] = useState([]);
  const [vouchers, setVouchers] = useState([]);
  const [gameCoupons, setGameCoupons] = useState([]);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState(props.defaultTab || "score"); // "score" hoặc "voucher"
  const [search, setSearch] = useState("");
  const [typeFilter, setTypeFilter] = useState(""); // "plus", "minus", ""
  const [dateFilter, setDateFilter] = useState(""); // yyyy-mm-dd
  const PAGE_SIZE_OPTIONS = [10, 25, 50];
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(PAGE_SIZE_OPTIONS[0]);
  const [selectedVoucher, setSelectedVoucher] = useState(null);
  const [showModal, setShowModal] = useState(false);
  useEffect(() => { setPage(1); }, [search, typeFilter, dateFilter, pageSize]);

  useEffect(() => {
    const customerID = getCustomerID();
    if (!customerID) {
      setLoading(false);
      return;
    }
    const fetchData = async () => {
      setLoading(true);
      try {
        const scoreRes = await getScoreHistories(customerID);
        setScoreHistories(Array.isArray(scoreRes.result) ? scoreRes.result : []);
        if (activeTab === "voucher") {
          const promoRes = await getAllPromotionsForCustomer();
          setVouchers(Array.isArray(promoRes.result) ? promoRes.result : []);

          const gameCouponRes = await getMyGameCoupons(customerID);
          setGameCoupons(Array.isArray(gameCouponRes.result) ? gameCouponRes.result : []);
        }
      } catch (error) {
        setScoreHistories([]);
        setVouchers([]);
        setGameCoupons([]);
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, [activeTab]);

  // Filtered histories
  const filteredScores = scoreHistories.filter(item => {
    const q = search.toLowerCase();
    const matchSearch = !q || (item.movieName && item.movieName.toLowerCase().includes(q));
    const matchType = !typeFilter || item.actionType === typeFilter;
    const matchDate = !dateFilter || (item.dateCreate && new Date(item.dateCreate).toISOString().slice(0,10) === dateFilter);
    return matchSearch && matchType && matchDate;
  });

  const total = filteredScores.length;
  const totalPages = Math.ceil(total / pageSize);
  const pagedScores = filteredScores.slice((page - 1) * pageSize, page * pageSize);

  // Khi đổi pageSize, nếu page hiện tại > tổng số trang mới, set page về tổng số trang mới
  useEffect(() => {
    const totalPages = Math.ceil(filteredScores.length / pageSize);
    if (page > totalPages) setPage(totalPages || 1);
  }, [pageSize, filteredScores.length]);

  if (loading) {
    return <div className="text-center py-4">Đang tải dữ liệu...</div>;
  }

  const getGameCouponStatusStyle = (status) => {
    if (status === "ACTIVE") return "bg-green-100 text-green-700";
    if (status === "USED") return "bg-gray-200 text-gray-600";
    if (status === "EXPIRED") return "bg-red-100 text-red-600";
    return "bg-yellow-100 text-yellow-700";
  };

  const getGameCouponStatusLabel = (status) => {
    if (status === "ACTIVE") return "Khả dụng";
    if (status === "USED") return "Đã dùng";
    if (status === "EXPIRED") return "Hết hạn";
    return "Không khả dụng";
  };

  return (
    <>
      {/* Modal chi tiết voucher - render ngoài cùng để không bị giới hạn max-w */}
      {showModal && selectedVoucher && (
        <div className="fixed z-50 left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 flex items-center justify-center pointer-events-auto px-2">
          <div className="bg-white rounded-2xl py-5 px-6 max-w-full w-[450px] shadow-2xl relative border-2 border-orange-300 flex flex-col items-center gap-3">
            <button
              className="absolute top-3 right-4 text-gray-500 hover:text-orange-500 text-3xl font-bold"
              onClick={() => setShowModal(false)}
            >
              &times;
            </button>
            <img src={selectedVoucher.image} alt={selectedVoucher.title} className="w-40 h-28 object-contain rounded-xl border bg-white mb-2" />
            <h2 className="text-2xl font-bold text-orange-600 mb-1 text-center line-clamp-2">{selectedVoucher.title}</h2>
            <div className="flex items-center gap-2 mb-2 justify-center">
              <span className={`px-2 py-0.5 rounded-full text-xs font-bold tracking-wide shadow-sm ${selectedVoucher.promotionType === 'PERCENTAGE' ? 'bg-orange-100 text-orange-600' : 'bg-blue-100 text-blue-600'}`}>{selectedVoucher.promotionType === 'PERCENTAGE' ? 'Giảm %' : 'Giảm giá'}</span>
              <span className="text-lg font-extrabold text-orange-500">{selectedVoucher.value}{selectedVoucher.promotionType === "PERCENTAGE" ? "%" : "đ"}</span>
              {selectedVoucher.maxDiscountAmount && (
                <span className="text-xs text-gray-500">(Tối đa {selectedVoucher.maxDiscountAmount.toLocaleString()}đ)</span>
              )}
            </div>
            <div className="text-base text-gray-700 mb-2 text-center line-clamp-3">{selectedVoucher.detail}</div>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 mt-1 text-sm w-full">
              <div><span className="font-semibold">Thời gian:</span> {selectedVoucher.startTime ? new Date(selectedVoucher.startTime).toLocaleString("vi-VN") : ""} - {selectedVoucher.endTime ? new Date(selectedVoucher.endTime).toLocaleString("vi-VN") : ""}</div>
              {selectedVoucher.condition?.minOrderAmount && (
                <div><span className="font-semibold">Đơn tối thiểu:</span> {selectedVoucher.condition.minOrderAmount.toLocaleString()}đ</div>
              )}
              {selectedVoucher.groupCode && (
                <div><span className="font-semibold">Group code:</span> {selectedVoucher.groupCode}</div>
              )}
              {selectedVoucher.isExclusive !== undefined && (
                <div><span className="font-semibold">Độc quyền:</span> {selectedVoucher.isExclusive ? "Có" : "Không"}</div>
              )}
              {selectedVoucher.maxTotalUsage && (
                <div><span className="font-semibold">Tổng số lượt sử dụng tối đa:</span> {selectedVoucher.maxTotalUsage}</div>
              )}
              {selectedVoucher.maxUsagePerCustomer && (
                <div><span className="font-semibold">Số lượt sử dụng tối đa mỗi khách:</span> {selectedVoucher.maxUsagePerCustomer}</div>
              )}
              {selectedVoucher.condition?.applicableRoles && selectedVoucher.condition.applicableRoles.length > 0 && (
                <div><span className="font-semibold">Áp dụng cho vai trò:</span> {selectedVoucher.condition.applicableRoles.join(", ")}</div>
              )}
              {selectedVoucher.condition?.applicableRanks && selectedVoucher.condition.applicableRanks.length > 0 && (
                <div><span className="font-semibold">Áp dụng cho hạng:</span> {selectedVoucher.condition.applicableRanks.join(", ")}</div>
              )}
              {selectedVoucher.condition?.dayOfWeek && selectedVoucher.condition.dayOfWeek.length > 0 && (
                <div><span className="font-semibold">Áp dụng các ngày:</span> {selectedVoucher.condition.dayOfWeek.join(", ")}</div>
              )}
            </div>
            <div className="mt-6 flex justify-end">
              <button
                className="px-5 py-2 bg-orange-500 text-white rounded-lg hover:bg-orange-600 font-semibold shadow"
                onClick={() => setShowModal(false)}
              >
                Đóng
              </button>
            </div>
          </div>
        </div>
      )}
      <div className="max-w-2xl mx-auto mt-8 space-y-10">
        {/* Tabs */}
        <div className="flex justify-center mb-8 gap-4">
          <button
            className={`px-6 py-2 rounded-lg font-semibold border transition focus:outline-none ${
              activeTab === "voucher"
                ? "bg-orange-500 text-white border-orange-500 shadow"
                : "bg-white text-orange-500 border-orange-300 hover:bg-orange-50"
            }`}
            onClick={() => setActiveTab("voucher")}
          >
            Voucher của tôi
          </button>
        </div>

        {/* Nội dung bảng tương ứng */}
        <div key={activeTab} className="transition-all duration-500 ease-out animate-fade-in-slide">
          {activeTab === "score" && (
            <div>
              <h2 className="text-2xl font-bold mb-6 text-center text-gray-800">
                Lịch sử nhận điểm khi mua vé
              </h2>
              {/* Filter bar nhỏ gọn */}
              <div className="flex flex-col sm:flex-row sm:items-end sm:gap-4 gap-2 mb-4">
                {/* Search phim */}
                <div className="flex flex-col flex-1 min-w-[120px]">
                  <label className="text-gray-700 font-medium mb-1 flex items-center gap-1 text-sm" htmlFor="score-search">
                    <FiSearch className="inline" size={14} /> Tìm phim
                  </label>
                  <input
                    id="score-search"
                    type="text"
                    className="border px-2 py-1 text-sm focus:ring-2 focus:ring-blue-400 focus:border-blue-400 transition placeholder:text-gray-400 rounded-xl"
                    placeholder="Tên phim..."
                    value={search}
                    onChange={e => setSearch(e.target.value)}
                  />
                </div>
                {/* Filter loại */}
                <div className="flex flex-col min-w-[100px]">
                  <label className="text-gray-700 font-medium mb-1 flex items-center gap-1 text-sm" htmlFor="score-type">
                    <FiFilter className="inline" size={14} /> Loại
                  </label>
                  <select
                    id="score-type"
                    className="border px-2 py-1 text-sm focus:ring-2 focus:ring-blue-400 focus:border-blue-400 transition rounded-xl"
                    value={typeFilter}
                    onChange={e => setTypeFilter(e.target.value)}
                  >
                    <option value="">Tất cả</option>
                    <option value="plus">Cộng</option>
                    <option value="minus">Trừ</option>
                  </select>
                </div>
                {/* Filter ngày */}
                <div className="flex flex-col min-w-[120px]">
                  <label className="text-gray-700 font-medium mb-1 flex items-center gap-1 text-sm" htmlFor="score-date">
                    <svg xmlns='http://www.w3.org/2000/svg' className='inline w-4 h-4' fill='none' viewBox='0 0 24 24' stroke='currentColor'><path strokeLinecap='round' strokeLinejoin='round' strokeWidth={2} d='M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z' /></svg> Ngày
                  </label>
                  <input
                    id="score-date"
                    type="date"
                    className="border px-2 py-1 text-sm focus:ring-2 focus:ring-blue-400 focus:border-blue-400 transition rounded-xl"
                    value={dateFilter}
                    onChange={e => setDateFilter(e.target.value)}
                    pattern="(0[1-9]|1[0-2])/[0-3][0-9]/[0-9]{4}"
                  />
                </div>
              </div>
              {pagedScores.length === 0 ? (
                <div className="text-gray-600 text-center py-8 bg-gray-50 rounded-lg shadow">
                  Bạn chưa có lịch sử nhận điểm nào.
                </div>
              ) : (
                <div className="w-full">
                  <ul className="flex flex-col gap-1">
                    {/* Header row */}
                    
                    {pagedScores.map((item) => (
                      <li
                        key={item.scoreID}
                        className="flex items-center px-2 py-2 rounded-xl hover:bg-blue-50 transition text-base group border border-gray-100"
                      >
                        {/* Icon loại điểm */}
                        <span className={`inline-flex items-center justify-center rounded-full w-7 h-7 text-base font-bold mr-2 ${item.actionType === 'plus' ? 'bg-green-100 text-green-600' : 'bg-red-100 text-red-600'}`}>{item.actionType === 'plus' ? '+' : '-'}</span>
                        {/* Ngày */}
                        <span className="min-w-[100px] w-[100px] text-gray-500 text-sm tabular-nums">
                          {item.dateCreate ? new Date(item.dateCreate).toLocaleDateString("vi-VN") : ""}
                        </span>
                        {/* Tên phim */}
                        <span className="flex-1 font-medium text-gray-800 truncate max-w-[180px]" title={item.movieName}>
                          {item.movieName}
                        </span>
                        {/* Loại */}
                        <span className="w-[70px] flex justify-center items-center flex-shrink-0">
                          <span className={`inline-flex items-center justify-center rounded-full px-3 py-0.5 text-sm font-semibold min-w-[48px] ${item.actionType === 'plus' ? 'bg-green-50 text-green-700 border border-green-200' : 'bg-red-50 text-red-700 border border-red-200'}`}>{item.actionType === 'plus' ? 'Cộng' : 'Trừ'}</span>
                        </span>
                        {/* Số điểm */}
                        <span className={`w-[90px] text-right font-bold tabular-nums flex-shrink-0 ${item.actionType === 'plus' ? 'text-green-600' : 'text-red-600'}`}>
                          <span className="text-lg align-middle">{item.actionType === 'plus' ? '+' : '-'}</span>
                          <span className="align-middle">{item.amount}</span>
                          <span className="text-xs font-normal text-gray-400 ml-0.5 align-middle">đ</span>
                        </span>
                      </li>
                    ))}
                  </ul>
                  {/* Pagination + PageSize select nhỏ gọn, nằm trong container, không fixed */}
                  <div className="flex flex-col sm:flex-row sm:items-center justify-between mt-6 gap-2 bg-white rounded-xl border border-blue-100 shadow-sm px-2 py-2">
                    <div className="flex justify-center sm:justify-start gap-1">
                      <button
                        className="px-2 py-1 rounded-md border bg-white hover:bg-blue-50 disabled:opacity-50 flex items-center justify-center text-sm"
                        onClick={() => setPage(p => Math.max(1, p - 1))}
                        disabled={page === 1}
                        aria-label="Trang trước"
                      >
                        <svg width="16" height="16" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" d="M15 19l-7-7 7-7" /></svg>
                      </button>
                      {Array.from({ length: totalPages }, (_, i) => (
                        <button
                          key={i}
                          className={`px-2 py-1 rounded-md border flex items-center justify-center text-sm font-medium ${page === i + 1 ? 'bg-blue-500 text-white border-blue-500' : 'bg-white hover:bg-blue-50'}`}
                          onClick={() => setPage(i + 1)}
                        >
                          {i + 1}
                        </button>
                      ))}
                      <button
                        className="px-2 py-1 rounded-md border bg-white hover:bg-blue-50 disabled:opacity-50 flex items-center justify-center text-sm"
                        onClick={() => setPage(p => Math.min(totalPages, p + 1))}
                        disabled={page === totalPages}
                        aria-label="Trang sau"
                      >
                        <svg width="16" height="16" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" d="M9 5l7 7-7 7" /></svg>
                      </button>
                    </div>
                    <div className="flex justify-center sm:justify-end">
                      <select
                        className="border rounded-md px-2 py-1 text-sm focus:ring-2 focus:ring-blue-400"
                        value={pageSize}
                        onChange={e => setPageSize(Number(e.target.value))}
                      >
                        {PAGE_SIZE_OPTIONS.map(opt => (
                          <option key={opt} value={opt}>{opt} / page</option>
                        ))}
                      </select>
                    </div>
                  </div>
                </div>
              )}
            </div>
          )}

          {activeTab === "voucher" && (
            <div>
              <h2 className="text-2xl font-bold mb-6 text-center text-gray-800">
                Danh sách voucher của bạn
              </h2>
              {vouchers.length === 0 ? (
                <div className="text-gray-600 text-center py-8 bg-gray-50 rounded-lg shadow">
                  Bạn chưa có voucher nào.
                </div>
              ) : (
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                  <AnimatePresence>
                    {vouchers.map((voucher, idx) => (
                      <motion.div
                        key={voucher.promotionId}
                        initial={{ opacity: 0, y: 40 }}
                        animate={{ opacity: 1, y: 0 }}
                        exit={{ opacity: 0, y: 40 }}
                        transition={{ duration: 0.5, delay: idx * 0.08 }}
                        className="relative flex flex-col bg-orange-50 hover:bg-white rounded-2xl shadow-lg border-2 border-transparent hover:border-orange-400 transition-all duration-300 p-2 overflow-hidden group min-h-[100px] cursor-pointer"
                        onClick={() => {
                          setSelectedVoucher(voucher);
                          setShowModal(true);
                        }}
                      >
                        {/* Ảnh voucher */}
                        {voucher.image && (
                          <img
                            src={voucher.image}
                            alt={voucher.title}
                            className="w-full h-24 object-contain rounded-lg mb-1 border bg-white"
                          />
                        )}
                        {/* Badge loại voucher */}
                        <span className={`absolute top-2 right-2 px-2 py-0.5 rounded-full text-xs font-bold tracking-wide shadow-sm
                          ${voucher.promotionType === 'PERCENTAGE' ? 'bg-orange-100 text-orange-600' : 'bg-blue-100 text-blue-600'}`}
                        >
                          {voucher.promotionType === 'PERCENTAGE' ? 'Giảm %' : 'Giảm giá'}
                        </span>
                        {/* Giá trị giảm giá nổi bật */}
                        <div className="flex items-center gap-2 mb-1">
                          <motion.div
                            whileHover={{ scale: 1.1 }}
                            className="text-2xl font-extrabold text-orange-500 drop-shadow-lg group-hover:scale-105 transition-transform duration-200"
                          >
                            {voucher.value}{voucher.promotionType === "PERCENTAGE" ? "%" : "đ"}
                          </motion.div>
                          <div className="flex flex-col">
                            <span className="text-sm font-semibold text-gray-800 line-clamp-1">{voucher.title}</span>
                            <span className="text-xs text-gray-400">Từ: {voucher.startTime ? new Date(voucher.startTime).toLocaleDateString("vi-VN") : ""} - Đến: {voucher.endTime ? new Date(voucher.endTime).toLocaleDateString("vi-VN") : ""}</span>
                          </div>
                        </div>
                        {/* Chi tiết */}
                        <div className="text-xs text-gray-600 mb-1 line-clamp-2">{voucher.detail}</div>
                        {/* Thông tin bổ sung */}
                        {voucher.condition?.minOrderAmount && (
                          <div className="text-xs text-gray-500 italic mb-1">Áp dụng cho đơn từ {voucher.condition.minOrderAmount.toLocaleString()}đ</div>
                        )}
                        {/* Trạng thái */}
                        <div className="mt-auto flex items-center gap-1">
                          <span className={`inline-block w-2 h-2 rounded-full ${voucher.status === 'ACTIVE' ? 'bg-green-500' : 'bg-gray-400'}`}></span>
                          <span className={`text-xs font-semibold ${voucher.status === 'ACTIVE' ? 'text-green-600' : 'text-gray-500'}`}>{voucher.status === 'ACTIVE' ? 'Đang khả dụng' : 'Không khả dụng'}</span>
                        </div>
                      </motion.div>
                    ))}
                  </AnimatePresence>
                </div>
              )}

              <div className="mt-8">
                <h3 className="text-xl font-bold mb-4 text-center text-gray-800">Voucher từ minigame</h3>
                {gameCoupons.length === 0 ? (
                  <div className="text-gray-600 text-center py-6 bg-gray-50 rounded-lg shadow">
                    Bạn chưa nhận voucher minigame nào.
                  </div>
                ) : (
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    {gameCoupons.map((coupon, idx) => (
                      <motion.div
                        key={`${coupon.couponId}-${coupon.receivedAt || idx}`}
                        initial={{ opacity: 0, y: 20 }}
                        animate={{ opacity: 1, y: 0 }}
                        transition={{ duration: 0.35, delay: idx * 0.05 }}
                        className="rounded-xl border border-orange-200 bg-white p-4 shadow-sm"
                      >
                        <div className="flex items-start justify-between gap-2 mb-2">
                          <div>
                            <p className="font-semibold text-gray-800 line-clamp-1">{coupon.name || "Voucher minigame"}</p>
                            <p className="text-xs text-gray-500">
                              Nhận lúc: {coupon.receivedAt ? new Date(coupon.receivedAt).toLocaleString("vi-VN") : "Không rõ"}
                            </p>
                          </div>
                          <span className={`px-2 py-1 rounded-full text-xs font-semibold ${getGameCouponStatusStyle(coupon.status)}`}>
                            {getGameCouponStatusLabel(coupon.status)}
                          </span>
                        </div>

                        <div className="bg-orange-50 border border-orange-200 rounded-lg p-2 mb-2">
                          <p className="text-xs text-gray-500">Mã giảm giá</p>
                          <p className="text-lg font-bold tracking-wide text-orange-600">{coupon.code}</p>
                        </div>

                        <div className="text-sm text-gray-700 space-y-1">
                          <p>
                            Giá trị: {coupon.discountValue}
                            {coupon.discountType === "PERCENTAGE" ? "%" : "đ"}
                          </p>
                          <p>
                            Hết hạn: {coupon.expirationDate ? new Date(coupon.expirationDate).toLocaleDateString("vi-VN") : "Không rõ"}
                          </p>
                        </div>
                      </motion.div>
                    ))}
                  </div>
                )}
              </div>
            </div>
          )}
        </div>
      </div>
    </>
  );
};

export default MyVoucher;

import React, { useState, useEffect, useRef } from "react";
import { useLocation } from "react-router-dom";
import { FiEdit2, FiEye, FiEyeOff, FiUser, FiMail, FiCalendar, FiPhone, FiMapPin, FiAward, FiGift, FiKey, FiChevronRight, FiFilm } from "react-icons/fi";
import { getProfileMember, sendOtpResetPassword, resetPasswordWithOtp } from "../../../service/profile";
import Orders from "./MyOrders/MyOrdered";
import MyVoucher from "./MyVouchers/MyVoucher";
import EditProfile from "./UpdateProfile/UpdateProfile";
import avatarMale from "../../../assets/img/avatar-male.png";
import avatarFemale from "../../../assets/img/avatar-female.png";
import avatarDefault from "../../../assets/img/default-avatar.png";
import { toast } from "react-toastify";
import ParallaxBackground from '../LandingPage/ParallaxBackground';
import { CiSun } from 'react-icons/ci';

const OTP_LENGTH = 6;

const tabList = [
  { key: "profile", label: "Thông tin cá nhân", icon: <FiUser /> },
  { key: "orders", label: "Lịch sử đặt vé", icon: <FiFilm /> },
  { key: "myVoucher", label: "Voucher của tôi", icon: <FiGift /> },
];

const ProfilePage = () => {
  const [activeTab, setActiveTab] = useState("profile");
  const location = useLocation();
  const [formData, setFormData] = useState(null);
  const [isEditing, setIsEditing] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [showResetModal, setShowResetModal] = useState(false);
  const [resetStep, setResetStep] = useState(1);
  const [emailOrUsername, setEmailOrUsername] = useState("");
  const [otp, setOtp] = useState(Array(OTP_LENGTH).fill(""));
  const [newPassword, setNewPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [loading, setLoading] = useState(false);
  const [resetMsg, setResetMsg] = useState("");
  const [showNewPassword, setShowNewPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const inputsRef = useRef([]);
  // Dark mode state synced with localStorage (like LandingPage)
  const [isDarkMode, setIsDarkMode] = useState(() => {
    const stored = localStorage.getItem('landing_dark_mode');
    return stored === 'true';
  });

  // Hàm lấy thông tin tài khoản từ API
  const fetchProfile = async () => {
    try {
      setIsLoading(true);
      const customerID = localStorage.getItem("id") || JSON.parse(localStorage.getItem("user"))?.customerID;
      if (customerID) {
        const profile = await getProfileMember(customerID);
        if (profile) {
          let avatar = profile.avatar || null;
          let gender = profile.sex || localStorage.getItem("gender");
          if (!avatar) {
            if (gender?.toUpperCase() === "MALE") {
              avatar = avatarMale;
            } else if (gender?.toUpperCase() === "FEMALE") {
              avatar = avatarFemale;
            } else {
              avatar = avatarDefault;
            }
          }
          setFormData({
            fullName: profile.fullName || "",
            email: profile.email || "",
            dateOfBirth: profile.dob || "",
            sex: gender || "",
            identityCard: profile.identityCard || "",
            phoneNumber: profile.phone || "",
            address: profile.address || "",
            avatar: avatar,
            // loyalty-related fields removed: score, finalScore, rank, rankImage
            updatedDate: profile.updatedDate || "",
          });
        }
      }
    } catch (err) {
      alert("Không lấy được thông tin cá nhân!");
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchProfile();
    // loyalty feature removed: do not fetch tiers
  }, []);

  useEffect(() => {
    if (location.state && location.state.tab === 'myVoucher') {
      setActiveTab('myVoucher');
      setTimeout(() => {
        const mainContent = document.getElementById('profile-main-content');
        if (mainContent) {
          mainContent.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
      }, 200);
    }
  }, [location.state]);

  // Gửi OTP
  const handleSendOtp = async (e) => {
    e.preventDefault();
    setLoading(true);
    setResetMsg("");
    const res = await sendOtpResetPassword(emailOrUsername);
    setLoading(false);
    if (res && (res.status === "OK" || res.success)) {
      setResetStep(2);
      toast.success("OTP đã được gửi đến email hoặc số điện thoại của bạn.");
    } else {
      setResetMsg(res?.message || "Gửi OTP thất bại.");
    }
  };

  // Đổi mật khẩu
  const handleResetPassword = async (e) => {
    e.preventDefault();
    setResetMsg("");
    const otpValue = otp.join("");
    if (
      otpValue.length !== OTP_LENGTH ||
      !newPassword ||
      !confirmPassword
    ) {
      setResetMsg("Vui lòng nhập đầy đủ thông tin!");
      return;
    }
    if (newPassword.length < 6) {
      setResetMsg("Mật khẩu mới phải có ít nhất 6 ký tự!");
      return;
    }
    if (newPassword !== confirmPassword) {
      setResetMsg("Mật khẩu xác nhận không khớp!");
      return;
    }
    setLoading(true);
    const res = await resetPasswordWithOtp({
      token: otpValue,
      newPassword,
      confirmPassword,
    });
    setLoading(false);
    if (res && (res.status === "OK" || res.success)) {
      toast.success("Đổi mật khẩu thành công!");
      setTimeout(() => setShowResetModal(false), 1500);
    } else {
      setResetMsg(res?.message || "OTP không hợp lệ hoặc có lỗi!");
      setOtp(Array(OTP_LENGTH).fill(""));
      inputsRef.current[0]?.focus();
    }
  };

  const isConfirmMismatch = confirmPassword && newPassword !== confirmPassword;

  // Loyalty/rank UI removed: no client-side rank/tier calculations

  return (
    <div className="relative min-h-screen w-full font-sans" style={{ fontFamily: 'Inter, Montserrat, Roboto, Arial, sans-serif' }}>
      {/* Nút chuyển chế độ sáng/tối giống MovieList/LandingPage */}
      <button
        onClick={() => {
          setIsDarkMode((prev) => {
            localStorage.setItem('landing_dark_mode', !prev);
            return !prev;
          });
        }}
        className="fixed top-20 right-1 z-[10000] w-8 h-8 flex items-center justify-center rounded-full shadow-lg hover:bg-gray-700 transition bg-orange-100 border-gray-600 focus:outline-none"
        aria-label={isDarkMode ? 'Chế độ Sáng' : 'Chế độ Tối'}
        title={isDarkMode ? 'Chế độ Sáng' : 'Chế độ Tối'}
      >
        <CiSun className={`w-7 h-7 transition-colors duration-200 ${isDarkMode ? 'text-black' : 'text-orange-400'}`} />
      </button>
      {/* Lớp phủ hiệu ứng đặt ngoài cùng, dùng ParallaxBackground */}
      <ParallaxBackground isDarkMode={isDarkMode} />
      {/* Main content */}
      <div className="relative z-10 px-1 py-4">
                 <div className="max-w-6xl mx-auto flex flex-col md:flex-row gap-6">
           {/* Sidebar */}
           <aside className="w-full md:w-1/3 bg-white rounded-2xl shadow-xl p-6 flex flex-col items-center border border-[#e5e7eb] overflow-hidden">
            <div className="relative w-24 h-24 mb-4">
              <img
                src={formData?.avatar || avatarDefault}
                alt="Profile"
                className="w-24 h-24 rounded-full object-cover border-2 border-[#FF7120] shadow"
              />
              <button
                className="absolute bottom-1 right-1 bg-[#FF7120] text-white p-2 rounded-full shadow hover:bg-orange-600 transition-all duration-200 border border-white"
                title="Đổi mật khẩu"
                onClick={() => {
                  setShowResetModal(true);
                  setResetStep(1);
                  setEmailOrUsername("");
                  setOtp(Array(OTP_LENGTH).fill(""));
                  setNewPassword("");
                  setConfirmPassword("");
                  setResetMsg("");
                }}
              >
                <FiKey size={18} />
              </button>
            </div>
            {/* Tên */}
            <div className="flex flex-col items-center w-full min-w-0 overflow-x-auto mb-1">
                <div className="flex items-center justify-center w-full min-w-0">
                  <span className="break-all w-full min-w-0 text-lg font-extrabold text-gray-900 text-center">{formData?.fullName || ""}</span>
                </div>
            </div>
                         {/* Email */}
             <div className="flex flex-col items-center w-full min-w-0 overflow-x-auto mb-1">
               <div className="flex items-center justify-center w-full min-w-0">
                 <span className="break-all w-full min-w-0 text-gray-500 text-sm text-center">{formData?.email || ""}</span>
               </div>
             </div>
              {/* Rank/loyalty removed per product decision */}
            <div className="flex flex-col gap-2 w-full mt-1">
              {tabList.map(tab => (
                <button
                  key={tab.key}
                  onClick={() => setActiveTab(tab.key)}
                  className={`flex items-center gap-2 px-3 py-2 rounded-xl font-bold text-sm uppercase tracking-wide transition border shadow-sm ${
                    activeTab === tab.key
                      ? "bg-gradient-to-r from-[#FF7120] to-[#fbbf24] text-white border-[#FF7120] shadow-lg scale-105"
                      : "bg-white text-[#FF7120] border-gray-200 hover:bg-orange-50 hover:scale-105"
                  }`}
                >
                  {tab.icon}
                  {tab.label}
                  {activeTab === tab.key && <FiChevronRight className="ml-auto" />}
                </button>
              ))}
            </div>
          </aside>

          {/* Main content */}
          <main id="profile-main-content" className="flex-1">
            <div className="bg-white rounded-2xl shadow-xl p-5 border border-[#e5e7eb] min-h-[400px]">
              {isLoading ? (
                <div className="flex justify-center items-center h-40">
                  <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-[#FF7120]"></div>
                </div>
              ) : (
                <div
                  key={activeTab}
                  className="transition-all duration-500 ease-out animate-fade-in-slide"
                >
                  {activeTab === "profile" && (
                    <div>
                      <h3 className="text-xl font-extrabold mb-5 text-[#FF7120] flex items-center gap-2 tracking-tight">
                        <FiUser /> Thông tin cá nhân
                      </h3>
                      {formData ? (
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                          <div className="bg-gradient-to-br from-[#fff7f0] to-[#f3f4f6] rounded-xl shadow p-4 border flex flex-col gap-3">
                            {/* Tên */}
                            <div className="flex items-center gap-2 w-full min-w-0 overflow-x-auto mb-1">
                              <FiUser className="text-lg text-[#FF7120]" />
                              <span className="break-all w-full min-w-0 font-semibold text-base">{formData.fullName}</span>
                            </div>
                            <div className="flex items-center gap-2 w-full min-w-0 overflow-x-auto">
                              <FiMail className="text-lg text-[#FF7120]" />
                              <span className="break-words w-full min-w-0">{formData.email}</span>
                            </div>
                            <div className="flex items-center gap-2 w-full min-w-0 overflow-x-auto">
                              <FiCalendar className="text-lg text-[#FF7120]" />
                              <span className="break-words w-full min-w-0">{formData.dateOfBirth}</span>
                            </div>
                            <div className="flex items-center gap-2 w-full min-w-0 overflow-x-auto">
                              <FiUser className="text-lg text-[#FF7120]" />
                              <span className="break-words w-full min-w-0">{formData.sex === "MALE" ? "Nam" : formData.sex === "FEMALE" ? "Nữ" : formData.sex}</span>
                            </div>
                            <div className="flex items-center gap-2 w-full min-w-0 overflow-x-auto">
                              <FiAward className="text-lg text-[#FF7120]" />
                              <span className="break-words w-full min-w-0">{formData.identityCard}</span>
                            </div>
                          </div>
                          <div className="bg-gradient-to-br from-[#f3f4f6] to-[#fff7f0] rounded-xl shadow p-4 border flex flex-col gap-3">
                            <div className="flex items-center gap-2 w-full min-w-0 overflow-x-auto">
                              <FiPhone className="text-lg text-[#FF7120]" />
                              <span className="break-words w-full min-w-0">{formData.phoneNumber}</span>
                            </div>
                            <div className="flex items-center gap-2 w-full min-w-0 overflow-x-auto">
                              <FiMapPin className="text-lg text-[#FF7120]" />
                              <span className="break-words w-full min-w-0">{formData.address}</span>
                            </div>
                            <div className="flex items-center gap-2 w-full min-w-0 overflow-x-auto">
                              <FiCalendar className="text-lg text-[#FF7120]" />
                              <span className="break-words w-full min-w-0">{formData.updatedDate ? new Date(formData.updatedDate).toLocaleString("vi-VN") : ""}</span>
                            </div>
                          </div>
                        </div>
                      ) : (
                        <p className="text-gray-500">Không có thông tin chi tiết để hiển thị.</p>
                      )}
                      <div className="flex justify-end mt-5">
                        <button
                          onClick={() => setIsEditing(true)}
                          className="flex items-center gap-2 px-5 py-2 rounded-xl bg-gradient-to-r from-[#FF7120] to-[#fbbf24] text-white font-bold shadow-lg hover:scale-105 transition-all text-base"
                        >
                          <FiEdit2 /> Chỉnh sửa thông tin
                        </button>
                      </div>
                    </div>
                  )}
                  {activeTab === "orders" && (
                    <div>
                      <h3 className="text-xl font-extrabold mb-5 text-[#FF7120] flex items-center gap-2 tracking-tight">
                        <FiFilm /> Lịch sử đặt vé
                      </h3>
                      <Orders />
                    </div>
                  )}
                  {activeTab === "myVoucher" && (
                    <div>
                      <h3 className="text-xl font-extrabold mb-5 text-[#FF7120] flex items-center gap-2 tracking-tight">
                        <FiGift /> Voucher của tôi
                      </h3>
                      <MyVoucher defaultTab="voucher" />
                    </div>
                  )}
                </div>
              )}
            </div>
          </main>
        </div>
      </div>

      {/* Modal chỉnh sửa thông tin */}
      {isEditing && (
        <EditProfile
          initialData={formData}
          onClose={() => setIsEditing(false)}
          onSuccess={fetchProfile}
        />
      )}

      {/* Modal đổi mật khẩu bằng OTP */}
      {showResetModal && (
        <div className="fixed inset-0 bg-black/40 flex items-center justify-center z-50">
          <div className="bg-white rounded-xl p-5 w-full max-w-md shadow-2xl border border-[#FF7120]">
            <h3 className="text-lg font-extrabold mb-5 text-[#FF7120] flex items-center gap-2"><FiKey /> Đổi mật khẩu bằng OTP</h3>
            {resetStep === 1 && (
              <form className="space-y-4" onSubmit={handleSendOtp}>
                <input
                  type="text"
                  className="w-full border-2 border-blue-200 rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-400"
                  placeholder="Nhập email hoặc username"
                  value={emailOrUsername}
                  onChange={e => setEmailOrUsername(e.target.value)}
                  required
                  disabled={loading}
                />
                <button
                  type="submit"
                  className="w-full text-white py-2 rounded-lg bg-gradient-to-r from-orange-500 to-blue-400 hover:from-orange-600 hover:to-blue-500 font-semibold shadow"
                  disabled={loading || !emailOrUsername}
                >
                  {loading ? "Đang gửi..." : "Gửi OTP"}
                </button>
                {resetMsg && <div className="mt-2 text-sm text-red-600">{resetMsg}</div>}
              </form>
            )}
            {resetStep === 2 && (
              <form className="space-y-4" onSubmit={handleResetPassword}>
                <div className="flex gap-2 mb-2" onPaste={e => {
                  const paste = e.clipboardData.getData("text").replace(/[^0-9]/g, "");
                  if (paste.length === OTP_LENGTH) {
                    setOtp(paste.split(""));
                    inputsRef.current[OTP_LENGTH - 1]?.focus();
                  }
                }}>
                  {otp.map((digit, idx) => (
                    <input
                      key={idx}
                      ref={el => (inputsRef.current[idx] = el)}
                      type="text"
                      inputMode="numeric"
                      maxLength={1}
                      value={digit}
                      onChange={e => {
                        const value = e.target.value.replace(/[^0-9]/g, "");
                        if (!value) return;
                        const newOtp = [...otp];
                        newOtp[idx] = value[0];
                        setOtp(newOtp);
                        if (idx < OTP_LENGTH - 1 && value) {
                          inputsRef.current[idx + 1].focus();
                        }
                      }}
                      onKeyDown={e => {
                        if (e.key === "Backspace") {
                          if (otp[idx]) {
                            const newOtp = [...otp];
                            newOtp[idx] = "";
                            setOtp(newOtp);
                          } else if (idx > 0) {
                            inputsRef.current[idx - 1].focus();
                          }
                        }
                      }}
                      className="w-12 h-12 text-center text-2xl border-2 border-blue-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-400 transition"
                      autoFocus={idx === 0}
                      disabled={loading}
                    />
                  ))}
                </div>
                <div className="relative">
                  <input
                    type={showNewPassword ? "text" : "password"}
                    className="w-full border-2 border-blue-200 rounded-lg px-3 py-2 pr-10 focus:ring-2 focus:ring-blue-400"
                    placeholder="Mật khẩu mới"
                    value={newPassword}
                    onChange={e => setNewPassword(e.target.value)}
                    required
                    disabled={loading}
                  />
                  <button
                    type="button"
                    tabIndex={-1}
                    className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-500"
                    onClick={() => setShowNewPassword(v => !v)}
                    style={{ outline: "none" }}
                  >
                    {showNewPassword ? <FiEyeOff /> : <FiEye />}
                  </button>
                </div>
                <div className="relative">
                  <input
                    type={showConfirmPassword ? "text" : "password"}
                    className="w-full border-2 border-blue-200 rounded-lg px-3 py-2 pr-10 focus:ring-2 focus:ring-blue-400"
                    placeholder="Xác nhận mật khẩu mới"
                    value={confirmPassword}
                    onChange={e => setConfirmPassword(e.target.value)}
                    required
                    disabled={loading}
                  />
                  <button
                    type="button"
                    tabIndex={-1}
                    className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-500"
                    onClick={() => setShowConfirmPassword(v => !v)}
                    style={{ outline: "none" }}
                  >
                    {showConfirmPassword ? <FiEyeOff /> : <FiEye />}
                  </button>
                </div>
                {isConfirmMismatch && (
                  <div className="text-sm text-red-600 -mt-2 mb-2">
                    Mật khẩu xác nhận không khớp!
                  </div>
                )}
                <button
                  type="submit"
                  className="w-full text-white py-2 rounded-lg bg-gradient-to-r from-orange-500 to-blue-400 hover:from-orange-600 hover:to-blue-500 font-semibold shadow"
                  disabled={loading || otp.join("").length !== OTP_LENGTH}
                >
                  {loading ? "Đang đổi..." : "Đổi mật khẩu"}
                </button>
                {resetMsg && <div className="mt-2 text-sm text-red-600">{resetMsg}</div>}
              </form>
            )}
            <div className="flex justify-center mt-4">
              <button
                className="w-full bg-white border-2 border-blue-400 text-blue-700 py-2 rounded-lg hover:bg-blue-50 hover:text-blue-900 transition font-semibold"
                onClick={() => setShowResetModal(false)}
                disabled={loading}
                type="button"
              >
                Đóng
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ProfilePage;

import React, { useState, useEffect, useRef } from "react";
import { useLocation } from "react-router-dom";
import { FiEdit2, FiEye, FiEyeOff, FiUser, FiMail, FiCalendar, FiPhone, FiMapPin, FiAward, FiGift, FiKey, FiChevronRight, FiFilm } from "react-icons/fi";
import { getProfileMember, sendOtpResetPassword, resetPasswordWithOtp } from "../../../service/profile";
import Orders from "./MyOrders/MyOrdered";
import MyVoucher from "./MyVouchers/MyVoucher";
import EditProfile from "./UpdateProfile/UpdateProfile";
import avatarMale from "../../../assets/img/avatar-male.png";
import avatarFemale from "../../../assets/img/avatar-female.png";
import avatarDefault from "../../../assets/img/default-avatar.png";
import { toast } from "react-toastify";
import ParallaxBackground from '../LandingPage/ParallaxBackground';
import { CiSun } from 'react-icons/ci';

const OTP_LENGTH = 6;

const tabList = [
  { key: "profile", label: "Thông tin cá nhân", icon: <FiUser /> },
  { key: "orders", label: "Lịch sử đặt vé", icon: <FiFilm /> },
  { key: "myVoucher", label: "Voucher của tôi", icon: <FiGift /> },
];

const ProfilePage = () => {
  const [activeTab, setActiveTab] = useState("profile");
  const location = useLocation();
  const [formData, setFormData] = useState(null);
  const [isEditing, setIsEditing] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [showResetModal, setShowResetModal] = useState(false);
  const [resetStep, setResetStep] = useState(1);
  const [emailOrUsername, setEmailOrUsername] = useState("");
  const [otp, setOtp] = useState(Array(OTP_LENGTH).fill(""));
  const [newPassword, setNewPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [loading, setLoading] = useState(false);
  const [resetMsg, setResetMsg] = useState("");
  const [showNewPassword, setShowNewPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const inputsRef = useRef([]);
  // Dark mode state synced with localStorage (like LandingPage)
  const [isDarkMode, setIsDarkMode] = useState(() => {
    const stored = localStorage.getItem('landing_dark_mode');
    return stored === 'true';
  });

  // Hàm lấy thông tin tài khoản từ API
  const fetchProfile = async () => {
    try {
      setIsLoading(true);
      const customerID = localStorage.getItem("id") || JSON.parse(localStorage.getItem("user"))?.customerID;
      if (customerID) {
        const profile = await getProfileMember(customerID);
        if (profile) {
          let avatar = profile.avatar || null;
          let gender = profile.sex || localStorage.getItem("gender");
          if (!avatar) {
            if (gender?.toUpperCase() === "MALE") {
              avatar = avatarMale;
            } else if (gender?.toUpperCase() === "FEMALE") {
              avatar = avatarFemale;
            } else {
              avatar = avatarDefault;
            }
          }
          setFormData({
            fullName: profile.fullName || "",
            email: profile.email || "",
            dateOfBirth: profile.dob || "",
            sex: gender || "",
            identityCard: profile.identityCard || "",
            phoneNumber: profile.phone || "",
            address: profile.address || "",
            avatar: avatar,
            // loyalty-related fields removed: score, finalScore, rank, rankImage
            updatedDate: profile.updatedDate || "",
            favoriteGenres: Array.isArray(profile.favoriteGenres) && profile.favoriteGenres.length
              ? profile.favoriteGenres
              : JSON.parse(localStorage.getItem("favoriteGenres") || "[]"),
          });
        }
      }
    } catch (err) {
      alert("Không lấy được thông tin cá nhân!");
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchProfile();
    // loyalty feature removed: do not fetch tiers
  }, []);

  useEffect(() => {
    if (location.state && location.state.tab === 'myVoucher') {
      setActiveTab('myVoucher');
      setTimeout(() => {
        const mainContent = document.getElementById('profile-main-content');
        if (mainContent) {
          mainContent.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
      }, 200);
    }
  }, [location.state]);

  // Gửi OTP
  const handleSendOtp = async (e) => {
    e.preventDefault();
    setLoading(true);
    setResetMsg("");
    const res = await sendOtpResetPassword(emailOrUsername);
    setLoading(false);
    if (res && (res.status === "OK" || res.success)) {
      setResetStep(2);
      toast.success("OTP đã được gửi đến email hoặc số điện thoại của bạn.");
    } else {
      setResetMsg(res?.message || "Gửi OTP thất bại.");
    }
  };

  // Đổi mật khẩu
  const handleResetPassword = async (e) => {
    e.preventDefault();
    setResetMsg("");
    const otpValue = otp.join("");
    if (
      otpValue.length !== OTP_LENGTH ||
      !newPassword ||
      !confirmPassword
    ) {
      setResetMsg("Vui lòng nhập đầy đủ thông tin!");
      return;
    }
    if (newPassword.length < 6) {
      setResetMsg("Mật khẩu mới phải có ít nhất 6 ký tự!");
      return;
    }
    if (newPassword !== confirmPassword) {
      setResetMsg("Mật khẩu xác nhận không khớp!");
      return;
    }
    setLoading(true);
    const res = await resetPasswordWithOtp({
      token: otpValue,
      newPassword,
      confirmPassword,
    });
    setLoading(false);
    if (res && (res.status === "OK" || res.success)) {
      toast.success("Đổi mật khẩu thành công!");
      setTimeout(() => setShowResetModal(false), 1500);
    } else {
      setResetMsg(res?.message || "OTP không hợp lệ hoặc có lỗi!");
      setOtp(Array(OTP_LENGTH).fill(""));
      inputsRef.current[0]?.focus();
    }
  };

  const isConfirmMismatch = confirmPassword && newPassword !== confirmPassword;

  // Loyalty/rank UI removed: no client-side rank/tier calculations

  return (
    <div className="relative min-h-screen w-full font-sans" style={{ fontFamily: 'Inter, Montserrat, Roboto, Arial, sans-serif' }}>
      {/* Nút chuyển chế độ sáng/tối giống MovieList/LandingPage */}
      <button
        onClick={() => {
          setIsDarkMode((prev) => {
            localStorage.setItem('landing_dark_mode', !prev);
            return !prev;
          });
        }}
        className="fixed top-20 right-1 z-[10000] w-8 h-8 flex items-center justify-center rounded-full shadow-lg hover:bg-gray-700 transition bg-orange-100 border-gray-600 focus:outline-none"
        aria-label={isDarkMode ? 'Chế độ Sáng' : 'Chế độ Tối'}
        title={isDarkMode ? 'Chế độ Sáng' : 'Chế độ Tối'}
      >
        <CiSun className={`w-7 h-7 transition-colors duration-200 ${isDarkMode ? 'text-black' : 'text-orange-400'}`} />
      </button>
      {/* Lớp phủ hiệu ứng đặt ngoài cùng, dùng ParallaxBackground */}
      <ParallaxBackground isDarkMode={isDarkMode} />
      {/* Main content */}
      <div className="relative z-10 px-1 py-4">
                 <div className="max-w-6xl mx-auto flex flex-col md:flex-row gap-6">
           {/* Sidebar */}
           <aside className="w-full md:w-1/3 bg-white rounded-2xl shadow-xl p-6 flex flex-col items-center border border-[#e5e7eb] overflow-hidden">
            <div className="relative w-24 h-24 mb-4">
              <img
                src={formData?.avatar || avatarDefault}
                alt="Profile"
                className="w-24 h-24 rounded-full object-cover border-2 border-[#FF7120] shadow"
              />
              <button
                className="absolute bottom-1 right-1 bg-[#FF7120] text-white p-2 rounded-full shadow hover:bg-orange-600 transition-all duration-200 border border-white"
                title="Đổi mật khẩu"
                onClick={() => {
                  setShowResetModal(true);
                  setResetStep(1);
                  setEmailOrUsername("");
                  setOtp(Array(OTP_LENGTH).fill(""));
                  setNewPassword("");
                  setConfirmPassword("");
                  setResetMsg("");
                }}
              >
                <FiKey size={18} />
              </button>
            </div>
            {/* Tên */}
            <div className="flex flex-col items-center w-full min-w-0 overflow-x-auto mb-1">
                <div className="flex items-center justify-center w-full min-w-0">
                  <span className="break-all w-full min-w-0 text-lg font-extrabold text-gray-900 text-center">{formData?.fullName || ""}</span>
                </div>
            </div>
                         {/* Email */}
             <div className="flex flex-col items-center w-full min-w-0 overflow-x-auto mb-1">
               <div className="flex items-center justify-center w-full min-w-0">
                 <span className="break-all w-full min-w-0 text-gray-500 text-sm text-center">{formData?.email || ""}</span>
               </div>
             </div>
              {/* Rank/loyalty removed per product decision */}
            <div className="flex flex-col gap-2 w-full mt-1">
              {tabList.map(tab => (
                <button
                  key={tab.key}
                  onClick={() => setActiveTab(tab.key)}
                  className={`flex items-center gap-2 px-3 py-2 rounded-xl font-bold text-sm uppercase tracking-wide transition border shadow-sm ${
                    activeTab === tab.key
                      ? "bg-gradient-to-r from-[#FF7120] to-[#fbbf24] text-white border-[#FF7120] shadow-lg scale-105"
                      : "bg-white text-[#FF7120] border-gray-200 hover:bg-orange-50 hover:scale-105"
                  }`}
                >
                  {tab.icon}
                  {tab.label}
                  {activeTab === tab.key && <FiChevronRight className="ml-auto" />}
                </button>
              ))}
            </div>
          </aside>

          {/* Main content */}
          <main id="profile-main-content" className="flex-1">
            <div className="bg-white rounded-2xl shadow-xl p-5 border border-[#e5e7eb] min-h-[400px]">
              {isLoading ? (
                <div className="flex justify-center items-center h-40">
                  <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-[#FF7120]"></div>
                </div>
              ) : (
                <div
                  key={activeTab}
                  className="transition-all duration-500 ease-out animate-fade-in-slide"
                >
                  {activeTab === "profile" && (
                    <div>
                      <h3 className="text-xl font-extrabold mb-5 text-[#FF7120] flex items-center gap-2 tracking-tight">
                        <FiUser /> Thông tin cá nhân
                      </h3>
                      {formData ? (
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                          <div className="bg-gradient-to-br from-[#fff7f0] to-[#f3f4f6] rounded-xl shadow p-4 border flex flex-col gap-3">
                            {/* Tên */}
                            <div className="flex items-center gap-2 w-full min-w-0 overflow-x-auto mb-1">
                              <FiUser className="text-lg text-[#FF7120]" />
                              <span className="break-all w-full min-w-0 font-semibold text-base">{formData.fullName}</span>
                            </div>
                            <div className="flex items-center gap-2 w-full min-w-0 overflow-x-auto">
                              <FiMail className="text-lg text-[#FF7120]" />
                              <span className="break-words w-full min-w-0">{formData.email}</span>
                            </div>
                            <div className="flex items-center gap-2 w-full min-w-0 overflow-x-auto">
                              <FiCalendar className="text-lg text-[#FF7120]" />
                              <span className="break-words w-full min-w-0">{formData.dateOfBirth}</span>
                            </div>
                            <div className="flex items-center gap-2 w-full min-w-0 overflow-x-auto">
                              <FiUser className="text-lg text-[#FF7120]" />
                              <span className="break-words w-full min-w-0">{formData.sex === "MALE" ? "Nam" : formData.sex === "FEMALE" ? "Nữ" : formData.sex}</span>
                            </div>
                            <div className="flex items-center gap-2 w-full min-w-0 overflow-x-auto">
                              <FiAward className="text-lg text-[#FF7120]" />
                              <span className="break-words w-full min-w-0">{formData.identityCard}</span>
                            </div>
                          </div>
                          <div className="bg-gradient-to-br from-[#f3f4f6] to-[#fff7f0] rounded-xl shadow p-4 border flex flex-col gap-3">
                            <div className="flex items-center gap-2 w-full min-w-0 overflow-x-auto">
                              <FiPhone className="text-lg text-[#FF7120]" />
                              <span className="break-words w-full min-w-0">{formData.phoneNumber}</span>
                            </div>
                            <div className="flex items-center gap-2 w-full min-w-0 overflow-x-auto">
                              <FiMapPin className="text-lg text-[#FF7120]" />
                              <span className="break-words w-full min-w-0">{formData.address}</span>
                            </div>
                            <div className="flex items-start gap-2 w-full min-w-0 overflow-x-auto">
                              <FiFilm className="text-lg text-[#FF7120] mt-1" />
                              <span className="break-words w-full min-w-0">
                                {(formData.favoriteGenres || []).length
                                  ? formData.favoriteGenres.join(", ")
                                  : "Chưa chọn thể loại yêu thích"}
                              </span>
                            </div>
                            <div className="flex items-center gap-2 w-full min-w-0 overflow-x-auto">
                              <FiCalendar className="text-lg text-[#FF7120]" />
                              <span className="break-words w-full min-w-0">{formData.updatedDate ? new Date(formData.updatedDate).toLocaleString("vi-VN") : ""}</span>
                            </div>
                          </div>
                        </div>
                      ) : (
                        <p className="text-gray-500">Không có thông tin chi tiết để hiển thị.</p>
                      )}
                      <div className="flex justify-end mt-5">
                        <button
                          onClick={() => setIsEditing(true)}
                          className="flex items-center gap-2 px-5 py-2 rounded-xl bg-gradient-to-r from-[#FF7120] to-[#fbbf24] text-white font-bold shadow-lg hover:scale-105 transition-all text-base"
                        >
                          <FiEdit2 /> Chỉnh sửa thông tin
                        </button>
                      </div>
                    </div>
                  )}
                  {activeTab === "orders" && (
                    <div>
                      <h3 className="text-xl font-extrabold mb-5 text-[#FF7120] flex items-center gap-2 tracking-tight">
                        <FiFilm /> Lịch sử đặt vé
                      </h3>
                      <Orders />
                    </div>
                  )}
                  {activeTab === "myVoucher" && (
                    <div>
                      <h3 className="text-xl font-extrabold mb-5 text-[#FF7120] flex items-center gap-2 tracking-tight">
                        <FiGift /> Voucher của tôi
                      </h3>
                      <MyVoucher defaultTab="voucher" />
                    </div>
                  )}
                </div>
              )}
            </div>
          </main>
        </div>
      </div>

      {/* Modal chỉnh sửa thông tin */}
      {isEditing && (
        <EditProfile
          initialData={formData}
          onClose={() => setIsEditing(false)}
          onSuccess={fetchProfile}
        />
      )}

      {/* Modal đổi mật khẩu bằng OTP */}
      {showResetModal && (
        <div className="fixed inset-0 bg-black/40 flex items-center justify-center z-50">
          <div className="bg-white rounded-xl p-5 w-full max-w-md shadow-2xl border border-[#FF7120]">
            <h3 className="text-lg font-extrabold mb-5 text-[#FF7120] flex items-center gap-2"><FiKey /> Đổi mật khẩu bằng OTP</h3>
            {resetStep === 1 && (
              <form className="space-y-4" onSubmit={handleSendOtp}>
                <input
                  type="text"
                  className="w-full border-2 border-blue-200 rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-400"
                  placeholder="Nhập email hoặc username"
                  value={emailOrUsername}
                  onChange={e => setEmailOrUsername(e.target.value)}
                  required
                  disabled={loading}
                />
                <button
                  type="submit"
                  className="w-full text-white py-2 rounded-lg bg-gradient-to-r from-orange-500 to-blue-400 hover:from-orange-600 hover:to-blue-500 font-semibold shadow"
                  disabled={loading || !emailOrUsername}
                >
                  {loading ? "Đang gửi..." : "Gửi OTP"}
                </button>
                {resetMsg && <div className="mt-2 text-sm text-red-600">{resetMsg}</div>}
              </form>
            )}
            {resetStep === 2 && (
              <form className="space-y-4" onSubmit={handleResetPassword}>
                <div className="flex gap-2 mb-2" onPaste={e => {
                  const paste = e.clipboardData.getData("text").replace(/[^0-9]/g, "");
                  if (paste.length === OTP_LENGTH) {
                    setOtp(paste.split(""));
                    inputsRef.current[OTP_LENGTH - 1]?.focus();
                  }
                }}>
                  {otp.map((digit, idx) => (
                    <input
                      key={idx}
                      ref={el => (inputsRef.current[idx] = el)}
                      type="text"
                      inputMode="numeric"
                      maxLength={1}
                      value={digit}
                      onChange={e => {
                        const value = e.target.value.replace(/[^0-9]/g, "");
                        if (!value) return;
                        const newOtp = [...otp];
                        newOtp[idx] = value[0];
                        setOtp(newOtp);
                        if (idx < OTP_LENGTH - 1 && value) {
                          inputsRef.current[idx + 1].focus();
                        }
                      }}
                      onKeyDown={e => {
                        if (e.key === "Backspace") {
                          if (otp[idx]) {
                            const newOtp = [...otp];
                            newOtp[idx] = "";
                            setOtp(newOtp);
                          } else if (idx > 0) {
                            inputsRef.current[idx - 1].focus();
                          }
                        }
                      }}
                      className="w-12 h-12 text-center text-2xl border-2 border-blue-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-400 transition"
                      autoFocus={idx === 0}
                      disabled={loading}
                    />
                  ))}
                </div>
                <div className="relative">
                  <input
                    type={showNewPassword ? "text" : "password"}
                    className="w-full border-2 border-blue-200 rounded-lg px-3 py-2 pr-10 focus:ring-2 focus:ring-blue-400"
                    placeholder="Mật khẩu mới"
                    value={newPassword}
                    onChange={e => setNewPassword(e.target.value)}
                    required
                    disabled={loading}
                  />
                  <button
                    type="button"
                    tabIndex={-1}
                    className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-500"
                    onClick={() => setShowNewPassword(v => !v)}
                    style={{ outline: "none" }}
                  >
                    {showNewPassword ? <FiEyeOff /> : <FiEye />}
                  </button>
                </div>
                <div className="relative">
                  <input
                    type={showConfirmPassword ? "text" : "password"}
                    className="w-full border-2 border-blue-200 rounded-lg px-3 py-2 pr-10 focus:ring-2 focus:ring-blue-400"
                    placeholder="Xác nhận mật khẩu mới"
                    value={confirmPassword}
                    onChange={e => setConfirmPassword(e.target.value)}
                    required
                    disabled={loading}
                  />
                  <button
                    type="button"
                    tabIndex={-1}
                    className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-500"
                    onClick={() => setShowConfirmPassword(v => !v)}
                    style={{ outline: "none" }}
                  >
                    {showConfirmPassword ? <FiEyeOff /> : <FiEye />}
                  </button>
                </div>
                {isConfirmMismatch && (
                  <div className="text-sm text-red-600 -mt-2 mb-2">
                    Mật khẩu xác nhận không khớp!
                  </div>
                )}
                <button
                  type="submit"
                  className="w-full text-white py-2 rounded-lg bg-gradient-to-r from-orange-500 to-blue-400 hover:from-orange-600 hover:to-blue-500 font-semibold shadow"
                  disabled={loading || otp.join("").length !== OTP_LENGTH}
                >
                  {loading ? "Đang đổi..." : "Đổi mật khẩu"}
                </button>
                {resetMsg && <div className="mt-2 text-sm text-red-600">{resetMsg}</div>}
              </form>
            )}
            <div className="flex justify-center mt-4">
              <button
                className="w-full bg-white border-2 border-blue-400 text-blue-700 py-2 rounded-lg hover:bg-blue-50 hover:text-blue-900 transition font-semibold"
                onClick={() => setShowResetModal(false)}
                disabled={loading}
                type="button"
              >
                Đóng
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ProfilePage;

import React, { useState } from "react";
import ReactDOM from "react-dom";
import { FiX, FiUser, FiMail, FiCalendar, FiPhone, FiMapPin, FiAward } from "react-icons/fi";
import { updateProfile } from "../../../../service/profile";
import { toast } from "react-toastify";

// Validate helpers
function isIdentityCardValid(identityCard) {
  return /^\d{9}$|^\d{12}$/.test(identityCard);
}
function isPhoneValid(phone) {
  return /^0\d{8,10}$/.test(phone);
}
function isEmailValid(email) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
}

const EditProfile = ({
  initialData,
  onClose,
  onSuccess,
}) => {
  const [formData, setFormData] = useState(initialData);
  const [loading, setLoading] = useState(false);
  const [errors, setErrors] = useState({});

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: value,
    }));
    setErrors((prev) => ({ ...prev, [name]: undefined }));
  };

  const validate = () => {
    const newErrors = {};
    if (!formData.fullName) newErrors.fullName = "Họ và tên không được để trống";
    if (formData.email && !isEmailValid(formData.email)) newErrors.email = "Email không hợp lệ";
    if (formData.identityCard && !isIdentityCardValid(formData.identityCard)) newErrors.identityCard = "CMND/CCCD phải có 9 hoặc 12 số";
    if (formData.phoneNumber && !isPhoneValid(formData.phoneNumber)) newErrors.phoneNumber = "Số điện thoại phải 10 số, bắt đầu bằng 0";
    if (!formData.dateOfBirth) newErrors.dateOfBirth = "Ngày sinh không được để trống";
    if (!formData.sex) newErrors.sex = "Giới tính không được để trống";
    if (!formData.address) newErrors.address = "Địa chỉ không được để trống";
    return newErrors;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const newErrors = validate();
    setErrors(newErrors);
    if (Object.keys(newErrors).length > 0) return;
    setLoading(true);
    try {
      const result = await updateProfile(formData);
      if (result && result.success) {
        if (onSuccess) onSuccess();
        onClose();
        toast.success("Cập nhật thông tin thành công!", {
          icon: "✅",
          position: "top-right",
          autoClose: 2000,
        });
      } else {
        toast.error("Cập nhật thông tin thất bại.", {
          icon: "❗",
          position: "top-right",
          autoClose: 2000,
        });
      }
    } catch (error) {
      toast.error("Cập nhật thông tin thất bại.", {
        icon: "❗",
        position: "top-right",
        autoClose: 2000,
      });
    } finally {
      setLoading(false);
    }
  };

  return ReactDOM.createPortal(
    <div className="fixed inset-0 bg-black/40 flex items-center justify-center z-[9999]" style={{ fontFamily: 'Inter, Montserrat, Roboto, Arial, sans-serif' }}>
      <div className="bg-white rounded-2xl p-8 w-full max-w-lg shadow-2xl border-2 border-[#FF7120]" style={{ maxHeight: "90vh", overflowY: "auto" }}>
        <div className="flex justify-between items-center mb-6">
          <h3 className="text-2xl font-extrabold text-[#FF7120] flex items-center gap-2">
            <FiUser /> Chỉnh sửa thông tin
          </h3>
          <button onClick={onClose} className="text-gray-400 hover:text-[#FF7120] transition">
            <FiX size={28} />
          </button>
        </div>
        <form onSubmit={handleSubmit} className="space-y-5">
          <div>
            <label className="text-[#FF7120] font-semibold mb-1 flex items-center gap-2"><FiUser /> Họ và tên</label>
            <input
              type="text"
              name="fullName"
              value={formData.fullName || ""}
              onChange={handleChange}
              className="w-full border-2 border-[#FF7120] rounded-xl px-4 py-2 text-base focus:ring-2 focus:ring-[#FF7120] focus:border-[#FF7120]"
              required
            />
            {errors.fullName && <p className="text-red-500 text-sm mt-1">{errors.fullName}</p>}
          </div>
          <div>
            <label className="text-[#FF7120] font-semibold mb-1 flex items-center gap-2"><FiCalendar /> Ngày sinh</label>
            <input
              type="date"
              name="dateOfBirth"
              value={formData.dateOfBirth || ""}
              onChange={handleChange}
              className="w-full border-2 border-[#FF7120] rounded-xl px-4 py-2 text-base focus:ring-2 focus:ring-[#FF7120] focus:border-[#FF7120]"
              required
            />
            {errors.dateOfBirth && <p className="text-red-500 text-sm mt-1">{errors.dateOfBirth}</p>}
          </div>
          <div>
            <label className="text-[#FF7120] font-semibold mb-1 flex items-center gap-2"><FiUser /> Giới tính</label>
            <select
              name="sex"
              value={formData.sex || ""}
              onChange={handleChange}
              className="w-full border-2 border-[#FF7120] rounded-xl px-4 py-2 text-base focus:ring-2 focus:ring-[#FF7120] focus:border-[#FF7120]"
              required
            >
              <option value="MALE">Nam</option>
              <option value="FEMALE">Nữ</option>
            </select>
            {errors.sex && <p className="text-red-500 text-sm mt-1">{errors.sex}</p>}
          </div>
          <div>
            <label className="text-[#FF7120] font-semibold mb-1 flex items-center gap-2"><FiAward /> CMND/CCCD</label>
            <input
              type="text"
              name="identityCard"
              value={formData.identityCard || ""}
              onChange={handleChange}
              className="w-full border-2 border-[#FF7120] rounded-xl px-4 py-2 text-base focus:ring-2 focus:ring-[#FF7120] focus:border-[#FF7120]"
            />
            {formData.identityCard && !isIdentityCardValid(formData.identityCard) && (
              <p className="text-red-500 text-sm mt-1">
                CMND/CCCD phải có 9 hoặc 12 số.
              </p>
            )}
            {errors.identityCard && <p className="text-red-500 text-sm mt-1">{errors.identityCard}</p>}
          </div>
          <div>
            <label className="text-[#FF7120] font-semibold mb-1 flex items-center gap-2"><FiMail /> Email</label>
            <input
              type="email"
              name="email"
              value={formData.email || ""}
              onChange={handleChange}
              className="w-full border-2 border-[#FF7120] rounded-xl px-4 py-2 text-base focus:ring-2 focus:ring-[#FF7120] focus:border-[#FF7120]"
            />
            {errors.email && <p className="text-red-500 text-sm mt-1">{errors.email}</p>}
          </div>
          <div>
            <label className="text-[#FF7120] font-semibold mb-1 flex items-center gap-2"><FiMapPin /> Địa chỉ</label>
            <input
              type="text"
              name="address"
              value={formData.address || ""}
              onChange={handleChange}
              className="w-full border-2 border-[#FF7120] rounded-xl px-4 py-2 text-base focus:ring-2 focus:ring-[#FF7120] focus:border-[#FF7120]"
              required
            />
            {errors.address && <p className="text-red-500 text-sm mt-1">{errors.address}</p>}
          </div>
          <div>
            <label className="text-[#FF7120] font-semibold mb-1 flex items-center gap-2"><FiPhone /> Số điện thoại</label>
            <input
              type="text"
              name="phoneNumber"
              value={formData.phoneNumber || ""}
              onChange={(e) =>
                setFormData((prev) => ({
                  ...prev,
                  phoneNumber: e.target.value.replace(/\D/g, ""),
                }))
              }
              className="w-full border-2 border-[#FF7120] rounded-xl px-4 py-2 text-base focus:ring-2 focus:ring-[#FF7120] focus:border-[#FF7120]"
              minLength={9}
              maxLength={11}
            />
            {formData.phoneNumber && !isPhoneValid(formData.phoneNumber) && (
              <p className="text-red-500 text-sm mt-1">
                Số điện thoại phải từ 9 đến 11 số.
              </p>
            )}
            {errors.phoneNumber && <p className="text-red-500 text-sm mt-1">{errors.phoneNumber}</p>}
          </div>
          <div className="flex gap-4 pt-6">
            <button
              type="button"
              onClick={onClose}
              className="flex-1 px-4 py-3 border-2 border-[#FF7120] text-[#FF7120] rounded-xl font-bold bg-white hover:bg-orange-50 hover:text-orange-700 transition text-base shadow"
              disabled={loading}
            >
              Hủy
            </button>
            <button
              type="submit"
              className="flex-1 px-4 py-3 text-white rounded-xl font-bold bg-gradient-to-r from-[#FF7120] to-[#fbbf24] hover:from-orange-600 hover:to-yellow-400 transition text-base shadow"
              disabled={loading}
            >
              {loading ? "Đang lưu..." : "Lưu thay đổi"}
            </button>
          </div>
        </form>
      </div>
    </div>,
    document.body
  );
};

export default EditProfile;

import React, { useState } from "react";
import ReactDOM from "react-dom";
import { FiX, FiUser, FiMail, FiCalendar, FiPhone, FiMapPin, FiAward, FiFilm } from "react-icons/fi";
import { updateProfile } from "../../../../service/profile";
import { toast } from "react-toastify";

const GENRE_OPTIONS = [
  "Hành động",
  "Phiêu lưu",
  "Kinh dị",
  "Tình cảm",
  "Hài",
  "Hoạt hình",
  "Khoa học viễn tưởng",
  "Tâm lý",
  "Gia đình",
  "Thần thoại",
];

// Validate helpers
function isIdentityCardValid(identityCard) {
  return /^\d{9}$|^\d{12}$/.test(identityCard);
}
function isPhoneValid(phone) {
  return /^0\d{8,10}$/.test(phone);
}
function isEmailValid(email) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
}

const EditProfile = ({
  initialData,
  onClose,
  onSuccess,
}) => {
  const initialFavoriteGenres = Array.isArray(initialData?.favoriteGenres) && initialData.favoriteGenres.length
    ? initialData.favoriteGenres
    : JSON.parse(localStorage.getItem("favoriteGenres") || "[]");

  const [formData, setFormData] = useState({
    ...initialData,
    favoriteGenres: initialFavoriteGenres,
  });
  const [loading, setLoading] = useState(false);
  const [errors, setErrors] = useState({});

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: value,
    }));
    setErrors((prev) => ({ ...prev, [name]: undefined }));
  };

  const handleGenreChange = (e) => {
    const selectedValues = Array.from(e.target.selectedOptions).map((option) => option.value);
    setFormData((prev) => ({
      ...prev,
      favoriteGenres: selectedValues,
    }));
  };

  const validate = () => {
    const newErrors = {};
    if (!formData.fullName) newErrors.fullName = "Họ và tên không được để trống";
    if (formData.email && !isEmailValid(formData.email)) newErrors.email = "Email không hợp lệ";
    if (formData.identityCard && !isIdentityCardValid(formData.identityCard)) newErrors.identityCard = "CMND/CCCD phải có 9 hoặc 12 số";
    if (formData.phoneNumber && !isPhoneValid(formData.phoneNumber)) newErrors.phoneNumber = "Số điện thoại phải 10 số, bắt đầu bằng 0";
    if (!formData.dateOfBirth) newErrors.dateOfBirth = "Ngày sinh không được để trống";
    if (!formData.sex) newErrors.sex = "Giới tính không được để trống";
    if (!formData.address) newErrors.address = "Địa chỉ không được để trống";
    return newErrors;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const newErrors = validate();
    setErrors(newErrors);
    if (Object.keys(newErrors).length > 0) return;
    setLoading(true);
    try {
      const favoriteGenres = Array.isArray(formData.favoriteGenres)
        ? formData.favoriteGenres
        : [];

      localStorage.setItem("favoriteGenres", JSON.stringify(favoriteGenres));
      window.dispatchEvent(new Event("favoriteGenresUpdated"));

      const payload = {
        fullName: formData.fullName,
        dateOfBirth: formData.dateOfBirth,
        sex: formData.sex,
        email: formData.email,
        identityCard: formData.identityCard,
        phoneNumber: formData.phoneNumber,
        address: formData.address,
        favoriteGenres,
      };

      const result = await updateProfile(payload);
      if (result && result.success) {
        if (onSuccess) onSuccess();
        onClose();
        toast.success("Cập nhật thông tin thành công!", {
          icon: "✅",
          position: "top-right",
          autoClose: 2000,
        });
      } else {
        toast.error(result?.message || "Cập nhật thông tin thất bại.", {
          icon: "❗",
          position: "top-right",
          autoClose: 2000,
        });
      }
    } catch (error) {
      toast.error("Cập nhật thông tin thất bại.", {
        icon: "❗",
        position: "top-right",
        autoClose: 2000,
      });
    } finally {
      setLoading(false);
    }
  };

  return ReactDOM.createPortal(
    <div className="fixed inset-0 bg-black/40 flex items-center justify-center z-[9999]" style={{ fontFamily: 'Inter, Montserrat, Roboto, Arial, sans-serif' }}>
      <div className="bg-white rounded-2xl p-8 w-full max-w-lg shadow-2xl border-2 border-[#FF7120]" style={{ maxHeight: "90vh", overflowY: "auto" }}>
        <div className="flex justify-between items-center mb-6">
          <h3 className="text-2xl font-extrabold text-[#FF7120] flex items-center gap-2">
            <FiUser /> Chỉnh sửa thông tin
          </h3>
          <button onClick={onClose} className="text-gray-400 hover:text-[#FF7120] transition">
            <FiX size={28} />
          </button>
        </div>
        <form onSubmit={handleSubmit} className="space-y-5">
          <div>
            <label className="text-[#FF7120] font-semibold mb-1 flex items-center gap-2"><FiUser /> Họ và tên</label>
            <input
              type="text"
              name="fullName"
              value={formData.fullName || ""}
              onChange={handleChange}
              className="w-full border-2 border-[#FF7120] rounded-xl px-4 py-2 text-base focus:ring-2 focus:ring-[#FF7120] focus:border-[#FF7120]"
              required
            />
            {errors.fullName && <p className="text-red-500 text-sm mt-1">{errors.fullName}</p>}
          </div>
          <div>
            <label className="text-[#FF7120] font-semibold mb-1 flex items-center gap-2"><FiCalendar /> Ngày sinh</label>
            <input
              type="date"
              name="dateOfBirth"
              value={formData.dateOfBirth || ""}
              onChange={handleChange}
              className="w-full border-2 border-[#FF7120] rounded-xl px-4 py-2 text-base focus:ring-2 focus:ring-[#FF7120] focus:border-[#FF7120]"
              required
            />
            {errors.dateOfBirth && <p className="text-red-500 text-sm mt-1">{errors.dateOfBirth}</p>}
          </div>
          <div>
            <label className="text-[#FF7120] font-semibold mb-1 flex items-center gap-2"><FiUser /> Giới tính</label>
            <select
              name="sex"
              value={formData.sex || ""}
              onChange={handleChange}
              className="w-full border-2 border-[#FF7120] rounded-xl px-4 py-2 text-base focus:ring-2 focus:ring-[#FF7120] focus:border-[#FF7120]"
              required
            >
              <option value="MALE">Nam</option>
              <option value="FEMALE">Nữ</option>
            </select>
            {errors.sex && <p className="text-red-500 text-sm mt-1">{errors.sex}</p>}
          </div>
          <div>
            <label className="text-[#FF7120] font-semibold mb-1 flex items-center gap-2"><FiAward /> CMND/CCCD</label>
            <input
              type="text"
              name="identityCard"
              value={formData.identityCard || ""}
              onChange={handleChange}
              className="w-full border-2 border-[#FF7120] rounded-xl px-4 py-2 text-base focus:ring-2 focus:ring-[#FF7120] focus:border-[#FF7120]"
            />
            {formData.identityCard && !isIdentityCardValid(formData.identityCard) && (
              <p className="text-red-500 text-sm mt-1">
                CMND/CCCD phải có 9 hoặc 12 số.
              </p>
            )}
            {errors.identityCard && <p className="text-red-500 text-sm mt-1">{errors.identityCard}</p>}
          </div>
          <div>
            <label className="text-[#FF7120] font-semibold mb-1 flex items-center gap-2"><FiMail /> Email</label>
            <input
              type="email"
              name="email"
              value={formData.email || ""}
              onChange={handleChange}
              className="w-full border-2 border-[#FF7120] rounded-xl px-4 py-2 text-base focus:ring-2 focus:ring-[#FF7120] focus:border-[#FF7120]"
            />
            {errors.email && <p className="text-red-500 text-sm mt-1">{errors.email}</p>}
          </div>
          <div>
            <label className="text-[#FF7120] font-semibold mb-1 flex items-center gap-2"><FiMapPin /> Địa chỉ</label>
            <input
              type="text"
              name="address"
              value={formData.address || ""}
              onChange={handleChange}
              className="w-full border-2 border-[#FF7120] rounded-xl px-4 py-2 text-base focus:ring-2 focus:ring-[#FF7120] focus:border-[#FF7120]"
              required
            />
            {errors.address && <p className="text-red-500 text-sm mt-1">{errors.address}</p>}
          </div>
          <div>
            <label className="text-[#FF7120] font-semibold mb-1 flex items-center gap-2"><FiFilm /> Thể loại yêu thích</label>
            <select
              multiple
              value={formData.favoriteGenres || []}
              onChange={handleGenreChange}
              className="w-full border-2 border-[#FF7120] rounded-xl px-4 py-2 text-base focus:ring-2 focus:ring-[#FF7120] focus:border-[#FF7120] min-h-[120px]"
            >
              {GENRE_OPTIONS.map((genre) => (
                <option key={genre} value={genre}>
                  {genre}
                </option>
              ))}
            </select>
            <p className="text-xs text-gray-500 mt-1">Giữ Ctrl (hoặc Cmd trên Mac) để chọn nhiều thể loại.</p>
          </div>
          <div>
            <label className="text-[#FF7120] font-semibold mb-1 flex items-center gap-2"><FiPhone /> Số điện thoại</label>
            <input
              type="text"
              name="phoneNumber"
              value={formData.phoneNumber || ""}
              onChange={(e) =>
                setFormData((prev) => ({
                  ...prev,
                  phoneNumber: e.target.value.replace(/\D/g, ""),
                }))
              }
              className="w-full border-2 border-[#FF7120] rounded-xl px-4 py-2 text-base focus:ring-2 focus:ring-[#FF7120] focus:border-[#FF7120]"
              minLength={9}
              maxLength={11}
            />
            {formData.phoneNumber && !isPhoneValid(formData.phoneNumber) && (
              <p className="text-red-500 text-sm mt-1">
                Số điện thoại phải từ 9 đến 11 số.
              </p>
            )}
            {errors.phoneNumber && <p className="text-red-500 text-sm mt-1">{errors.phoneNumber}</p>}
          </div>
          <div className="flex gap-4 pt-6">
            <button
              type="button"
              onClick={onClose}
              className="flex-1 px-4 py-3 border-2 border-[#FF7120] text-[#FF7120] rounded-xl font-bold bg-white hover:bg-orange-50 hover:text-orange-700 transition text-base shadow"
              disabled={loading}
            >
              Hủy
            </button>
            <button
              type="submit"
              className="flex-1 px-4 py-3 text-white rounded-xl font-bold bg-gradient-to-r from-[#FF7120] to-[#fbbf24] hover:from-orange-600 hover:to-yellow-400 transition text-base shadow"
              disabled={loading}
            >
              {loading ? "Đang lưu..." : "Lưu thay đổi"}
            </button>
          </div>
        </form>
      </div>
    </div>,
    document.body
  );
};

