import { instance } from "../instance";

const getAdminToken = () => {
  const adminUser = JSON.parse(localStorage.getItem("adminUser") || "{}");
  return adminUser.token || localStorage.getItem("token") || "";
};

const authConfig = () => ({
  headers: {
    Authorization: `Bearer ${getAdminToken()}`,
  },
});

export const getAllCinemas = async () => {
  try {
    const response = await instance.get("/admin/cinemas", authConfig());
    return {
      success: response.data.success,
      data: response.data.data || [],
      message: response.data.message,
    };
  } catch (error) {
    return {
      success: false,
      data: [],
      message: error.response?.data?.message || "Khong the lay danh sach rap phim",
    };
  }
};

export const getAllCities = async () => {
  try {
    const response = await instance.get("/admin/cinemas/cities", authConfig());
    return {
      success: response.data.success,
      data: response.data.data || [],
      message: response.data.message,
    };
  } catch (error) {
    return {
      success: false,
      data: [],
      message: error.response?.data?.message || "Khong the lay danh sach thanh pho",
    };
  }
};

export const createCinema = async ({ name, address, cityId }) => {
  try {
    const response = await instance.post(
      "/admin/cinemas",
      { name, address, cityId },
      authConfig()
    );

    return {
      success: response.data.success,
      data: response.data.data,
      message: response.data.message,
    };
  } catch (error) {
    return {
      success: false,
      data: null,
      message: error.response?.data?.message || "Khong the tao rap phim",
    };
  }
};

export const updateCinema = async (cinemaId, { name, address, cityId }) => {
  try {
    const response = await instance.put(
      `/admin/cinemas/${cinemaId}`,
      { name, address, cityId },
      authConfig()
    );

    return {
      success: response.data.success,
      data: response.data.data,
      message: response.data.message,
    };
  } catch (error) {
    return {
      success: false,
      data: null,
      message: error.response?.data?.message || "Khong the cap nhat rap phim",
    };
  }
};

export const deleteCinema = async (cinemaId) => {
  try {
    const response = await instance.delete(`/admin/cinemas/${cinemaId}`, authConfig());

    return {
      success: response.data.success,
      data: response.data.data,
      message: response.data.message,
    };
  } catch (error) {
    return {
      success: false,
      data: null,
      message: error.response?.data?.message || "Khong the xoa rap phim",
    };
  }
};

import { instance } from "../instance";


 // Lấy tất cả phòng chiếu trong hệ thống
export const getAllCinemaRooms = async () => {
  const adminUser = JSON.parse(localStorage.getItem("adminUser") || "{}");
  const token = adminUser.token;
  try {
    const response = await instance.get("/admin/cinema-rooms", {
      headers: {
        Authorization: `Bearer ${token}`,
      },
    });
    return {
      success: response.data.success,
      data: response.data.data,
      message: response.data.message,
    };
  } catch (error) {
    return {
      success: false,
      data: [],
      message: error.response?.data?.message || "Không thể lấy danh sách phòng chiếu",
    };
  }
};

// Bật/tắt trạng thái phòng chiếu
export const setActiveCinemaRoom = async (cinemaRoomId, active) => {
  const adminUser = JSON.parse(localStorage.getItem("adminUser") || "{}");
  const token = adminUser.token;
  try {
    const response = await instance.put(
      `/admin/cinema-rooms/${cinemaRoomId}/set-active?active=${active}`,
      {},
      {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      }
    );
    return {
      success: response.data.success,
      message: response.data.message,
    };
  } catch (error) {
    return {
      success: false,
      message: error.response?.data?.message || "Không thể cập nhật trạng thái phòng chiếu",
    };
  }
};

// Tạo phòng chiếu mới
export const createCinemaRoom = async ({ roomName, seatQuantity, cinemaId }) => {
  const adminUser = JSON.parse(localStorage.getItem("adminUser") || "{}");
  const token = adminUser.token;
  try {
    const response = await instance.post(
      "/admin/cinema-rooms",
      { roomName, seatQuantity, cinemaId },
      {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      }
    );
    return {
      success: response.data.success,
      data: response.data.data,
      message: response.data.message,
    };
  } catch (error) {
    return {
      success: false,
      data: null,
      message: error.response?.data?.message || "Không thể tạo phòng chiếu",
    };
  }
};

// Xóa phòng chiếu
export const deleteCinemaRoom = async (cinemaRoomId) => {
  const adminUser = JSON.parse(localStorage.getItem("adminUser") || "{}");
